import { afterEach, beforeEach, describe, it, test } from "node:test";

const globals = globalThis as typeof globalThis & {
  afterEach?: typeof afterEach;
  beforeEach?: typeof beforeEach;
  describe?: typeof describe;
  it?: typeof it;
  test?: typeof test;
};

globals.afterEach ??= afterEach;
globals.beforeEach ??= beforeEach;
globals.describe ??= describe;
globals.it ??= it;
globals.test ??= test;

import assert from "node:assert/strict";
import { Context } from "../src/core/Context.js";
import { AutonomousOrchestrator } from "../src/runtime/AutonomousOrchestrator.js";
import { EngineRegistry } from "../src/runtime/EngineRegistry.js";
import { AgentMeshEngine } from "../src/agents/AgentMeshEngine.js";

async function main(): Promise<void> {
  const context = new Context({
    projectRoot: process.cwd(),
    projectName: "mesh-test",
    nodeVersion: process.version,
    pnpmVersion: "9.0.0",
    typescriptVersion: "5.8.3",
    prismaVersion: "5.0.0",
    nextVersion: "14.0.0",
    issues: [],
    recommendations: [],
    metadata: { root: process.cwd(), idea: "mesh" },
  });

  const registry = new EngineRegistry();
  const orchestrator = new AutonomousOrchestrator(registry);
  const mesh = new AgentMeshEngine(orchestrator);
  await mesh.run(context);

  const agentMesh = (context.metadata as Record<string, unknown>).agentMesh as { history?: Array<{ agent: string; status: string; confidence: number }> } | undefined;
  assert.ok(agentMesh?.history && agentMesh.history.length > 0);
  assert.ok(registry.resolve("architectagent"));
  assert.ok(registry.resolve("backendagent"));
  console.log("agent mesh test passed");
}

void main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

import crypto from "node:crypto";
import type { Issue } from "./Issue.js";
import type { IssueSummary } from "./IssueSummary.js";
import type { ProjectMetadata } from "./ProjectMetadata.js";
import type { Diagnosis } from "../diagnostic/Diagnosis.js";
import type { RootCause } from "../rootcause/RootCause.js";
import type { RepairPlan } from "../planner/RepairPlan.js";
import type { HealthSummary } from "../health/HealthSummary.js";

export interface RepairOptions {
  dryRun?: boolean;
  maxSteps?: number;
}

export interface RepairLogEntry {
  id: string;
  planId?: string;
  rootCauseId?: string;
  stepId?: string;
  title: string;
  status: "applied" | "dry-run" | "skipped" | "failed";
  message: string;
  filePath?: string;
  timestamp: string;
  rollbackStatus?: "none" | "restored" | "failed";
  retryCount?: number;
}

export interface RepairLoopState {
  attempt: number;
  completed: boolean;
  reason?: string;
}

export interface ContextParams {
  projectRoot: string;
  projectName: string;
  nodeVersion: string;
  pnpmVersion: string;
  typescriptVersion: string;
  prismaVersion: string;
  nextVersion: string;
  issues: Issue[];
  recommendations: string[];
  metadata: ProjectMetadata;
  diagnosis?: Diagnosis[];
  rootCauses?: RootCause[];
  repairPlans?: RepairPlan[];
  repairOptions?: RepairOptions;
  repairLog?: RepairLogEntry[];
  repairLoop?: RepairLoopState;
  repairSummary?: {
    beforeIssueCount?: number;
    afterIssueCount?: number;
    beforeHealth?: number;
    afterHealth?: number;
    fixedIssueCount?: number;
    remainingIssueCount?: number;
    durationMs?: number;
    rollbackStatus?: "none" | "restored" | "failed";
    beforeIssueIds?: string[];
    afterIssueIds?: string[];
    resolvedIssueIds?: string[];
    remainingIssueIds?: string[];
    failedIssueIds?: string[];
    repairStatus?: string;
    repairAttemptCount?: number;
    actualRepairAction?: string;
    verificationPassed?: boolean;
    verificationReasons?: string[];
  };
  health?: HealthSummary | null;
  verification?: unknown;
}

export class Context {
  projectRoot: string;
  projectName: string;
  nodeVersion: string;
  pnpmVersion: string;
  typescriptVersion: string;
  prismaVersion: string;
  nextVersion: string;
  issues: Issue[];
  recommendations: string[];
  metadata: ProjectMetadata;
  diagnosis?: Diagnosis[];
  rootCauses?: RootCause[];
  repairPlans?: RepairPlan[];
  repairOptions?: RepairOptions;
  repairLog?: RepairLogEntry[];
  repairLoop?: RepairLoopState;
  repairSummary?: {
    beforeIssueCount?: number;
    afterIssueCount?: number;
    beforeHealth?: number;
    afterHealth?: number;
    fixedIssueCount?: number;
    remainingIssueCount?: number;
    durationMs?: number;
    rollbackStatus?: "none" | "restored" | "failed";
    beforeIssueIds?: string[];
    afterIssueIds?: string[];
    resolvedIssueIds?: string[];
    remainingIssueIds?: string[];
    failedIssueIds?: string[];
    repairStatus?: string;
    repairAttemptCount?: number;
    actualRepairAction?: string;
    verificationPassed?: boolean;
    verificationReasons?: string[];
  };
  health?: HealthSummary | null;
  verification?: unknown;

  constructor(params: ContextParams) {
    this.projectRoot = params.projectRoot;
    this.projectName = params.projectName;
    this.nodeVersion = params.nodeVersion;
    this.pnpmVersion = params.pnpmVersion;
    this.typescriptVersion = params.typescriptVersion;
    this.prismaVersion = params.prismaVersion;
    this.nextVersion = params.nextVersion;
    this.issues = params.issues;
    this.recommendations = params.recommendations;
    this.metadata = params.metadata;
    this.diagnosis = params.diagnosis;
    this.rootCauses = params.rootCauses;
    this.repairPlans = params.repairPlans;
    this.repairOptions = params.repairOptions;
    this.repairLog = params.repairLog ?? [];
    this.repairLoop = params.repairLoop;
    this.repairSummary = params.repairSummary;
    this.health = params.health ?? null;
    this.verification = params.verification;
  }

  addIssue(issue: Issue): void {
    const normalizedIssue = this.normalizeIssue(issue);
    const duplicate = this.issues.some(
      (existing) => existing.id === normalizedIssue.id && existing.message === normalizedIssue.message
    );

    if (!duplicate) {
      this.issues.push(normalizedIssue);
    }
  }

  getIssues(): readonly Issue[] {
    return [...this.issues].sort((left, right) => left.id.localeCompare(right.id));
  }

  private normalizeIssue(issue: Issue): Issue {
    const normalizedMessage = this.normalizeText(issue.message);
    const ruleId = this.normalizeText(issue.ruleId ?? issue.id);
    const file = this.normalizeText(issue.file ?? "unknown-file");
    const line = typeof issue.line === "number" ? String(issue.line) : "0";
    const hash = crypto.createHash("sha256").update(`${ruleId}|${file}|${line}|${normalizedMessage}`, "utf8").digest("hex").slice(0, 12);
    const deterministicId = `${ruleId}-${file}-${line}-${hash}`;

    return {
      ...issue,
      id: deterministicId,
      message: issue.message,
    };
  }

  private normalizeText(value: string): string {
    return value
      .trim()
      .toLowerCase()
      .replace(/\\+/g, "/")
      .replace(/[^a-z0-9./_-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "");
  }

  getSummary(): IssueSummary {
    const summary: IssueSummary = {
      total: 0,
      info: 0,
      warning: 0,
      error: 0,
      critical: 0,
      byCategory: {},
      bySeverity: {},
    };

    for (const issue of this.issues) {
      summary.total += 1;

      const severity = issue.severity.toLowerCase();
      if (severity === "critical") {
        summary.critical += 1;
      } else if (severity === "error") {
        summary.error += 1;
      } else if (severity === "warning") {
        summary.warning += 1;
      } else if (severity === "info") {
        summary.info += 1;
      }

      summary.byCategory[issue.category] = (summary.byCategory[issue.category] ?? 0) + 1;
      summary.bySeverity[issue.severity] = (summary.bySeverity[issue.severity] ?? 0) + 1;
    }

    return summary;
  }
}

import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { FactoryRuntime } from "../doctor/FactoryRuntime.js";
import { EngineRegistry } from "./EngineRegistry.js";
import { ExecutionGraph } from "./ExecutionGraph.js";
import { RuntimeMonitor } from "./RuntimeMonitor.js";
import { EventBus } from "../doctor/EventBus.js";
import { ProjectReasonerEngine, IntentAnalyzerEngine, DomainAnalyzerEngine, FeaturePlannerEngine, ConstraintAnalyzerEngine, ArchitectureReasonerEngine, TaskBreakdownEngine, PromptCompilerEngine, ReflectionEngine, CriticEngine, ConfidenceEngine } from "../ai/engines/ReasoningBrainEngines.js";
import { PlannerEngine } from "../ai/engines/PlannerEngine.js";
import { ArchitectureEngine } from "../ai/engines/ArchitectureEngine.js";
import { DatabaseGenerator } from "../ai/engines/DatabaseGenerator.js";
import { BackendGenerator } from "../ai/engines/BackendGenerator.js";
import { FrontendGenerator } from "../ai/engines/FrontendGenerator.js";
import { TestingGenerator } from "../ai/engines/TestingGenerator.js";
import { BuildLoopEngine } from "../doctor/BuildLoopEngine.js";
import { RepairMemoryEngine } from "../doctor/RepairMemoryEngine.js";
import { KnowledgeGraphEngine } from "../doctor/KnowledgeGraphEngine.js";
import { BenchmarkEngine } from "../benchmark/BenchmarkEngine.js";
import { ProductionValidator } from "../validation/ProductionValidator.js";
import { SelfEvolutionEngine } from "../selfevolution/SelfEvolutionEngine.js";
import { DashboardRuntime } from "./DashboardRuntime.js";
import { AgentMeshEngine } from "../agents/AgentMeshEngine.js";

class ProductionValidatorAdapter implements IEngine {
  public readonly name = "ProductionValidatorAdapter";

  constructor(private readonly inner = new ProductionValidator()) {}

  async run(context: Context): Promise<void> {
    await this.inner.run(context);
  }
}

export interface OrchestratorState {
  executionGraph: ReturnType<ExecutionGraph["createGraph"]>;
  metrics: ReturnType<RuntimeMonitor["collect"]>;
  status: string;
  phase: string;
}

export class AutonomousOrchestrator implements IEngine {
  public readonly name = "AutonomousOrchestrator";

  constructor(
    private readonly engineRegistry: EngineRegistry = new EngineRegistry(),
    private readonly executionGraph: ExecutionGraph = new ExecutionGraph(),
    private readonly monitor: RuntimeMonitor = new RuntimeMonitor(),
    private readonly eventBus: EventBus = new EventBus(),
    private readonly engines: IEngine[] = []
  ) {}

  registerEngine(engine: IEngine): void {
    this.engineRegistry.register(engine);
  }

  async run(context: Context): Promise<void> {
    await this.execute(context, this.engines.length > 0 ? this.engines : this.buildDefaultEngines());
  }

  async execute(context: Context, engines: IEngine[] = []): Promise<OrchestratorState> {
    const runtimeEngines = engines.length > 0 ? engines : this.buildDefaultEngines();
    for (const engine of runtimeEngines) {
      this.engineRegistry.register(engine);
    }

    const graph = this.executionGraph.createGraph(runtimeEngines);
    const runtime = new FactoryRuntime(context, { engines: runtimeEngines });
    await runtime.run();

    const metrics = this.monitor.collect(context, {
      durationMs: 1,
      benchmarkScore: 80,
      qualityScore: 85,
      healthScore: 90,
    });

    const dashboard = new DashboardRuntime();
    const agentMesh = (context.metadata as Record<string, unknown>).agentMesh as { history?: Array<{ agent: string; status: string; confidence: number }> } | undefined;
    context.metadata = {
      ...context.metadata,
      dashboardSnapshot: dashboard.getSnapshot(context, metrics, graph),
      runtimeGraph: graph,
      agentMesh: agentMesh ?? { queue: [], history: [], progress: 0, durationMs: 0, confidence: 0 },
    } as typeof context.metadata & { dashboardSnapshot?: unknown; runtimeGraph?: typeof graph; agentMesh?: unknown };

    this.eventBus.emit({ type: "RuntimeCompleted", timestamp: new Date().toISOString(), stage: "Doctor", engine: "AutonomousOrchestrator" });
    return { executionGraph: graph, metrics, status: "completed", phase: "validation" };
  }

  private buildDefaultEngines(): IEngine[] {
    return [
      new ProjectReasonerEngine(),
      new IntentAnalyzerEngine(),
      new DomainAnalyzerEngine(),
      new FeaturePlannerEngine(),
      new ConstraintAnalyzerEngine(),
      new ArchitectureReasonerEngine(),
      new TaskBreakdownEngine(),
      new PromptCompilerEngine(),
      new ReflectionEngine(),
      new CriticEngine(),
      new ConfidenceEngine(),
      new PlannerEngine(),
      new ArchitectureEngine(),
      new DatabaseGenerator(),
      new BackendGenerator(),
      new FrontendGenerator(),
      new TestingGenerator(),
      new BuildLoopEngine(),
      new RepairMemoryEngine(),
      new KnowledgeGraphEngine(),
      new BenchmarkEngine(),
      new ProductionValidatorAdapter(),
      new SelfEvolutionEngine(),
    ];
  }
}

import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { HistoryEngine } from "../history/HistoryEngine.js";
import { EventBus } from "./EventBus.js";
import { RuntimeKernel, type RuntimeKernelEvent } from "../runtime/RuntimeKernel.js";

export interface RuntimeEvent extends RuntimeKernelEvent {}

export interface FactoryRuntimeOptions {
  engines: IEngine[];
  maxRetries?: number;
}

export class FactoryRuntime {
  private readonly history: HistoryEngine;
  private readonly events: RuntimeEvent[] = [];
  private readonly eventBus: EventBus;
  private readonly kernel: RuntimeKernel;

  constructor(private readonly context: Context, options: FactoryRuntimeOptions) {
    this.history = new HistoryEngine(this.context.projectRoot);
    this.eventBus = new EventBus();
    this.kernel = new RuntimeKernel(this.context, {
      engines: options.engines,
      maxRetries: options.maxRetries,
      history: this.history,
      eventBus: this.eventBus,
      onEvent: (event) => {
        this.events.push(event);
      },
    });
  }

  async run(): Promise<void> {
    await this.kernel.run();
    this.context.metadata = {
      ...this.context.metadata,
      historyEvents: this.events,
    } as typeof this.context.metadata & { historyEvents?: RuntimeEvent[] };
  }
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { HistoryManager } from "./HistoryManager.js";
import type { Context } from "../core/Context.js";
import { ProjectFingerprintCalculator } from "../core/ProjectFingerprint.js";
import type { HistoryRecord } from "./History.js";

export class HistoryEngine {
  private readonly manager: HistoryManager;
  private readonly fingerprintCalculator = new ProjectFingerprintCalculator();

  constructor(root: string) {
    this.manager = new HistoryManager(root);
  }

  save(context: Context, durationMs: number): void {
    const fingerprint = this.fingerprintCalculator.generate(context);
    const scanId = this.manager.nextScanId(fingerprint.hash);
    const record: HistoryRecord = {
      scanId,
      projectName: context.projectName,
      fingerprint,
      timestamp: new Date().toISOString(),
      durationMs,
      doctorVersion: this.getDoctorVersion(),
      health: context.health ?? null,
      issues: [...context.getIssues()].sort((left, right) => left.id.localeCompare(right.id)),
      diagnosis: context.diagnosis?.slice().sort((left, right) => (left.id ?? "").localeCompare(right.id ?? "")),
      rootCauses: context.rootCauses?.slice().sort((left, right) => left.id.localeCompare(right.id)),
      repairPlans: context.repairPlans?.slice().sort((left, right) => left.id.localeCompare(right.id)),
      repairLog: context.repairLog?.slice(),
      repairLoop: context.repairLoop,
      repairSummary: context.repairSummary,
      verification: context.verification,
      metadata: context.metadata,
    };
    this.manager.save(record);
  }

  load(scanId: string) {
    return this.manager.load(scanId);
  }

  latest() {
    return this.manager.latest();
  }

  list() {
    return this.manager.list();
  }

  compare(scanA: string, scanB: string) {
    return this.manager.compare(scanA, scanB);
  }

  private getDoctorVersion(): string {
    try {
      const packagePath = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "package.json");
      const content = fs.readFileSync(packagePath, "utf8");
      const pkg = JSON.parse(content) as { version?: string };
      return pkg.version ?? "unknown";
    } catch {
      return "unknown";
    }
  }
}

import { HistoryRepository } from "./HistoryRepository.js";
import type { HistoryComparison, HistoryRecord } from "./History.js";

export class HistoryManager {
  private readonly repository: HistoryRepository;

  constructor(root: string) {
    this.repository = new HistoryRepository(root);
  }

  save(record: HistoryRecord): void {
    this.repository.save(record);
  }

  load(scanId: string): HistoryRecord | null {
    return this.repository.load(scanId);
  }

  latest(): HistoryRecord | null {
    return this.repository.latest();
  }

  list(): HistoryRecord[] {
    return this.repository.list();
  }

  compare(scanA: string, scanB: string): HistoryComparison | null {
    return this.repository.compare(scanA, scanB);
  }

  nextScanId(fingerprintHash: string): string {
    return this.repository.nextScanId(fingerprintHash);
  }
}

import fs from "node:fs";
import path from "node:path";
import type { HistoryComparison, HistoryRecord } from "./History.js";
import { HistorySerializer } from "./HistorySerializer.js";

export class HistoryRepository {
  private readonly root: string;
  private readonly serializer = new HistorySerializer();

  constructor(root: string) {
    this.root = root;
  }

  save(record: HistoryRecord): void {
    const historyDir = this.ensureHistoryDirectory(record.fingerprint.hash);
    const fileName = `scan-${record.scanId.padStart(6, "0")}.json`;
    const filePath = path.join(historyDir, fileName);
    fs.writeFileSync(filePath, this.serializer.serialize(record), "utf8");
  }

  load(scanId: string): HistoryRecord | null {
    const historyDirs = this.getFingerprintDirectories();
    for (const dir of historyDirs) {
      const filePath = path.join(dir, `scan-${scanId.padStart(6, "0")}.json`);
      if (fs.existsSync(filePath)) {
        return this.serializer.deserialize(fs.readFileSync(filePath, "utf8"));
      }
    }
    return null;
  }

  latest(): HistoryRecord | null {
    const historyDirs = this.getFingerprintDirectories();
    let latestRecord: HistoryRecord | null = null;

    for (const dir of historyDirs) {
      const files = fs.readdirSync(dir).filter((name) => /^scan-\d{6}\.json$/.test(name)).sort().reverse();
      if (files.length === 0) continue;
      const record = this.serializer.deserialize(fs.readFileSync(path.join(dir, files[0]), "utf8"));
      if (!latestRecord || new Date(record.timestamp) > new Date(latestRecord.timestamp)) {
        latestRecord = record;
      }
    }

    return latestRecord;
  }

  list(): HistoryRecord[] {
    const records: HistoryRecord[] = [];
    const historyDirs = this.getFingerprintDirectories();
    for (const dir of historyDirs) {
      const files = fs.readdirSync(dir).filter((name) => /^scan-\d{6}\.json$/.test(name)).sort();
      for (const file of files) {
        records.push(this.serializer.deserialize(fs.readFileSync(path.join(dir, file), "utf8")));
      }
    }
    return records;
  }

  compare(scanA: string, scanB: string): HistoryComparison | null {
    const recordA = this.load(scanA);
    const recordB = this.load(scanB);
    if (!recordA || !recordB) return null;

    const differences: Record<string, { a: unknown; b: unknown }> = {};
    const keys = new Set([...Object.keys(recordA), ...Object.keys(recordB)]);
    for (const key of keys) {
      const aValue = (recordA as unknown as Record<string, unknown>)[key];
      const bValue = (recordB as unknown as Record<string, unknown>)[key];
      if (JSON.stringify(aValue) !== JSON.stringify(bValue)) {
        differences[key] = { a: aValue, b: bValue };
      }
    }

    const issueKey = (issue: { id: string; message: string }) => `${issue.id}::${issue.message}`;
    const issueMapA = new Map(recordA.issues.map((issue) => [issueKey(issue), issue]));
    const issueMapB = new Map(recordB.issues.map((issue) => [issueKey(issue), issue]));

    const newIssues = recordB.issues.filter((issue) => !issueMapA.has(issueKey(issue)));
    const fixedIssues = recordA.issues.filter((issue) => !issueMapB.has(issueKey(issue)));
    const unchangedIssues = recordB.issues.filter((issue) => issueMapA.has(issueKey(issue)));

    const healthDelta = (recordB.health?.score ?? 0) - (recordA.health?.score ?? 0);
    const scoreDelta = healthDelta;
    const severityDelta = unchangedIssues.filter((issue) => {
      const previous = issueMapA.get(issueKey(issue));
      return previous ? previous.severity !== issue.severity : false;
    }).length;

    return {
      scanA,
      scanB,
      sameFingerprint: recordA.fingerprint.hash === recordB.fingerprint.hash,
      differences,
      newIssues,
      fixedIssues,
      unchangedIssues,
      healthDelta,
      scoreDelta,
      severityDelta,
    };
  }

  nextScanId(fingerprintHash: string): string {
    const historyDir = path.join(this.getHistoryRoot(), fingerprintHash);
    if (!fs.existsSync(historyDir)) {
      return "1";
    }

    const files = fs.readdirSync(historyDir).filter((name) => /^scan-\d{6}\.json$/.test(name));
    const highest = files
      .map((file) => Number(file.replace(/^scan-(\d{6})\.json$/, "$1")))
      .filter(Number.isFinite)
      .sort((a, b) => b - a)[0];

    return highest ? String(highest + 1) : "1";
  }

  private ensureHistoryDirectory(fingerprintHash: string): string {
    const historyRoot = this.getHistoryRoot();
    const fingerprintDir = path.join(historyRoot, fingerprintHash);
    if (!fs.existsSync(historyRoot)) {
      fs.mkdirSync(historyRoot, { recursive: true });
    }
    if (!fs.existsSync(fingerprintDir)) {
      fs.mkdirSync(fingerprintDir, { recursive: true });
    }
    return fingerprintDir;
  }

  private getHistoryRoot(): string {
    return path.join(this.root, ".history");
  }

  private getFingerprintDirectories(): string[] {
    const historyRoot = this.getHistoryRoot();
    if (!fs.existsSync(historyRoot)) return [];
    return fs.readdirSync(historyRoot)
      .map((name) => path.join(historyRoot, name))
      .filter((dir) => fs.statSync(dir).isDirectory());
  }
}

import stringify from "json-stable-stringify";
import type { HistoryRecord } from "./History.js";

export class HistorySerializer {
  serialize(record: HistoryRecord): string {
    const result = stringify(record as unknown as object, { space: 2 });
    return typeof result === "string" ? result : JSON.stringify(record, null, 2);
  }

  deserialize(content: string): HistoryRecord {
    return JSON.parse(content) as HistoryRecord;
  }
}

import crypto from "crypto";
import fs from "node:fs";
import path from "node:path";
import type { Context } from "./Context.js";

export interface ProjectFingerprint {
  framework: string | null;
  packageManager: string | null;
  workspace: boolean;
  typescript: string | null;
  react: string | null;
  next: string | null;
  prisma: string | null;
  tailwind: string | null;
  turbo: string | null;
  database: string | null;
  nodeVersion: string | null;
  dependencyCount: number;
  workspaceCount: number;
  trackedFileCount: number;
  trackedFilesHash: string;
  hash: string;
  signature: string;
}

export class ProjectFingerprintCalculator {
  public generate(context: Context): ProjectFingerprint {
    const metadata = context.metadata as Record<string, unknown>;

    const framework = this.getFramework(metadata);
    const packageManager = this.getPackageManager(metadata);
    const workspacePackages = this.getWorkspacePackages(metadata);
    const typescript = this.getVersion(metadata.typescript as Record<string, unknown> | null, "version");
    const react = this.getVersion(metadata.react as Record<string, unknown> | null, "reactVersion");
    const next = this.getVersion(metadata.next as Record<string, unknown> | null, "nextVersion");
    const prisma = this.getVersion(metadata.prisma as Record<string, unknown> | null, "prismaVersion");
    const tailwind = this.getVersion(metadata.tailwind as Record<string, unknown> | null, "version");
    const turbo = this.getVersion(metadata.turbo as Record<string, unknown> | null, "packageManager");
    const database = this.getDatabase(metadata);
    const nodeVersion = typeof context.nodeVersion === "string" ? context.nodeVersion : null;
    const dependencyCount = this.getDependencyCount(metadata);
    const workspaceCount = workspacePackages.length;
    const trackedFiles = this.collectMeaningfulFiles(context.projectRoot);
    const trackedFileCount = trackedFiles.length;
    const trackedFilesHash = this.createStableHash(trackedFiles);

    const fingerprintPayload = {
      framework,
      packageManager,
      workspace: workspaceCount > 0,
      typescript,
      react,
      next,
      prisma,
      tailwind,
      turbo,
      database,
      nodeVersion,
      dependencyCount,
      workspaceCount,
      trackedFileCount,
      trackedFilesHash,
    };

    const hash = this.createStableHash(fingerprintPayload);
    const signature = `${framework ?? "unknown"}:${packageManager ?? "unknown"}:${hash}`;

    return {
      ...fingerprintPayload,
      hash,
      signature,
    };
  }

  private getFramework(metadata: Record<string, unknown>): string | null {
    if (this.hasMetadata(metadata.next)) {
      return "next";
    }
    if (this.hasMetadata(metadata.react)) {
      return "react";
    }
    if (this.hasMetadata(metadata.tailwind)) {
      return "tailwind";
    }
    if (this.hasMetadata(metadata.turbo)) {
      return "turbo";
    }
    return null;
  }

  private getPackageManager(metadata: Record<string, unknown>): string | null {
    if (typeof metadata.packageManager === "string") {
      return metadata.packageManager;
    }
    const pnpm = metadata.pnpm as Record<string, unknown> | null;
    if (pnpm && typeof pnpm.packageManager === "string") {
      return pnpm.packageManager;
    }
    return null;
  }

  private getWorkspacePackages(metadata: Record<string, unknown>): string[] {
    const pnpm = metadata.pnpm as Record<string, unknown> | null;
    if (pnpm && Array.isArray(pnpm.workspacePackages)) {
      return pnpm.workspacePackages.map(String);
    }

    const packageJson = metadata.packageJson as Record<string, unknown> | null;
    if (!packageJson) {
      return [];
    }

    const workspaces = packageJson.workspaces;
    if (Array.isArray(workspaces)) {
      return workspaces.map(String);
    }
    if (workspaces && typeof workspaces === "object" && Array.isArray((workspaces as Record<string, unknown>).packages)) {
      return ((workspaces as Record<string, unknown>).packages as unknown[]).map(String);
    }

    return [];
  }

  private getVersion(metadata: Record<string, unknown> | null, key: string): string | null {
    if (!metadata || typeof metadata !== "object") {
      return null;
    }
    const value = metadata[key as keyof typeof metadata];
    return typeof value === "string" ? value : null;
  }

  private getDatabase(metadata: Record<string, unknown>): string | null {
    const prisma = metadata.prisma as Record<string, unknown> | null;
    if (prisma && this.getVersion(prisma, "prismaVersion")) {
      return "prisma";
    }

    const environment = metadata.environment as Record<string, unknown> | null;
    if (environment && environment.hasOwnProperty("hasDatabaseUrl") && environment.hasOwnProperty("hasSupabaseUrl")) {
      if (environment.hasOwnProperty("hasSupabaseUrl") && (environment.hasOwnProperty("hasSupabaseUrl") as unknown)) {
        return "supabase";
      }
      if (environment.hasOwnProperty("hasDatabaseUrl")) {
        return "database";
      }
    }

    return null;
  }

  private getDependencyCount(metadata: Record<string, unknown>): number {
    const dependencies = metadata.dependencies as Record<string, unknown> | null;
    if (dependencies && typeof dependencies.totalPackages === "number") {
      return dependencies.totalPackages;
    }
    return 0;
  }

  private collectMeaningfulFiles(projectRoot: string): Array<{ relativePath: string; hash: string }> {
    const trackedFiles: Array<{ relativePath: string; hash: string }> = [];
    const queue = [projectRoot];
    const ignoredDirectories = new Set([".git", ".history", ".next", ".turbo", ".cache", "node_modules", "dist", "build", "coverage", "out"]);
    const ignoredFiles = new Set([".DS_Store", "Thumbs.db", "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml"]);
    const includedExtensions = new Set([".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".json", ".yaml", ".yml", ".toml", ".prisma", ".env"]);
    const includedFiles = new Set(["package.json", "pnpm-workspace.yaml", "turbo.json", "tsconfig.json", "postcss.config.js", "postcss.config.cjs", "postcss.config.mjs", "postcss.config.ts", "tailwind.config.js", "tailwind.config.cjs", "tailwind.config.mjs", "tailwind.config.ts", "next.config.js", "next.config.cjs", "next.config.mjs", "next.config.ts"]);

    while (queue.length > 0) {
      const currentPath = queue.shift();
      if (!currentPath) continue;

      let entries: fs.Dirent[];
      try {
        entries = fs.readdirSync(currentPath, { withFileTypes: true });
      } catch {
        continue;
      }

      for (const entry of entries) {
        const absolutePath = path.join(currentPath, entry.name);
        if (entry.isDirectory()) {
          if (!ignoredDirectories.has(entry.name)) {
            queue.push(absolutePath);
          }
          continue;
        }

        if (entry.isFile()) {
          const relativePath = path.relative(projectRoot, absolutePath).split(path.sep).join("/");
          if (!relativePath || ignoredFiles.has(entry.name)) {
            continue;
          }

          const extension = path.extname(entry.name);
          const isIncludedByExtension = includedExtensions.has(extension);
          const isIncludedByName = includedFiles.has(entry.name) || entry.name.startsWith(".env") || entry.name.endsWith(".prisma");
          if (!isIncludedByExtension && !isIncludedByName) {
            continue;
          }

          const fileContent = fs.readFileSync(absolutePath, "utf8");
          trackedFiles.push({
            relativePath,
            hash: this.createStableHash({ path: relativePath, content: fileContent }),
          });
        }
      }
    }

    return trackedFiles.sort((left, right) => left.relativePath.localeCompare(right.relativePath));
  }

  private createStableHash(value: unknown): string {
    const stableString = this.stringifyStable(value);
    return crypto.createHash("sha256").update(stableString, "utf8").digest("hex");
  }

  private stringifyStable(value: unknown): string {
    if (value === null || typeof value !== "object") {
      return JSON.stringify(value);
    }

    if (Array.isArray(value)) {
      return `[${value.map((item) => this.stringifyStable(item)).join(",")} ]`;
    }

    const sortedKeys = Object.keys(value).sort();
    const entries = sortedKeys.map((key) => `${JSON.stringify(key)}:${this.stringifyStable((value as Record<string, unknown>)[key])}`);
    return `{${entries.join(",")}}`;
  }

  private hasMetadata(value: unknown): boolean {
    if (!value || typeof value !== "object") {
      return false;
    }

    if (Array.isArray(value)) {
      return value.length > 0;
    }

    return Object.keys(value).length > 0;
  }
}

export interface EngineEvent {
  type: string;
  timestamp: string;
  stage?: string;
  engine?: string;
  details?: Record<string, unknown>;
}

export class EventBus {
  private readonly listeners = new Set<(event: EngineEvent) => void>();

  subscribe(listener: (event: EngineEvent) => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  emit(event: EngineEvent): void {
    for (const listener of this.listeners) {
      listener({ ...event, timestamp: event.timestamp || new Date().toISOString() });
    }
  }

  emitLifecycle(type: string, engine?: string, stage?: string, details?: Record<string, unknown>): void {
    this.emit({ type, timestamp: new Date().toISOString(), engine, stage, details });
  }
}

import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { HistoryEngine } from "../history/HistoryEngine.js";
import { EventBus } from "../doctor/EventBus.js";
import { PipelineResolver } from "./PipelineResolver.js";
import { ExecutionScheduler } from "./ExecutionScheduler.js";
import { ArtifactBus } from "./ArtifactBus.js";
import { RuntimeMetricsEngine } from "./RuntimeMetricsEngine.js";
import { EngineRegistry } from "./EngineRegistry.js";
import type { EngineManifest, ManifestAwareEngine } from "./EngineManifest.js";

export interface RuntimeKernelEvent {
  type: string;
  timestamp: string;
  stage?: string;
  engine?: string;
  details?: Record<string, unknown>;
}

export interface RuntimeKernelOptions {
  engines: IEngine[];
  maxRetries?: number;
  history?: HistoryEngine;
  eventBus?: EventBus;
  registry?: EngineRegistry;
  pipelineResolver?: PipelineResolver;
  scheduler?: ExecutionScheduler;
  artifactBus?: ArtifactBus;
  runtimeMetrics?: RuntimeMetricsEngine;
  onEvent?: (event: RuntimeKernelEvent) => void;
  onLifecycle?: (type: string, engine: string, stage?: string, details?: Record<string, unknown>) => void;
}

export class RuntimeKernel {
  private readonly context: Context;
  private readonly engines: IEngine[];
  private readonly maxRetries: number;
  private readonly history: HistoryEngine;
  private readonly registry: EngineRegistry;
  private readonly pipelineResolver: PipelineResolver;
  private readonly scheduler: ExecutionScheduler;
  private readonly artifactBus: ArtifactBus;
  private readonly runtimeMetrics: RuntimeMetricsEngine;
  private readonly eventBus: EventBus;
  private readonly onEvent?: (event: RuntimeKernelEvent) => void;
  private readonly onLifecycle?: (type: string, engine: string, stage?: string, details?: Record<string, unknown>) => void;

  constructor(context: Context, options: RuntimeKernelOptions) {
    this.context = context;
    this.engines = options.engines;
    this.maxRetries = options.maxRetries ?? 2;
    this.history = options.history ?? new HistoryEngine(this.context.projectRoot);
    this.registry = options.registry ?? new EngineRegistry();
    this.pipelineResolver = options.pipelineResolver ?? new PipelineResolver(this.registry);
    this.scheduler = options.scheduler ?? new ExecutionScheduler();
    this.artifactBus = options.artifactBus ?? new ArtifactBus();
    this.runtimeMetrics = options.runtimeMetrics ?? new RuntimeMetricsEngine();
    this.eventBus = options.eventBus ?? new EventBus();
    this.onEvent = options.onEvent;
    this.onLifecycle = options.onLifecycle;

    for (const engine of this.engines) {
      try {
        this.registry.register(engine);
      } catch {
        // Preserve backward compatibility when an engine manifest collides with an existing registration.
      }
    }
  }

  async run(): Promise<void> {
    const resolvedEngines = this.pipelineResolver.resolve(this.engines);
    const groups = this.pipelineResolver.createGroups(resolvedEngines);

    this.emitLifecycle("PIPELINE_STARTED", "RuntimeKernel", "pipeline");

    for (const group of groups) {
      for (const engine of group.engines) {
        await this.executeEngine(engine);
      }
    }

    await this.artifactBus.flush(this.context);
    await this.runtimeMetrics.collect(this.context, {
      executionTimeMs: 0,
      memoryUsageMb: Math.round(process.memoryUsage().rss / 1024 / 1024),
      cpuUsagePercent: 0,
      warnings: 0,
      errors: 0,
      retries: 0,
      knowledgeReuse: 1,
      confidence: 0.8,
    });

    this.emitLifecycle("PIPELINE_FINISHED", "RuntimeKernel", "pipeline");
    this.history.save(this.context, 0);
  }

  private async executeEngine(engine: IEngine): Promise<void> {
    let attempt = 0;
    while (attempt <= this.maxRetries) {
      try {
        this.emit({ type: "EngineStarted", timestamp: new Date().toISOString(), stage: engine.name, engine: engine.name });
        this.emitLifecycle("ENGINE_STARTED", engine.name, engine.name);
        await engine.run(this.context);
        this.emit({ type: "EngineCompleted", timestamp: new Date().toISOString(), stage: engine.name, engine: engine.name });
        this.emitLifecycle("ENGINE_FINISHED", engine.name, engine.name);
        return;
      } catch (error) {
        attempt += 1;
        this.emit({
          type: "EngineFailed",
          timestamp: new Date().toISOString(),
          stage: engine.name,
          engine: engine.name,
          details: { attempt, error: error instanceof Error ? error.message : String(error) },
        });
        this.emitLifecycle("ENGINE_FAILED", engine.name, engine.name, { attempt, error: error instanceof Error ? error.message : String(error) });
        if (attempt > this.maxRetries) {
          throw error;
        }
      }
    }
  }

  private emit(event: RuntimeKernelEvent): void {
    this.onEvent?.({ ...event, timestamp: new Date().toISOString() });
  }

  private emitLifecycle(type: string, engine: string, stage?: string, details?: Record<string, unknown>): void {
    this.eventBus.emitLifecycle(type, engine, stage, details);
    this.onLifecycle?.(type, engine, stage, details);
  }
}

import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { EngineRegistry } from "./EngineRegistry.js";
import type { EngineManifest, ManifestAwareEngine } from "./EngineManifest.js";

export interface PipelineGroup {
  id: string;
  engines: IEngine[];
  parallel: boolean;
  dependencies: string[];
}

export class PipelineResolver {
  constructor(private readonly registry: EngineRegistry = new EngineRegistry()) {}

  resolve(engines: IEngine[]): IEngine[] {
    const manifestMap = new Map<string, EngineManifest>();
    const ordered: IEngine[] = [];
    const visited = new Set<string>();
    const visiting = new Set<string>();

    const visit = (engine: IEngine): void => {
      const manifest = this.getManifest(engine);
      const id = manifest.id;
      if (visiting.has(id)) {
        throw new Error(`Circular dependency detected for engine ${id}`);
      }
      if (visited.has(id)) {
        return;
      }
      visiting.add(id);
      manifestMap.set(id, manifest);
      for (const dependencyId of manifest.dependencies) {
        const dependency = engines.find((candidate) => this.getManifest(candidate).id === dependencyId);
        if (!dependency) {
          continue;
        }
        visit(dependency);
      }
      visiting.delete(id);
      visited.add(id);
      ordered.push(engine);
    };

    for (const engine of engines) {
      visit(engine);
    }

    return ordered;
  }

  createGroups(engines: IEngine[]): PipelineGroup[] {
    const ordered = this.resolve(engines);
    const groups: PipelineGroup[] = [];
    let current: IEngine[] = [];
    for (const engine of ordered) {
      if (current.length === 0) {
        current = [engine];
        continue;
      }
      current.push(engine);
    }
    if (current.length > 0) {
      groups.push({ id: "group-1", engines: current, parallel: false, dependencies: [] });
    }
    return groups;
  }

  private getManifest(engine: IEngine): EngineManifest {
    const manifestAware = engine as unknown as ManifestAwareEngine;
    return typeof manifestAware.getManifest === "function"
      ? manifestAware.getManifest()
      : {
          id: engine.name.toLowerCase(),
          name: engine.name,
          version: "1.0.0",
          author: "satset",
          category: "runtime",
          priority: 0,
          enabled: true,
          timeout: 30000,
          retryPolicy: { retries: 0, backoff: 0 },
          dependencies: [],
          tags: [],
        };
  }
}

import type { IEngine } from "../core/IEngine.js";
import type { EngineManifest, ManifestAwareEngine } from "./EngineManifest.js";

export interface EngineRegistration {
  id: string;
  name: string;
  priority: number;
  dependencies: string[];
  timeoutMs: number;
  retryPolicy: { maxAttempts: number; backoffMs: number };
  checkpoint: boolean;
  health: "healthy" | "degraded" | "failing";
  manifest?: EngineManifest;
}

export class EngineRegistry {
  private readonly registrations = new Map<string, EngineRegistration>();

  register(engine: IEngine, registration: Partial<EngineRegistration> = {}): void {
    const manifest = this.getManifest(engine);
    const key = registration.id ?? manifest.id ?? engine.name;
    if (this.registrations.has(key)) {
      throw new Error(`Duplicate engine id ${key}`);
    }
    this.registrations.set(key, {
      id: key,
      name: engine.name,
      priority: registration.priority ?? manifest.priority ?? 0,
      dependencies: registration.dependencies ?? manifest.dependencies ?? [],
      timeoutMs: registration.timeoutMs ?? manifest.timeout ?? 30000,
      retryPolicy: registration.retryPolicy ?? { maxAttempts: manifest.retryPolicy.retries + 1, backoffMs: manifest.retryPolicy.backoff },
      checkpoint: registration.checkpoint ?? true,
      health: registration.health ?? "healthy",
      manifest,
    });
  }

  unregister(name: string): void {
    this.registrations.delete(name);
  }

  discover(): EngineRegistration[] {
    return Array.from(this.registrations.values()).sort((left, right) => right.priority - left.priority || left.name.localeCompare(right.name));
  }

  list(): EngineRegistration[] {
    return this.discover();
  }

  get(name: string): EngineRegistration | undefined {
    return this.resolve(name);
  }

  resolve(name: string): EngineRegistration | undefined {
    const exact = this.registrations.get(name);
    if (exact) {
      return exact;
    }

    const normalized = name.toLowerCase();
    return Array.from(this.registrations.values()).find((entry) => {
      const candidates = [entry.id, entry.name, entry.manifest?.id, entry.manifest?.name];
      return candidates.some((candidate) => candidate?.toLowerCase() === normalized);
    });
  }

  validate(): string[] {
    const errors: string[] = [];
    const entries = this.discover();
    for (const entry of entries) {
      if (!entry.manifest?.id) {
        errors.push(`Missing manifest id for ${entry.name}`);
      }
      for (const dependency of entry.dependencies) {
        if (!entries.some((item) => item.id === dependency || item.name === dependency)) {
          errors.push(`Missing dependency ${dependency} for ${entry.name}`);
        }
      }
    }
    return errors;
  }

  private getManifest(engine: IEngine): EngineManifest {
    const manifestAware = engine as unknown as ManifestAwareEngine;
    return typeof manifestAware.getManifest === "function"
      ? manifestAware.getManifest()
      : {
          id: engine.name.toLowerCase(),
          name: engine.name,
          version: "1.0.0",
          author: "satset",
          category: "runtime",
          priority: 0,
          enabled: true,
          timeout: 30000,
          retryPolicy: { retries: 0, backoff: 0 },
          dependencies: [],
          tags: [],
        };
  }
}

import type { Context } from "../core/Context.js";
