import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../core/Context.js";
import type { RuntimeEvent } from "./FactoryRuntime.js";

export interface CheckpointSnapshot {
  projectName: string;
  metadata: unknown;
  issues: readonly unknown[];
  recommendations: string[];
  repairLog: unknown[];
  repairLoop: unknown;
  repairSummary: unknown;
  health: unknown;
  verification: unknown;
  events: RuntimeEvent[];
  stage?: string;
}

export class CheckpointManager {
  constructor(private readonly projectRoot: string) {}

  async save(context: Context, events: RuntimeEvent[], stage?: string): Promise<void> {
    const snapshot: CheckpointSnapshot = {
      projectName: context.projectName,
      metadata: context.metadata,
      issues: context.getIssues(),
      recommendations: context.recommendations,
      repairLog: context.repairLog ?? [],
      repairLoop: context.repairLoop,
      repairSummary: context.repairSummary,
      health: context.health,
      verification: context.verification,
      events,
      stage,
    };

    const checkpointPath = path.join(this.projectRoot, ".satset-checkpoint.json");
    await fs.mkdir(this.projectRoot, { recursive: true });
    await fs.writeFile(checkpointPath, JSON.stringify(snapshot, null, 2), "utf8");
  }

  async restore(context: Context): Promise<CheckpointSnapshot | undefined> {
    const checkpointPath = path.join(this.projectRoot, ".satset-checkpoint.json");
    try {
      const content = await fs.readFile(checkpointPath, "utf8");
      const snapshot = JSON.parse(content) as CheckpointSnapshot;
      context.projectName = snapshot.projectName;
      context.recommendations = snapshot.recommendations;
      context.metadata = snapshot.metadata as typeof context.metadata;
      context.repairLog = snapshot.repairLog as typeof context.repairLog;
      context.repairLoop = snapshot.repairLoop as typeof context.repairLoop;
      context.repairSummary = snapshot.repairSummary as typeof context.repairSummary;
      context.health = snapshot.health as typeof context.health;
      context.verification = snapshot.verification;
      return snapshot;
    } catch {
      return undefined;
    }
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { ArtifactPipeline } from "../artifacts/ArtifactPipeline.js";

export interface RepairMemoryEntry {
  id: string;
  category: string;
  severity: string;
  errors: string[];
  solution: string;
}

export interface RepairMemoryState {
  reused: boolean;
  entries: RepairMemoryEntry[];
}

export class RepairMemoryEngine implements IEngine {
  public readonly name = "RepairMemoryEngine";

  async run(context: Context): Promise<void> {
    const memoryPath = path.join(context.projectRoot, ".repair-memory.json");
    const failureReport = (context.metadata as Record<string, unknown>).failureReport as {
      category?: string;
      severity?: string;
      errors?: string[];
    } | undefined;

    const category = failureReport?.category ?? "typescript";
    const severity = failureReport?.severity ?? "medium";
    const errors = failureReport?.errors ?? [];
    const id = `repair:${category}:${errors.join("|")}`.slice(0, 180);

    let entries: RepairMemoryEntry[] = [];
    try {
      const existing = await fs.readFile(memoryPath, "utf8");
      entries = JSON.parse(existing) as RepairMemoryEntry[];
    } catch {
      entries = [];
    }

    const existingEntry = entries.find((entry) => entry.id === id);
    const reused = Boolean(existingEntry);
    if (!existingEntry) {
      entries.push({
        id,
        category,
        severity,
        errors,
        solution: `repair ${category} issue with minimal patch`,
      });
    }

    await fs.writeFile(memoryPath, JSON.stringify(entries, null, 2), "utf8");

    const pipeline = new ArtifactPipeline(context.projectRoot);
    await pipeline.run(context, [{
      id: "repair-memory",
      name: "repair-memory",
      templatePath: path.join(context.projectRoot, "templates", "repair-plan.md.tpl"),
      outputPath: path.join(context.projectRoot, "knowledge", "repair-memory.json"),
      variables: {
        strategy: reused ? "reuse" : "remember",
        priority: severity === "high" ? "high" : "medium",
        category,
      },
    }]);

    context.metadata = {
      ...context.metadata,
      repairMemory: {
        reused,
        entries,
      },
    } as typeof context.metadata & { repairMemory?: RepairMemoryState };
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { ArtifactPipeline } from "../artifacts/ArtifactPipeline.js";

export interface KnowledgeNode {
  id: string;
  kind: "problem" | "repair" | "file" | "engine" | "artifact";
  label: string;
  metadata?: Record<string, unknown>;
}

export interface KnowledgeEdge {
  from: string;
  to: string;
  kind: string;
}

export interface KnowledgeGraph {
  nodes: KnowledgeNode[];
  edges: KnowledgeEdge[];
}

export class KnowledgeGraphEngine implements IEngine {
  public readonly name = "KnowledgeGraphEngine";

  async run(context: Context): Promise<void> {
    const repairMemory = (context.metadata as Record<string, unknown>).repairMemory as { entries?: Array<{ id: string; category: string; errors: string[]; solution: string }> } | undefined;
    const entries = repairMemory?.entries ?? [];
    const agentMesh = (context.metadata as Record<string, unknown>).agentMesh as { history?: Array<{ agent: string; status: string; confidence: number }> } | undefined;

    const graph: KnowledgeGraph = {
      nodes: [],
      edges: [],
    };

    for (const entry of entries) {
      const problemId = `problem:${entry.category}`;
      const repairId = `repair:${entry.id}`;
      const fileId = `file:${entry.category}`;
      const engineId = `engine:repair`;
      const artifactId = `artifact:${entry.category}`;

      graph.nodes.push(
        { id: problemId, kind: "problem", label: entry.category },
        { id: repairId, kind: "repair", label: entry.solution },
        { id: fileId, kind: "file", label: entry.category },
        { id: engineId, kind: "engine", label: "RepairMemoryEngine" },
        { id: artifactId, kind: "artifact", label: `${entry.category}-artifact` }
      );

      graph.edges.push(
        { from: problemId, to: repairId, kind: "causes" },
        { from: repairId, to: fileId, kind: "touches" },
        { from: repairId, to: engineId, kind: "generated-by" },
        { from: repairId, to: artifactId, kind: "produces" }
      );
    }

    for (const entry of agentMesh?.history ?? []) {
      const agentId = `agent:${entry.agent}`;
      const agentNode = { id: agentId, kind: "engine" as const, label: entry.agent, metadata: { status: entry.status, confidence: entry.confidence } };
      graph.nodes.push(agentNode);
      if (entry.status === "failed") {
        const failureId = `failure:${entry.agent}`;
        graph.nodes.push({ id: failureId, kind: "problem" as const, label: `${entry.agent} failure`, metadata: { confidence: entry.confidence } });
        graph.edges.push({ from: agentId, to: failureId, kind: "failed" });
      } else {
        const performanceId = `performance:${entry.agent}`;
        graph.nodes.push({ id: performanceId, kind: "artifact" as const, label: `${entry.agent} performance`, metadata: { confidence: entry.confidence } });
        graph.edges.push({ from: agentId, to: performanceId, kind: "performed" });
      }
    }

    const dedupedNodes = this.dedup(graph.nodes);
    const dedupedEdges = this.dedup(graph.edges);

    await fs.mkdir(path.join(context.projectRoot, "knowledge"), { recursive: true });
    await fs.writeFile(path.join(context.projectRoot, "knowledge", "knowledge-graph.json"), JSON.stringify({ nodes: dedupedNodes, edges: dedupedEdges }, null, 2), "utf8");

    const pipeline = new ArtifactPipeline(context.projectRoot);
    await pipeline.run(context, [{
      id: "knowledge-graph",
      name: "knowledge-graph",
      templatePath: path.join(context.projectRoot, "templates", "repair-plan.md.tpl"),
      outputPath: path.join(context.projectRoot, "knowledge", "knowledge-graph.json"),
      variables: {
        strategy: "graph",
        priority: "high",
        category: "knowledge",
      },
    }]);

    context.metadata = {
      ...context.metadata,
      knowledgeGraph: { nodes: dedupedNodes, edges: dedupedEdges },
    } as typeof context.metadata & { knowledgeGraph?: KnowledgeGraph };
  }

  private dedup<T extends { id?: string; from?: string; to?: string }>(values: T[]): T[] {
    const seen = new Set<string>();
    return values.filter((value) => {
      const key = value.id ?? `${value.from ?? ""}:${value.to ?? ""}`;
      if (seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    });
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { Doctor } from "../doctor/Doctor.js";

export interface BenchmarkProjectSpec {
  name: string;
  root: string;
  expectedArtifacts: string[];
  expectedApi: string[];
  expectedDatabase: string[];
  expectedUi: string[];
  expectedTests: string[];
}

export interface BenchmarkResult {
  project: string;
  score: number;
  summary: Record<string, number | string>;
  artifacts: string[];
}

export class BenchmarkEngine implements IEngine {
  public readonly name = "BenchmarkEngine";

  async run(context: Context): Promise<void> {
    const benchmarkRoot = path.join(context.projectRoot, "benchmarks");
    const resolvedBenchmarkRoot = await this.resolveBenchmarkRoot(context.projectRoot);
    let entries;
    try {
      entries = await fs.readdir(resolvedBenchmarkRoot, { withFileTypes: true });
    } catch (error) {
      if ((error as NodeJS.ErrnoException)?.code === "ENOENT") {
        await fs.mkdir(path.join(context.projectRoot, "knowledge"), { recursive: true });
        await fs.writeFile(path.join(context.projectRoot, "knowledge", "benchmark-result.json"), JSON.stringify([], null, 2), "utf8");
        context.metadata = {
          ...context.metadata,
          benchmarkResult: [],
        } as typeof context.metadata & { benchmarkResult?: BenchmarkResult[] };
        return;
      }
      throw error;
    }
    const projects = [] as string[];
    for (const entry of entries) {
      if (entry.isDirectory()) {
        const isBenchmark = await this.isBenchmarkProject(entry.name, resolvedBenchmarkRoot);
        if (isBenchmark) {
          projects.push(entry.name);
        }
      }
    }
    const results: BenchmarkResult[] = [];

    for (const project of projects) {
      const projectRoot = path.join(resolvedBenchmarkRoot, project);
      const spec = await this.loadSpec(projectRoot);
      const projectContext = new Context({
        projectRoot: projectRoot,
        projectName: spec.name,
        nodeVersion: context.nodeVersion,
        pnpmVersion: context.pnpmVersion,
        typescriptVersion: context.typescriptVersion,
        prismaVersion: context.prismaVersion,
        nextVersion: context.nextVersion,
        issues: [],
        recommendations: [],
        metadata: { root: projectRoot },
      });

      const doctor = new Doctor({
        projectRoot: projectRoot,
        projectName: spec.name,
        nodeVersion: context.nodeVersion,
        pnpmVersion: context.pnpmVersion,
        typescriptVersion: context.typescriptVersion,
        prismaVersion: context.prismaVersion,
        nextVersion: context.nextVersion,
        issues: [],
        recommendations: [],
        metadata: { root: projectRoot },
      }, { skipBenchmark: true });
      await doctor.run();

      const artifacts = await this.collectArtifacts(projectRoot);
      const score = this.scoreArtifacts(spec, artifacts);
      results.push({ project: spec.name, score, summary: { artifactsFound: artifacts.length }, artifacts });
    }

    await this.writeBenchmarkArtifacts(context, results);

    context.metadata = {
      ...context.metadata,
      benchmarkResult: results,
    } as typeof context.metadata & { benchmarkResult?: BenchmarkResult[] };
  }

  private async writeBenchmarkArtifacts(context: Context, results: BenchmarkResult[]): Promise<void> {
    const knowledgeDir = path.join(context.projectRoot, "knowledge");
    await fs.mkdir(knowledgeDir, { recursive: true });

    const baseMetadata = this.buildBenchmarkMetadata(context, results);
    const resultPayload = results.map((result) => ({
      ...result,
      ...baseMetadata,
      projectId: result.project,
      projectName: result.project,
      benchmarkScore: result.score,
      qualityScore: baseMetadata.qualityScore,
      validationScore: baseMetadata.validationScore,
      knowledgeVersion: baseMetadata.knowledgeVersion,
    }));

    const summaryPayload = {
      ...baseMetadata,
      totalProjects: resultPayload.length,
      averageBenchmarkScore: resultPayload.length ? resultPayload.reduce((sum, item) => sum + Number((item as { benchmarkScore?: number }).benchmarkScore ?? 0), 0) / resultPayload.length : 0,
      averageQualityScore: baseMetadata.qualityScore,
      averageValidationScore: baseMetadata.validationScore,
      projects: resultPayload,
    };

    const historyPayload = this.loadHistory(knowledgeDir, resultPayload);

    await fs.writeFile(path.join(knowledgeDir, "benchmark-result.json"), JSON.stringify(resultPayload, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgeDir, "benchmark-history.json"), JSON.stringify(historyPayload, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgeDir, "benchmark-summary.json"), JSON.stringify(summaryPayload, null, 2), "utf8");

    context.metadata = {
      ...context.metadata,
      benchmarkResult: resultPayload,
      benchmarkHistory: historyPayload,
      benchmarkSummary: summaryPayload,
      benchmarkScore: summaryPayload.averageBenchmarkScore,
      qualityScore: baseMetadata.qualityScore,
      validationScore: baseMetadata.validationScore,
      knowledgeVersion: baseMetadata.knowledgeVersion,
    } as typeof context.metadata & { benchmarkResult?: BenchmarkResult[]; benchmarkHistory?: unknown; benchmarkSummary?: unknown; benchmarkScore?: number; qualityScore?: number; validationScore?: number; knowledgeVersion?: string };
  }

  private buildBenchmarkMetadata(context: Context, results: BenchmarkResult[]): Record<string, unknown> {
    const metadata = context.metadata as Record<string, unknown>;
    const qualityScore = typeof metadata.qualityScore === "object" && metadata.qualityScore && "overallScore" in metadata.qualityScore
      ? Number((metadata.qualityScore as { overallScore?: number }).overallScore ?? 0)
      : Number((metadata.qualityScore as number | undefined) ?? 0);
    const validationScore = typeof metadata.validationReport === "object" && metadata.validationReport && "benchmarkScore" in metadata.validationReport
      ? Number((metadata.validationReport as { benchmarkScore?: number }).benchmarkScore ?? 0)
      : Number((metadata.validationScore as number | undefined) ?? 0);
    const knowledgeVersion = String((metadata.knowledgeVersion as string | undefined) ?? "1.0.0");

    return {
      projectId: String((metadata.projectId as string | undefined) ?? context.projectName),
      projectName: context.projectName,
      runtimeId: String((metadata.runtimeId as string | undefined) ?? "satset-doctor"),
      timestamp: new Date().toISOString(),
      benchmarkScore: results.length ? results.reduce((sum, item) => sum + (item.score ?? 0), 0) / results.length : 0,
      qualityScore,
      validationScore,
      knowledgeVersion,
    };
  }

  private async loadHistory(knowledgeDir: string, resultPayload: Array<Record<string, unknown>>): Promise<Array<Record<string, unknown>>> {
    const historyPath = path.join(knowledgeDir, "benchmark-history.json");
    try {
      const existing = await fs.readFile(historyPath, "utf8");
      const parsed = JSON.parse(existing) as Array<Record<string, unknown>>;
      return [...parsed, ...resultPayload];
    } catch {
      return [...resultPayload];
    }
  }

  private async resolveBenchmarkRoot(projectRoot: string): Promise<string> {
    const candidate = path.join(projectRoot, "benchmarks");
    try {
      await fs.access(candidate);
      return candidate;
    } catch {
      return projectRoot;
    }
  }

  private async isBenchmarkProject(name: string, root: string): Promise<boolean> {
    const projectRoot = path.join(root, name);
    try {
      await fs.access(path.join(projectRoot, "expected-artifacts.json"));
      return true;
    } catch {
      return false;
    }
  }

  private async loadSpec(projectRoot: string): Promise<BenchmarkProjectSpec> {
    const expectedArtifacts = JSON.parse(await fs.readFile(path.join(projectRoot, "expected-artifacts.json"), "utf8")) as string[];
    const expectedApi = JSON.parse(await fs.readFile(path.join(projectRoot, "expected-api.json"), "utf8")) as string[];
    const expectedDatabase = JSON.parse(await fs.readFile(path.join(projectRoot, "expected-database.json"), "utf8")) as string[];
    const expectedUi = JSON.parse(await fs.readFile(path.join(projectRoot, "expected-ui.json"), "utf8")) as string[];
    const expectedTests = JSON.parse(await fs.readFile(path.join(projectRoot, "expected-tests.json"), "utf8")) as string[];

    return {
      name: path.basename(projectRoot),
      root: projectRoot,
      expectedArtifacts,
      expectedApi,
      expectedDatabase,
      expectedUi,
      expectedTests,
    };
  }

  private async collectArtifacts(root: string): Promise<string[]> {
    const collected: string[] = [];
    const walk = async (dir: string): Promise<void> => {
      const entries = await fs.readdir(dir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          await walk(fullPath);
        } else {
          collected.push(path.relative(root, fullPath));
        }
      }
    };
    await walk(root);
    return collected.filter((entry) => entry !== "" && !entry.startsWith("node_modules") && !entry.startsWith(".git"));
  }

  private scoreArtifacts(spec: BenchmarkProjectSpec, artifacts: string[]): number {
    const expected = new Set([...spec.expectedArtifacts, ...spec.expectedApi, ...spec.expectedDatabase, ...spec.expectedUi, ...spec.expectedTests]);
    const matched = artifacts.filter((artifact) => expected.has(artifact));
    return Math.round((matched.length / Math.max(1, expected.size)) * 100);
  }
}

