import { promises as fs } from "fs";
import crypto from "crypto";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface PrismaMetadata {
  prismaFolderExists: boolean;
  schemaExists: boolean;
  schemaPath: string | null;
  schemaFolder?: string | null;
  schemaCount?: number;
  generatorProvider: string | null;
  generatorOutput: string | null;
  datasourceProvider: string | null;
  datasourceUrl: string | null;
  engineType: string | null;
  modelCount: number;
  modelNames: string[];
  generatedPrismaExists: boolean;
  generatedPrismaPath: string | null;
  generatedHash: string | null;
  runtimeLibraryExists: boolean;
  runtimeLibraryPath: string | null;
  runtimeExists: boolean;
  libraryDtsSize: number | null;
  libraryLineCount: number | null;
  libraryHash: string | null;
  indexDtsExists: boolean;
  indexDtsPath: string | null;
  indexDtsSize: number | null;
  indexLineCount: number | null;
  indexHash: string | null;
  hasRuntimeFolder: boolean;
  hasGeneratorFolder: boolean;
  hasBinary: boolean;
  hasQueryEngine: boolean;
  hasSchemaModels: boolean;
  hasDatasource: boolean;
  hasGenerator: boolean;
  hasNamespacePrisma: boolean;
  hasPrismaClient: boolean;
  hasKnownRequestError: boolean;
  hasPrismaPromise: boolean;
  prismaVersion: string | null;
  generatorPackageVersion: string | null;
  clientPackageVersion: string | null;
  schemaHash: string | null;
}

export class PrismaScanner implements IScanner {
  public readonly name = "PrismaScanner";

  public async scan(context: Context): Promise<void> {
    const root = context.projectRoot;
    const prismaDir = path.join(root, "prisma");
    let schemaPath = path.join(prismaDir, "schema.prisma");
    const generatedPrismaDir = path.join(root, "node_modules", ".prisma", "client");
    const runtimeLibraryPath = path.join(generatedPrismaDir, "runtime", "library.d.ts");
    const indexDtsPath = path.join(generatedPrismaDir, "index.d.ts");
    const packageJsonPath = path.join(root, "package.json");

    const metadata: PrismaMetadata = {
      prismaFolderExists: false,
      schemaExists: false,
      schemaFolder: null,
      schemaPath: null,
      generatorProvider: null,
      generatorOutput: null,
      datasourceProvider: null,
      datasourceUrl: null,
      engineType: null,
      modelCount: 0,
      modelNames: [],
      generatedPrismaExists: false,
      generatedPrismaPath: null,
      generatedHash: null,
      runtimeLibraryExists: false,
      runtimeLibraryPath: null,
      runtimeExists: false,
      libraryDtsSize: null,
      libraryLineCount: null,
      libraryHash: null,
      indexDtsExists: false,
      indexDtsPath: null,
      indexDtsSize: null,
      indexLineCount: null,
      indexHash: null,
      hasRuntimeFolder: false,
      hasGeneratorFolder: false,
      hasBinary: false,
      hasQueryEngine: false,
      hasSchemaModels: false,
      hasDatasource: false,
      hasGenerator: false,
      hasNamespacePrisma: false,
      hasPrismaClient: false,
      hasKnownRequestError: false,
      hasPrismaPromise: false,
      prismaVersion: null,
      generatorPackageVersion: null,
      clientPackageVersion: null,
      schemaHash: null,
      schemaCount: 0,
    };

    const tryAccess = async (targetPath: string): Promise<boolean> => {
      try {
        await fs.access(targetPath);
        return true;
      } catch {
        return false;
      }
    };

    const parseBlock = (content: string, blockType: string): string | null => {
      const match = content.match(new RegExp(`${blockType}\\s+\\w+\\s*\\{([\\s\\S]*?)\\}`, "i"));
      return match ? match[1] : null;
    };

    const parseProperty = (block: string | null, key: string): string | null => {
      if (!block) {
        return null;
      }

      const match = block.match(new RegExp(`${key}\\s*=\\s*("([^"]*)"|[^\\s]+)`, "i"));
      if (!match) {
        return null;
      }

      const value = match[1].trim();
      return value.startsWith('"') && value.endsWith('"') ? value.slice(1, -1) : value;
    };

    const hashString = (value: string): string =>
      crypto.createHash("sha256").update(value, "utf8").digest("hex");

    const findSchemaFiles = async (start: string, maxDepth = 5): Promise<string[]> => {
      const results: string[] = [];

      const walk = async (dir: string, depth: number): Promise<void> => {
        if (depth > maxDepth) return;
        let entries;
        try {
          entries = await fs.readdir(dir, { withFileTypes: true });
        } catch {
          return;
        }

        for (const entry of entries) {
          const resPath = path.join(dir, entry.name);
          if (entry.isFile() && entry.name === "schema.prisma") {
            results.push(resPath);
          } else if (entry.isDirectory()) {
            await walk(resPath, depth + 1);
          }
        }
      };

      await walk(start, 0);
      return results;
    };

    const readSchema = async (): Promise<void> => {
      // perform recursive search for schema.prisma up to depth 5
      const found = await findSchemaFiles(root, 5);
      metadata.schemaCount = found.length;

      if (found.length === 0) {
        // fallback to default path if exists
        const existsDefault = await tryAccess(schemaPath);
        if (!existsDefault) {
          metadata.schemaExists = false;
          metadata.schemaPath = null;
          metadata.schemaFolder = null as unknown as string | null;
          return;
        }
        schemaPath = schemaPath;
      } else if (found.length === 1) {
        schemaPath = found[0];
      } else {
        // choose the one that has a generator named 'client'
        let chosen: string | null = null;
        for (const p of found) {
          try {
            const c = await fs.readFile(p, "utf-8");
            if (/generator\s+client\s*\{/i.test(c)) {
              chosen = p;
              break;
            }
          } catch {
            // ignore
          }
        }

        schemaPath = chosen ?? found[0];
      }

      const exists = await tryAccess(schemaPath);
      if (!exists) {
        metadata.schemaExists = false;
        metadata.schemaPath = null;
        metadata.schemaFolder = null as unknown as string | null;
        return;
      }

      metadata.schemaExists = true;
      metadata.schemaPath = schemaPath;
      metadata.schemaFolder = path.dirname(schemaPath);

      const content = await fs.readFile(schemaPath, "utf-8");
      metadata.schemaHash = hashString(content);

      const generatorBlock = parseBlock(content, "generator");
      const datasourceBlock = parseBlock(content, "datasource");

      metadata.generatorProvider = parseProperty(generatorBlock, "provider");
      metadata.generatorOutput = parseProperty(generatorBlock, "output");
      metadata.engineType = parseProperty(generatorBlock, "engineType");
      metadata.datasourceProvider = parseProperty(datasourceBlock, "provider");
      metadata.datasourceUrl = parseProperty(datasourceBlock, "url");
      metadata.hasDatasource = datasourceBlock !== null;
      metadata.hasGenerator = generatorBlock !== null;

      const modelNames = Array.from(content.matchAll(/^\s*model\s+([A-Za-z0-9_]+)\s*\{/gm)).map((match) => match[1]);
      metadata.modelNames = modelNames;
      metadata.modelCount = modelNames.length;
      metadata.hasSchemaModels = modelNames.length > 0;
    };

    const loadPackageVersion = async (): Promise<void> => {
      const exists = await tryAccess(packageJsonPath);
      if (!exists) {
        return;
      }

      const content = await fs.readFile(packageJsonPath, "utf-8");
      const parsed = JSON.parse(content) as {
        dependencies?: Record<string, string>;
        devDependencies?: Record<string, string>;
      };

      metadata.prismaVersion = parsed.dependencies?.prisma ?? parsed.devDependencies?.prisma ?? null;
      metadata.generatorPackageVersion = metadata.prismaVersion;
      metadata.clientPackageVersion = parsed.dependencies?.["@prisma/client"] ?? parsed.devDependencies?.["@prisma/client"] ?? null;
    };

    const readGeneratedMetadata = async (): Promise<void> => {
      metadata.hasGeneratorFolder = await tryAccess(path.join(generatedPrismaDir, "generator"));
      metadata.hasRuntimeFolder = await tryAccess(path.join(generatedPrismaDir, "runtime"));
      metadata.runtimeExists = metadata.hasRuntimeFolder;

      metadata.generatedPrismaExists = await tryAccess(generatedPrismaDir);
      metadata.generatedPrismaPath = metadata.generatedPrismaExists ? generatedPrismaDir : null;

      if (metadata.generatedPrismaExists) {
        try {
          const entries = await fs.readdir(generatedPrismaDir);
          metadata.generatedHash = hashString(entries.sort().join(","));
          metadata.hasBinary = entries.some((entry) => /query_engine|libquery_engine|prisma-engine/i.test(entry));
          metadata.hasQueryEngine = metadata.hasBinary || entries.some((entry) => /engine/i.test(entry));
        } catch {
          metadata.generatedHash = null;
          metadata.hasBinary = false;
          metadata.hasQueryEngine = false;
        }
      }
    };

    const readRuntimeFiles = async (): Promise<void> => {
      metadata.runtimeLibraryExists = await tryAccess(runtimeLibraryPath);
      metadata.runtimeLibraryPath = metadata.runtimeLibraryExists ? runtimeLibraryPath : null;
      metadata.indexDtsExists = await tryAccess(indexDtsPath);
      metadata.indexDtsPath = metadata.indexDtsExists ? indexDtsPath : null;

      if (metadata.runtimeLibraryExists) {
        const content = await fs.readFile(runtimeLibraryPath, "utf-8");
        metadata.libraryDtsSize = Buffer.byteLength(content, "utf8");
        metadata.libraryLineCount = content.split(/\r?\n/).length;
        metadata.libraryHash = hashString(content);
        metadata.hasNamespacePrisma = /export\s+declare\s+namespace\s+Prisma/.test(content);
        metadata.hasPrismaClient = /class\s+PrismaClient/.test(content);
        metadata.hasKnownRequestError = /PrismaClientKnownRequestError/.test(content);
        metadata.hasPrismaPromise = /PrismaPromise/.test(content);
      }

      if (metadata.indexDtsExists) {
        const content = await fs.readFile(indexDtsPath, "utf-8");
        metadata.indexDtsSize = Buffer.byteLength(content, "utf8");
        metadata.indexLineCount = content.split(/\r?\n/).length;
        metadata.indexHash = hashString(content);
      }
    };

    const populateMetadata = async (): Promise<void> => {
      metadata.prismaFolderExists = await tryAccess(prismaDir);
      await readSchema();
      await loadPackageVersion();
      await readGeneratedMetadata();
      await readRuntimeFiles();

      const existingMetadata = context.metadata as Record<string, unknown>;
      (context as unknown as { metadata: Record<string, unknown> }).metadata = {
        ...existingMetadata,
        prisma: metadata,
      };
    };

    await populateMetadata();
  }
}

import { promises as fs } from "fs";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface TypeScriptMetadata {
  exists: boolean;
  version: string | null;
  configExists: boolean;
  configPath: string | null;
  compilerOptions: Record<string, unknown> | null;
  baseUrl: string | null;
  paths: Record<string, unknown> | null;
  strict: boolean | null;
  module: string | null;
  moduleResolution: string | null;
  target: string | null;
  jsx: string | null;
  incremental: boolean | null;
  skipLibCheck: boolean | null;
  resolveJsonModule: boolean | null;
  esModuleInterop: boolean | null;
  allowJs: boolean | null;
  references: unknown[] | null;
  include: string[] | null;
  exclude: string[] | null;
}

export class TypeScriptScanner implements IScanner {
  public readonly name = "TypeScriptScanner";

  public scan(context: Context): void {
    void this.scanAsync(context);
  }

  private async scanAsync(context: Context): Promise<void> {
    const root = context.projectRoot;
    const tsconfigPath = path.join(root, "tsconfig.json");
    const packageJsonPath = path.join(root, "package.json");
    const typescriptPackageJsonPath = path.join(root, "node_modules", "typescript", "package.json");

    const metadata: TypeScriptMetadata = {
      exists: false,
      version: null,
      configExists: false,
      configPath: null,
      compilerOptions: null,
      baseUrl: null,
      paths: null,
      strict: null,
      module: null,
      moduleResolution: null,
      target: null,
      jsx: null,
      incremental: null,
      skipLibCheck: null,
      resolveJsonModule: null,
      esModuleInterop: null,
      allowJs: null,
      references: null,
      include: null,
      exclude: null,
    };

    metadata.exists = await this.fileExists(typescriptPackageJsonPath);

    metadata.configPath = tsconfigPath;
    metadata.configExists = await this.fileExists(tsconfigPath);

    if (metadata.configExists) {
      try {
        const configContent = await fs.readFile(tsconfigPath, "utf-8");
        const parsedConfig = JSON.parse(configContent) as {
          compilerOptions?: Record<string, unknown>;
          references?: unknown[];
          include?: string[];
          exclude?: string[];
        };

        const compilerOptions = parsedConfig.compilerOptions ?? {};
        metadata.compilerOptions = parsedConfig.compilerOptions ?? null;
        metadata.baseUrl = typeof compilerOptions.baseUrl === "string" ? compilerOptions.baseUrl : null;
        metadata.paths = typeof compilerOptions.paths === "object" && compilerOptions.paths !== null ? compilerOptions.paths as Record<string, unknown> : null;
        metadata.strict = typeof compilerOptions.strict === "boolean" ? compilerOptions.strict : null;
        metadata.module = typeof compilerOptions.module === "string" ? compilerOptions.module : null;
        metadata.moduleResolution = typeof compilerOptions.moduleResolution === "string" ? compilerOptions.moduleResolution : null;
        metadata.target = typeof compilerOptions.target === "string" ? compilerOptions.target : null;
        metadata.jsx = typeof compilerOptions.jsx === "string" ? compilerOptions.jsx : null;
        metadata.incremental = typeof compilerOptions.incremental === "boolean" ? compilerOptions.incremental : null;
        metadata.skipLibCheck = typeof compilerOptions.skipLibCheck === "boolean" ? compilerOptions.skipLibCheck : null;
        metadata.resolveJsonModule = typeof compilerOptions.resolveJsonModule === "boolean" ? compilerOptions.resolveJsonModule : null;
        metadata.esModuleInterop = typeof compilerOptions.esModuleInterop === "boolean" ? compilerOptions.esModuleInterop : null;
        metadata.allowJs = typeof compilerOptions.allowJs === "boolean" ? compilerOptions.allowJs : null;
        metadata.references = Array.isArray(parsedConfig.references) ? parsedConfig.references : null;
        metadata.include = Array.isArray(parsedConfig.include) ? parsedConfig.include : null;
        metadata.exclude = Array.isArray(parsedConfig.exclude) ? parsedConfig.exclude : null;
      } catch {
        metadata.configExists = false;
        metadata.configPath = null;
      }
    }

    if (await this.fileExists(packageJsonPath)) {
      try {
        const packageContent = await fs.readFile(packageJsonPath, "utf-8");
        const parsedPackage = JSON.parse(packageContent) as {
          dependencies?: Record<string, string>;
          devDependencies?: Record<string, string>;
        };

        metadata.version =
          parsedPackage.dependencies?.typescript ??
          parsedPackage.devDependencies?.typescript ??
          metadata.version;
      } catch {
        // Ignore package.json parse failure.
      }
    }

    if (metadata.exists) {
      try {
        const typescriptPackageContent = await fs.readFile(typescriptPackageJsonPath, "utf-8");
        const parsedTypescriptPackage = JSON.parse(typescriptPackageContent) as {
          version?: string;
        };

        metadata.version = parsedTypescriptPackage.version ?? metadata.version;
      } catch {
        metadata.exists = false;
      }
    }

    (context.metadata as Record<string, unknown>)["typescript"] = metadata;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }
}

import { promises as fs } from "fs";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface NextMetadata {
  exists: boolean;
  version: string | null;
  configExists: boolean;
  configPath: string | null;
  appRouter: boolean | null;
  pagesRouter: boolean | null;
  turbopack: boolean | null;
  typescript: boolean | null;
  eslint: boolean | null;
  reactVersion: string | null;
  nextVersion: string | null;
  output: string | null;
  images: string | null;
  experimental: string | null;
}

export class NextJsScanner implements IScanner {
  public readonly name = "NextJsScanner";

  public scan(context: Context): void {
    void this.scanAsync(context);
  }

  private async scanAsync(context: Context): Promise<void> {
    const root = context.projectRoot;
    const packageJsonPath = path.join(root, "package.json");
    const configCandidates = [
      path.join(root, "next.config.js"),
      path.join(root, "next.config.mjs"),
      path.join(root, "next.config.ts"),
    ];

    const metadata: NextMetadata = {
      exists: false,
      version: null,
      configExists: false,
      configPath: null,
      appRouter: null,
      pagesRouter: null,
      turbopack: null,
      typescript: null,
      eslint: null,
      reactVersion: null,
      nextVersion: null,
      output: null,
      images: null,
      experimental: null,
    };

    const configPath = await this.findFirstExistingPath(configCandidates);
    metadata.configExists = configPath !== null;
    metadata.configPath = configPath;

    const appDirExists = await this.fileExists(path.join(root, "app"));
    const pagesDirExists = await this.fileExists(path.join(root, "pages"));
    metadata.appRouter = appDirExists && !pagesDirExists ? true : appDirExists ? true : false;
    metadata.pagesRouter = pagesDirExists && !appDirExists ? true : pagesDirExists ? true : false;

    if (await this.fileExists(packageJsonPath)) {
      try {
        const packageContent = await fs.readFile(packageJsonPath, "utf-8");
        const parsed = JSON.parse(packageContent) as {
          dependencies?: Record<string, string>;
          devDependencies?: Record<string, string>;
          scripts?: Record<string, string>;
        };

        const deps = { ...parsed.dependencies, ...parsed.devDependencies } as Record<string, string> | undefined;
        metadata.nextVersion = deps?.next ?? null;
        metadata.reactVersion = deps?.react ?? null;
        metadata.typescript = deps?.typescript !== undefined ? true : null;
        metadata.eslint = deps?.eslint !== undefined ? true : null;

        if (metadata.eslint === null && parsed.scripts) {
          metadata.eslint = Object.values(parsed.scripts).some((script) => typeof script === "string" && script.includes("next lint"));
        }

        metadata.exists = metadata.nextVersion !== null;
      } catch {
        metadata.exists = false;
      }
    }

    if (configPath) {
      try {
        const configContent = await fs.readFile(configPath, "utf-8");
        metadata.output = this.extractString(configContent, "output");
        metadata.images = this.extractRawBlock(configContent, "images");
        metadata.experimental = this.extractRawBlock(configContent, "experimental");
        metadata.turbopack = this.extractBoolean(configContent, "turbopack") ?? this.extractBoolean(configContent, "experimental.turbopack");

        if (metadata.appRouter === null) {
          metadata.appRouter = this.extractBoolean(configContent, "appDir") ?? null;
        }

        if (metadata.pagesRouter === null) {
          metadata.pagesRouter = this.extractBoolean(configContent, "pagesDir") ?? null;
        }
      } catch {
        metadata.configExists = metadata.configExists;
      }
    }

    (context.metadata as Record<string, unknown>)["next"] = metadata;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  private async findFirstExistingPath(paths: string[]): Promise<string | null> {
    for (const candidate of paths) {
      if (await this.fileExists(candidate)) {
        return candidate;
      }
    }

    return null;
  }

  private extractString(content: string, key: string): string | null {
    const match = content.match(new RegExp(`${key}\s*:\s*("([^"]*)"|'([^']*)'|` + "([^,\n\r}]+)" + ")", "i"));
    if (!match) {
      return null;
    }

    const value = match[2] ?? match[3] ?? match[4] ?? null;
    return value !== null ? String(value).trim().replace(/['"]$/u, "") : null;
  }

  private extractBoolean(content: string, key: string): boolean | null {
    const match = content.match(new RegExp(`${key}\s*:\s*(true|false)`, "i"));
    if (!match) {
      return null;
    }

    return match[1].toLowerCase() === "true";
  }

  private extractRawBlock(content: string, key: string): string | null {
    const regex = new RegExp(`${key}\s*:\s*(\{[\s\S]*?\})`, "i");
    const match = content.match(regex);
    return match ? match[1].trim() : null;
  }
}

import { promises as fs } from "fs";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface PnpmMetadata {
  exists: boolean;
  workspaceExists: boolean;
  workspaceFile: string | null;
  lockfileExists: boolean;
  lockfileVersion: string | null;
  packageManager: string | null;
  workspacePackages: string[] | null;
  catalogs: string[] | null;
  onlyBuiltDependencies: boolean | null;
  patchedDependencies: Record<string, unknown> | null;
  overrides: Record<string, unknown> | null;
  peerDependencyRules: Record<string, unknown> | null;
  registries: Record<string, unknown> | null;
  packageCount: number | null;
  workspaceGlobs: string[] | null;
}

export class PnpmWorkspaceScanner implements IScanner {
  public readonly name = "PnpmWorkspaceScanner";

  public scan(context: Context): void {
    void this.scanAsync(context);
  }

  private async scanAsync(context: Context): Promise<void> {
    const root = context.projectRoot;
    const workspacePath = path.join(root, "pnpm-workspace.yaml");
    const packageJsonPath = path.join(root, "package.json");
    const lockfilePath = path.join(root, "pnpm-lock.yaml");

    const metadata: PnpmMetadata = {
      exists: false,
      workspaceExists: false,
      workspaceFile: null,
      lockfileExists: false,
      lockfileVersion: null,
      packageManager: null,
      workspacePackages: null,
      catalogs: null,
      onlyBuiltDependencies: null,
      patchedDependencies: null,
      overrides: null,
      peerDependencyRules: null,
      registries: null,
      packageCount: null,
      workspaceGlobs: null,
    };

    metadata.workspaceExists = await this.fileExists(workspacePath);
    metadata.workspaceFile = metadata.workspaceExists ? workspacePath : null;
    metadata.lockfileExists = await this.fileExists(lockfilePath);

    const packageJsonExists = await this.fileExists(packageJsonPath);
    metadata.exists = packageJsonExists || metadata.workspaceExists || metadata.lockfileExists;

    let packageJson: Record<string, unknown> | null = null;
    if (packageJsonExists) {
      try {
        const packageContent = await fs.readFile(packageJsonPath, "utf-8");
        packageJson = JSON.parse(packageContent) as Record<string, unknown>;
        const packageManagerValue = packageJson.packageManager;
        if (typeof packageManagerValue === "string") {
          metadata.packageManager = packageManagerValue.split("@")[0] ?? packageManagerValue;
        }

        const pnpmSection = packageJson.pnpm as Record<string, unknown> | undefined;
        if (pnpmSection) {
          if (pnpmSection.registries && typeof pnpmSection.registries === "object") {
            metadata.registries = pnpmSection.registries as Record<string, unknown>;
          }
          if (pnpmSection.peerDependencyRules && typeof pnpmSection.peerDependencyRules === "object") {
            metadata.peerDependencyRules = pnpmSection.peerDependencyRules as Record<string, unknown>;
          }
          if (pnpmSection.overrides && typeof pnpmSection.overrides === "object") {
            metadata.overrides = pnpmSection.overrides as Record<string, unknown>;
          }
          if (pnpmSection.catalogs && Array.isArray(pnpmSection.catalogs)) {
            metadata.catalogs = pnpmSection.catalogs.map((entry) => String(entry));
          }
        }
      } catch {
        // ignore malformed package.json
      }
    }

    if (metadata.workspaceExists) {
      try {
        const workspaceContent = await fs.readFile(workspacePath, "utf-8");
        metadata.workspaceGlobs = this.extractYamlList(workspaceContent, "packages");
        metadata.workspacePackages = metadata.workspaceGlobs ? [...metadata.workspaceGlobs] : null;
        metadata.catalogs = metadata.catalogs ?? this.extractYamlList(workspaceContent, "catalogs");
      } catch {
        metadata.workspaceGlobs = null;
        metadata.workspacePackages = null;
      }
    }

    if (metadata.lockfileExists) {
      try {
        const lockfileContent = await fs.readFile(lockfilePath, "utf-8");
        metadata.lockfileVersion = this.extractYamlValue(lockfileContent, "lockfileVersion");
        metadata.onlyBuiltDependencies = this.extractYamlBoolean(lockfileContent, "onlyBuiltDependencies");
        metadata.patchedDependencies = this.extractYamlObject(lockfileContent, "patchedDependencies");
        metadata.overrides = metadata.overrides ?? this.extractYamlObject(lockfileContent, "overrides");
        metadata.peerDependencyRules = metadata.peerDependencyRules ?? this.extractYamlObject(lockfileContent, "peerDependencyRules");
        metadata.registries = metadata.registries ?? this.extractYamlObject(lockfileContent, "registries");
        metadata.packageCount = this.countLockfilePackages(lockfileContent);
      } catch {
        // ignore malformed lockfile
      }
    }

    (context.metadata as Record<string, unknown>)["pnpm"] = metadata;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  private extractYamlValue(content: string, key: string): string | null {
    const match = content.match(new RegExp(`^${key}\s*:\s*(.+)$`, "m"));
    if (!match) {
      return null;
    }

    return match[1].trim().replace(/['"]+/g, "");
  }

  private extractYamlBoolean(content: string, key: string): boolean | null {
    const value = this.extractYamlValue(content, key);
    if (value === null) {
      return null;
    }

    if (value.toLowerCase() === "true") {
      return true;
    }
    if (value.toLowerCase() === "false") {
      return false;
    }

    return null;
  }

  private extractYamlList(content: string, key: string): string[] | null {
    const regex = new RegExp(`^${key}\s*:\s*\n((?:\s+-\s+.*\n)+)`, "m");
    const match = content.match(regex);
    if (!match) {
      return null;
    }

    const lines = match[1].split(/\r?\n/);
    const values = lines
      .map((line) => line.replace(/^\s*-\s*/, "").trim())
      .filter((value) => value.length > 0);

    return values.length > 0 ? values : null;
  }

  private extractYamlObject(content: string, key: string): Record<string, unknown> | null {
    const regex = new RegExp(`^${key}\s*:\s*\n((?:\s{2,}[^\n]+\n)+)`, "m");
    const match = content.match(regex);
    if (!match) {
      return null;
    }

    const object: Record<string, unknown> = {};
    const lines = match[1].split(/\r?\n/).filter((line) => line.trim().length > 0);

    for (const line of lines) {
      const trimmed = line.trim();
      const keyValue = trimmed.match(/^([^:]+):\s*(.*)$/);
      if (!keyValue) {
        continue;
      }
      const itemKey = keyValue[1].trim();
      const rawValue = keyValue[2].trim();
      if (rawValue === "true") {
        object[itemKey] = true;
      } else if (rawValue === "false") {
        object[itemKey] = false;
      } else if (rawValue === "[]") {
        object[itemKey] = [];
      } else if (rawValue === "{}") {
        object[itemKey] = {};
      } else if (/^\d+$/.test(rawValue)) {
        object[itemKey] = Number(rawValue);
      } else {
        object[itemKey] = rawValue.replace(/['"]+/g, "");
      }
    }

    return Object.keys(object).length > 0 ? object : null;
  }

  private countLockfilePackages(content: string): number | null {
    const regex = /^packages:\s*$/m;
    const startIndex = content.search(regex);
    if (startIndex === -1) {
      return null;
    }

    const contentAfter = content.slice(startIndex);
    const lines = contentAfter.split(/\r?\n/);
    let count = 0;
    for (let i = 1; i < lines.length; i += 1) {
      const line = lines[i];
      if (/^[^\s]/.test(line)) {
        break;
      }
      if (/^\s{2,}['"][^'"]+['"]\s*:/u.test(line) || /^\s{2,}[^\s].*:\s*$/u.test(line)) {
        count += 1;
      }
    }

    return count > 0 ? count : null;
  }
}

import { promises as fs } from "fs";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface TurboMetadata {
  exists: boolean;
  configExists: boolean;
  configPath: string | null;
  pipeline: Record<string, unknown> | null;
  tasks: Record<string, unknown> | null;
  globalDependencies: string[] | null;
  globalEnv: Record<string, string> | null;
  remoteCache: Record<string, unknown> | null;
  outputs: string[] | null;
  cache: Record<string, unknown> | null;
  persistentTasks: string[] | null;
  packageManager: string | null;
}

export class TurboScanner implements IScanner {
  public readonly name = "TurboScanner";

  public scan(context: Context): void {
    void this.scanAsync(context);
  }

  private async scanAsync(context: Context): Promise<void> {
    const root = context.projectRoot;
    const packageJsonPath = path.join(root, "package.json");
    const configCandidates = [path.join(root, "turbo.json"), path.join(root, "turbo.jsonc")];

    const metadata: TurboMetadata = {
      exists: false,
      configExists: false,
      configPath: null,
      pipeline: null,
      tasks: null,
      globalDependencies: null,
      globalEnv: null,
      remoteCache: null,
      outputs: null,
      cache: null,
      persistentTasks: null,
      packageManager: null,
    };

    const configPath = await this.findFirstExistingPath(configCandidates);
    metadata.configExists = configPath !== null;
    metadata.configPath = configPath;

    if (await this.fileExists(packageJsonPath)) {
      metadata.exists = true;
      try {
        const packageContent = await fs.readFile(packageJsonPath, "utf-8");
        const parsedPackage = JSON.parse(packageContent) as Record<string, unknown>;
        const packageManagerValue = parsedPackage.packageManager;
        if (typeof packageManagerValue === "string") {
          metadata.packageManager = packageManagerValue.split("@")[0] ?? packageManagerValue;
        }
      } catch {
        metadata.packageManager = null;
      }
    }

    if (configPath) {
      try {
        const configContent = await fs.readFile(configPath, "utf-8");
        const parsedConfig = this.parseJsonc(configContent);

        metadata.pipeline = typeof parsedConfig.pipeline === "object" && parsedConfig.pipeline !== null ? parsedConfig.pipeline as Record<string, unknown> : null;
        metadata.tasks = typeof parsedConfig.tasks === "object" && parsedConfig.tasks !== null ? parsedConfig.tasks as Record<string, unknown> : null;
        metadata.globalDependencies = Array.isArray(parsedConfig.globalDependencies) ? parsedConfig.globalDependencies.map(String) : null;
        metadata.globalEnv = this.extractStringMap(parsedConfig.globalEnv);
        metadata.remoteCache = typeof parsedConfig.remoteCache === "object" && parsedConfig.remoteCache !== null ? parsedConfig.remoteCache as Record<string, unknown> : null;
        metadata.outputs = Array.isArray(parsedConfig.outputs) ? parsedConfig.outputs.map(String) : null;
        metadata.cache = typeof parsedConfig.cache === "object" && parsedConfig.cache !== null ? parsedConfig.cache as Record<string, unknown> : null;
        metadata.persistentTasks = Array.isArray(parsedConfig.persistentTasks) ? parsedConfig.persistentTasks.map(String) : null;
        metadata.exists = true;
      } catch {
        metadata.configExists = false;
        metadata.configPath = null;
      }
    }

    (context.metadata as Record<string, unknown>)["turbo"] = metadata;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  private async findFirstExistingPath(paths: string[]): Promise<string | null> {
    for (const candidate of paths) {
      if (await this.fileExists(candidate)) {
        return candidate;
      }
    }

    return null;
  }

  private parseJsonc(content: string): Record<string, unknown> {
    const withoutComments = content
      .replace(/\/\/.*$/gm, "")
      .replace(/\/\*[\s\S]*?\*\//g, "");

    return JSON.parse(withoutComments);
  }

  private extractStringMap(value: unknown): Record<string, string> | null {
    if (typeof value !== "object" || value === null) {
      return null;
    }

    const result: Record<string, string> = {};
    for (const [key, entry] of Object.entries(value)) {
      if (typeof entry === "string") {
        result[key] = entry;
      }
    }

    return Object.keys(result).length > 0 ? result : null;
  }
}

import { promises as fs } from "fs";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface TailwindMetadata {
  exists: boolean;
  version: string | null;
  configExists: boolean;
  configPath: string | null;
  postcssExists: boolean;
  postcssPath: string | null;
  plugins: string[] | null;
  content: unknown | null;
  theme: unknown | null;
  presets: unknown | null;
  darkMode: unknown | null;
  usesTailwindV4: boolean | null;
  cssEntryDetected: boolean | null;
}

export class TailwindScanner implements IScanner {
  public readonly name = "TailwindScanner";

  public scan(context: Context): void {
    void this.scanAsync(context);
  }

  private async scanAsync(context: Context): Promise<void> {
    const root = context.projectRoot;
    const packageJsonPath = path.join(root, "package.json");
    const configCandidates = [
      path.join(root, "tailwind.config.js"),
      path.join(root, "tailwind.config.ts"),
      path.join(root, "tailwind.config.cjs"),
    ];
    const postcssCandidates = [
      path.join(root, "postcss.config.js"),
      path.join(root, "postcss.config.cjs"),
      path.join(root, "postcss.config.mjs"),
    ];

    const metadata: TailwindMetadata = {
      exists: false,
      version: null,
      configExists: false,
      configPath: null,
      postcssExists: false,
      postcssPath: null,
      plugins: null,
      content: null,
      theme: null,
      presets: null,
      darkMode: null,
      usesTailwindV4: null,
      cssEntryDetected: null,
    };

    const configPath = await this.findFirstExistingPath(configCandidates);
    metadata.configExists = configPath !== null;
    metadata.configPath = configPath;

    const postcssPath = await this.findFirstExistingPath(postcssCandidates);
    metadata.postcssExists = postcssPath !== null;
    metadata.postcssPath = postcssPath;

    if (await this.fileExists(packageJsonPath)) {
      metadata.exists = true;
      try {
        const packageContent = await fs.readFile(packageJsonPath, "utf-8");
        const parsed = JSON.parse(packageContent) as {
          dependencies?: Record<string, unknown>;
          devDependencies?: Record<string, unknown>;
        };
        const deps = {
          ...(parsed.dependencies ?? {}),
          ...(parsed.devDependencies ?? {}),
        } as Record<string, unknown>;
        const version = deps.tailwindcss;
        metadata.version = typeof version === "string" ? version : null;
      } catch {
        metadata.version = null;
      }
    }

    if (configPath) {
      try {
        const content = await fs.readFile(configPath, "utf-8");
        metadata.usesTailwindV4 = /tailwindcss\s*:\s*\{[\s\S]*?\b(?:content|theme|plugins|presets)\b/iu.test(content);
        metadata.plugins = this.extractArray(content, "plugins");
        metadata.content = this.extractObject(content, "content");
        metadata.theme = this.extractObject(content, "theme");
        metadata.presets = this.extractArray(content, "presets");
        metadata.darkMode = this.extractValue(content, "darkMode");
      } catch {
        metadata.configExists = metadata.configExists;
      }
    }

    metadata.cssEntryDetected = await this.detectCssEntry(root);

    (context.metadata as Record<string, unknown>)["tailwind"] = metadata;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  private async findFirstExistingPath(paths: string[]): Promise<string | null> {
    for (const candidate of paths) {
      if (await this.fileExists(candidate)) {
        return candidate;
      }
    }

    return null;
  }

  private extractArray(content: string, key: string): string[] | null {
    const match = content.match(new RegExp(`${key}\s*:\s*\[(.*?)\]`, "is"));
    if (!match) {
      return null;
    }

    return match[1]
      .split(/,(?![^\[\]]*\])/)
      .map((item) => item.trim().replace(/^['\"]|['\"]$/g, ""))
      .filter(Boolean);
  }

  private extractObject(content: string, key: string): unknown | null {
    const match = content.match(new RegExp(`${key}\s*:\s*(\{[\s\S]*?\})`, "is"));
    if (!match) {
      return null;
    }

    try {
      return this.parsePartialObject(match[1]);
    } catch {
      return null;
    }
  }

  private extractValue(content: string, key: string): unknown | null {
    const match = content.match(new RegExp(`${key}\s*:\s*([^,\n}]+)`, "i"));
    if (!match) {
      return null;
    }

    const value = match[1].trim();
    if (/^['\"]/.test(value)) {
      return value.replace(/^['\"]|['\"]$/g, "");
    }

    if (/^(true|false)$/i.test(value)) {
      return value.toLowerCase() === "true";
    }

    return value;
  }

  private parsePartialObject(value: string): unknown {
    const jsonLike = value
      .replace(/([\w$]+)\s*:/g, '"$1":')
      .replace(/'/g, '"');
    return JSON.parse(jsonLike);
  }

  private async detectCssEntry(root: string): Promise<boolean> {
    const candidates = [
      path.join(root, "src", "styles", "globals.css"),
      path.join(root, "src", "styles", "tailwind.css"),
      path.join(root, "styles", "globals.css"),
      path.join(root, "styles", "tailwind.css"),
      path.join(root, "src", "index.css"),
      path.join(root, "src", "app", "globals.css"),
    ];

    for (const candidate of candidates) {
      if (await this.fileExists(candidate)) {
        return true;
      }
    }

    return false;
  }
}

import { promises as fs } from "fs";
import path from "path";
import type { Context } from "../core/Context.js";
import type { IScanner } from "./IScanner.js";

interface ReactMetadata {
  exists: boolean;
  reactVersion: string | null;
  reactDomVersion: string | null;
  jsxRuntime: string | null;
  strictMode: boolean | null;
  reactCompiler: string | null;
  serverComponents: boolean | null;
  clientComponents: boolean | null;
  hooksDetected: boolean | null;
}

export class ReactScanner implements IScanner {
  public readonly name = "ReactScanner";

  public scan(context: Context): void {
    void this.scanAsync(context);
  }

  private async scanAsync(context: Context): Promise<void> {
    const root = context.projectRoot;
    const packageJsonPath = path.join(root, "package.json");

    const metadata: ReactMetadata = {
      exists: false,
      reactVersion: null,
      reactDomVersion: null,
      jsxRuntime: null,
      strictMode: null,
      reactCompiler: null,
      serverComponents: null,
      clientComponents: null,
      hooksDetected: null,
    };

    if (!(await this.fileExists(packageJsonPath))) {
      (context.metadata as Record<string, unknown>)["react"] = metadata;
      return;
    }

    metadata.exists = true;

    try {
      const content = await fs.readFile(packageJsonPath, "utf-8");
      const parsedPackage = JSON.parse(content) as Record<string, unknown>;
      const dependencies = parsedPackage.dependencies as Record<string, unknown> | undefined;
      const devDependencies = parsedPackage.devDependencies as Record<string, unknown> | undefined;
      const allDeps = { ...dependencies, ...devDependencies } as Record<string, unknown> | undefined;

      const reactVersion = allDeps?.react;
      const reactDomVersion = allDeps?.["react-dom"];

      metadata.reactVersion = typeof reactVersion === "string" ? reactVersion : null;
      metadata.reactDomVersion = typeof reactDomVersion === "string" ? reactDomVersion : null;

      metadata.jsxRuntime = typeof parsedPackage.jsxRuntime === "string" ? parsedPackage.jsxRuntime : null;
      metadata.strictMode = this.extractBoolean(parsedPackage.strictMode);
      metadata.reactCompiler = typeof parsedPackage.reactCompiler === "string" ? parsedPackage.reactCompiler : null;

      const scripts = parsedPackage.scripts as Record<string, string> | undefined;
      metadata.serverComponents = this.detectServerComponents(scripts);
      metadata.clientComponents = this.detectClientComponents(scripts);
      metadata.hooksDetected = this.detectHooks(parsedPackage);
    } catch {
      metadata.exists = false;
    }

    (context.metadata as Record<string, unknown>)["react"] = metadata;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  private extractBoolean(value: unknown): boolean | null {
    if (typeof value === "boolean") {
      return value;
    }
    if (typeof value === "string") {
      const normalized = value.toLowerCase();
      if (normalized === "true") {
        return true;
      }
      if (normalized === "false") {
        return false;
      }
    }
    return null;
  }

  private detectServerComponents(scripts: Record<string, string> | undefined): boolean | null {
    if (!scripts) {
      return null;
    }

    return Object.values(scripts).some((script) => /server|next build|next dev|next start/i.test(script));
  }

  private detectClientComponents(scripts: Record<string, string> | undefined): boolean | null {
    if (!scripts) {
      return null;
    }

    return Object.values(scripts).some((script) => /client|react-scripts|vite|next dev|next build/i.test(script));
  }

  private detectHooks(parsedPackage: Record<string, unknown>): boolean | null {
    const keywords = parsedPackage.keywords as unknown;
    if (Array.isArray(keywords)) {
      return keywords.some((keyword) => typeof keyword === "string" && /react|hooks/i.test(keyword));
    }
    return null;
  }
}

import { promises as fs } from "fs";
import path from "path";
