import type { Context } from "../../core/Context.js";
import type { IRule } from "../IRule.js";
import type { Issue } from "../../core/Issue.js";
import type { Evidence } from "../../core/Evidence.js";
import type { FixSuggestion } from "../../core/FixSuggestion.js";
import { Severity } from "../../core/Severity.js";

export class PrismaIntegrityRule implements IRule {
  public readonly id = "prisma-integrity-failed";
  public readonly name = "Prisma Integrity Rule";
  public readonly category = "Prisma";

  public match(context: Context): boolean {
    const prisma = context.metadata.prisma as Record<string, unknown> | undefined;

    if (!prisma) {
      return false;
    }

    return [
      prisma.hasNamespacePrisma === false,
      prisma.hasPrismaClient === false,
      prisma.hasKnownRequestError === false,
      prisma.hasPrismaPromise === false,
      prisma.runtimeExists === false,
      prisma.generatedPrismaExists === false,
      prisma.schemaExists === false,
      prisma.hasGenerator === false,
      prisma.hasDatasource === false,
    ].some(Boolean);
  }

  public analyze(context: Context): void {
    const prisma = context.metadata.prisma as Record<string, unknown> | undefined;
    const failedFields: string[] = [];

    if (!prisma || prisma.hasNamespacePrisma === false) {
      failedFields.push("hasNamespacePrisma");
    }
    if (!prisma || prisma.hasPrismaClient === false) {
      failedFields.push("hasPrismaClient");
    }
    if (!prisma || prisma.hasKnownRequestError === false) {
      failedFields.push("hasKnownRequestError");
    }
    if (!prisma || prisma.hasPrismaPromise === false) {
      failedFields.push("hasPrismaPromise");
    }
    if (!prisma || prisma.runtimeExists === false) {
      failedFields.push("runtimeExists");
    }
    if (!prisma || prisma.generatedPrismaExists === false) {
      failedFields.push("generatedPrismaExists");
    }
    if (!prisma || prisma.schemaExists === false) {
      failedFields.push("schemaExists");
    }
    if (!prisma || prisma.hasGenerator === false) {
      failedFields.push("hasGenerator");
    }
    if (!prisma || prisma.hasDatasource === false) {
      failedFields.push("hasDatasource");
    }

    const evidenceFile = prisma?.schemaExists === false ? "schema.prisma" : "library.d.ts";
    const evidence: Evidence[] = [
      {
        id: "prisma-integrity-source",
        type: "file",
        file: evidenceFile,
        description: `Integrity indication from Prisma metadata for ${evidenceFile}`,
      },
    ];

    const issue: Issue = {
      id: "prisma-integrity-failed",
      title: "Prisma Client Integrity Failed",
      category: "Prisma",
      severity: Severity.Critical,
      message: `Prisma metadata failed integrity checks: ${failedFields.join(", ")}`,
      evidence,
      fixes: [
        {
          id: "generate-prisma-client",
          title: "Generate ulang Prisma Client",
          description: "Regenerate the Prisma Client to restore integrity.",
          risk: "low",
          automatic: false,
          steps: ["Run prisma generate in the project root."],
        },
      ],
    };

    const contextAny = context as unknown as { issues?: Issue[] };
    if (!Array.isArray(contextAny.issues)) {
      contextAny.issues = [];
    }

    contextAny.issues.push(issue);
  }
}

export enum Severity {
  Info = "info",
  Warning = "warning",
  Error = "error",
  Critical = "critical",
}

import type { Context } from "../../core/Context.js";
import type { Issue } from "../../core/Issue.js";
import type { Evidence } from "../../core/Evidence.js";
import type { FixSuggestion } from "../../core/FixSuggestion.js";
import type { IRule } from "../IRule.js";
import { Severity } from "../../core/Severity.js";

const acceptedModuleResolutions = new Set([
  "node",
  "bundler",
  "nodenext",
  "node16",
]);

export class TypeScriptConfigurationRule implements IRule {
  public readonly id = "typescript-configuration";
  public readonly name = "TypeScript Configuration";
  public readonly category = "typescript";

  public match(context: Context): boolean {
    const metadata = context.metadata as Record<string, unknown>;
    return metadata.typescript !== undefined && metadata.typescript !== null;
  }

  public analyze(context: Context): Issue[] {
    const metadata = context.metadata as Record<string, unknown>;
    const tsMetadata = metadata.typescript as Record<string, unknown> | undefined;
    const packageJson = metadata.packageJson as Record<string, unknown> | undefined;
    const workspaces = packageJson?.workspaces;
    const isWorkspaceProject = workspaces !== undefined && workspaces !== null;

    const issues: Issue[] = [];
    if (!tsMetadata) {
      return issues;
    }

    const configExists = Boolean(tsMetadata.configExists);
    const configPath = typeof tsMetadata.configPath === "string" ? tsMetadata.configPath : "tsconfig.json";
    const version = typeof tsMetadata.version === "string" ? tsMetadata.version : null;
    const strict = tsMetadata.strict === true ? true : tsMetadata.strict === false ? false : null;
    const moduleResolution = typeof tsMetadata.moduleResolution === "string" ? tsMetadata.moduleResolution : null;
    const paths = tsMetadata.paths as Record<string, unknown> | null;
    const references = Array.isArray(tsMetadata.references) ? tsMetadata.references : null;

    if (!configExists) {
      issues.push({
        id: "typescript-config-missing",
        title: "TypeScript configuration file is missing",
        category: "typescript",
        severity: Severity.Error,
        message: "tsconfig.json is not present in the project root.",
        evidence: [
          {
            id: "tsconfig-file-not-found",
            type: "file",
            file: "tsconfig.json",
            description: "TypeScript configuration file is required by the scanner.",
            expected: "tsconfig.json exists",
            actual: "not found",
          },
        ],
        fixes: [
          {
            id: "create-tsconfig",
            title: "Create tsconfig.json",
            description: "Add a tsconfig.json file with the required compiler options.",
            risk: "low",
            automatic: false,
            steps: [
              "Create tsconfig.json in the project root.",
              "Include compilerOptions like moduleResolution, target, strict, and paths as needed.",
            ],
          },
        ],
      });
    }

    if (!version) {
      issues.push({
        id: "typescript-version-missing",
        title: "TypeScript dependency is not found",
        category: "typescript",
        severity: Severity.Error,
        message: "TypeScript package version could not be resolved from node_modules or package.json.",
        evidence: [
          {
            id: "typescript-version-missing-evidence",
            type: "file",
            file: "package.json",
            description: "No TypeScript dependency was found in package.json or node_modules.",
            expected: "typescript dependency present",
            actual: "missing or version unknown",
          },
        ],
        fixes: [
          {
            id: "install-typescript",
            title: "Install TypeScript",
            description: "Add TypeScript to the project dependencies.",
            risk: "low",
            automatic: false,
            steps: ["Run npm install --save-dev typescript"],
          },
        ],
      });
    }

    if (strict === false) {
      issues.push({
        id: "typescript-strict-disabled",
        title: "TypeScript strict mode is disabled",
        category: "typescript",
        severity: Severity.Warning,
        message: "The tsconfig.json compiler option strict is set to false.",
        evidence: [
          {
            id: "typescript-strict-disabled-evidence",
            type: "file",
            file: configPath,
            description: "The strict compiler option is disabled in tsconfig.json.",
            expected: "strict: true",
            actual: "strict: false",
          },
        ],
        fixes: [
          {
            id: "enable-typescript-strict",
            title: "Enable strict mode",
            description: "Set compilerOptions.strict to true in tsconfig.json.",
            risk: "low",
            automatic: false,
            steps: ["Open tsconfig.json", "Set compilerOptions.strict to true."],
          },
        ],
      });
    }

    if (moduleResolution !== null && !acceptedModuleResolutions.has(moduleResolution.toLowerCase())) {
      issues.push({
        id: "typescript-module-resolution-invalid",
        title: "TypeScript moduleResolution is not standard",
        category: "typescript",
        severity: Severity.Warning,
        message: `moduleResolution is set to '${moduleResolution}', which is not one of the common values (${Array.from(
          acceptedModuleResolutions
        ).join(", ")}).`,
        evidence: [
          {
            id: "typescript-module-resolution-evidence",
            type: "file",
            file: configPath,
            description: "The moduleResolution setting does not match the expected configuration.",
            expected: `moduleResolution: ${Array.from(acceptedModuleResolutions).join(" or ")}`,
            actual: moduleResolution,
          },
        ],
        fixes: [
          {
            id: "fix-module-resolution",
            title: "Update moduleResolution",
            description: "Use a standard moduleResolution value in tsconfig.json.",
            risk: "low",
            automatic: false,
            steps: [
              "Open tsconfig.json",
              "Set compilerOptions.moduleResolution to node, bundler, node16, or nodenext.",
            ],
          },
        ],
      });
    }

    if (isWorkspaceProject) {
      const pathsEmpty = paths === null || (typeof paths === "object" && paths !== null && Object.keys(paths).length === 0);
      if (pathsEmpty) {
        issues.push({
          id: "typescript-paths-empty-workspace",
          title: "Compiler paths are empty in a workspace project",
          category: "typescript",
          severity: Severity.Warning,
          message: "Workspace projects should define compilerOptions.paths for package aliases and workspace imports.",
          evidence: [
            {
              id: "typescript-paths-empty-evidence",
              type: "file",
              file: configPath,
              description: "The compilerOptions.paths property is missing or empty in tsconfig.json.",
              expected: "paths contains workspace mappings",
              actual: "paths is empty or missing",
            },
          ],
          fixes: [
            {
              id: "add-typescript-paths",
              title: "Add compilerOptions.paths",
              description: "Define workspace path aliases in tsconfig.json for project modules.",
              risk: "low",
              automatic: false,
              steps: [
                "Open tsconfig.json",
                "Add compilerOptions.paths with workspace package mappings.",
              ],
            },
          ],
        });
      }

      const referencesEmpty = !Array.isArray(references) || references.length === 0;
      if (referencesEmpty) {
        issues.push({
          id: "typescript-references-empty-monorepo",
          title: "TypeScript references are empty in a monorepo",
          category: "typescript",
          severity: Severity.Warning,
          message: "Monorepos should define project references in tsconfig.json.",
          evidence: [
            {
              id: "typescript-references-empty-evidence",
              type: "file",
              file: configPath,
              description: "The references array is missing or empty for the monorepo configuration.",
              expected: "references contains project references",
              actual: "references is empty or missing",
            },
          ],
          fixes: [
            {
              id: "add-typescript-references",
              title: "Add project references",
              description: "Define TypeScript project references in tsconfig.json for monorepo builds.",
              risk: "low",
              automatic: false,
              steps: [
                "Open tsconfig.json",
                "Add a references array with each workspace project path.",
              ],
            },
          ],
        });
      }
    }

    return issues;
  }
}

import type { Context } from "../../core/Context.js";
import type { FixSuggestion } from "../../core/FixSuggestion.js";
import type { Issue } from "../../core/Issue.js";
import type { Evidence } from "../../core/Evidence.js";
import type { IRule } from "../IRule.js";
import { Severity } from "../../core/Severity.js";

export class NextJsConfigurationRule implements IRule {
  public readonly id = "nextjs-configuration";
  public readonly name = "Next.js Configuration";
  public readonly category = "next";

  public match(context: Context): boolean {
    const metadata = context.metadata as Record<string, unknown>;
    return metadata.next !== undefined && metadata.next !== null;
  }

  public analyze(context: Context): Issue[] {
    const metadata = context.metadata as Record<string, unknown>;
    const nextMetadata = metadata.next as Record<string, unknown> | null;
    if (!nextMetadata) {
      return [];
    }

    const issues: Issue[] = [];
    const nextExists = nextMetadata.exists === true;
    const configExists = nextMetadata.configExists === true;
    const appRouter = nextMetadata.appRouter === true;
    const pagesRouter = nextMetadata.pagesRouter === true;
    const turbopack = nextMetadata.turbopack === true;
    const reactVersion = typeof nextMetadata.reactVersion === "string" ? nextMetadata.reactVersion : null;
    const nextVersion = typeof nextMetadata.nextVersion === "string" ? nextMetadata.nextVersion : null;
    const typescriptEnabled = nextMetadata.typescript === true;
    const configPath = typeof nextMetadata.configPath === "string" ? nextMetadata.configPath : "next.config";

    if (!nextExists) {
      issues.push(this.createIssue({
        id: "nextjs-not-detected",
        title: "Next.js is not detected",
        severity: Severity.Error,
        message: "The project metadata does not indicate a Next.js installation.",
        evidence: [
          {
            id: "nextjs-not-detected-evidence",
            type: "metadata",
            file: "package.json",
            description: "Next package was not found in project dependencies.",
          },
        ],
        fix: {
          id: "install-nextjs",
          title: "Install Next.js",
          description: "Add Next.js to the project dependencies and configure it in package.json.",
          risk: "low",
          automatic: false,
          steps: ["Run npm install next react react-dom --save"],
        },
      }));
    }

    if (nextExists && !configExists) {
      issues.push(this.createIssue({
        id: "next-config-missing",
        title: "Next.js configuration file is missing",
        severity: Severity.Error,
        message: "next.config.js, next.config.mjs, or next.config.ts was not found.",
        evidence: [
          {
            id: "next-config-missing-evidence",
            type: "file",
            file: configPath,
            description: "Next.js configuration file is required for advanced Next.js settings.",
            expected: "next.config.js or next.config.mjs or next.config.ts exists",
            actual: "missing",
          },
        ],
        fix: {
          id: "create-next-config",
          title: "Create a Next.js configuration file",
          description: "Add a next.config.js or next.config.mjs file to configure Next.js behavior.",
          risk: "low",
          automatic: false,
          steps: ["Create next.config.js in the project root.", "Define required settings such as reactStrictMode or experimental flags."],
        },
      }));
    }

    if (appRouter && pagesRouter) {
      issues.push(this.createIssue({
        id: "next-app-and-pages-router-conflict",
        title: "App Router and Pages Router are both active",
        severity: Severity.Error,
        message: "The project appears to be using both App Router and Pages Router at the same time.",
        evidence: [
          {
            id: "next-router-mode-conflict-evidence",
            type: "metadata",
            file: configPath,
            description: "Both appRouter and pagesRouter are enabled in Next.js metadata.",
          },
        ],
        fix: {
          id: "choose-next-router",
          title: "Use a single Next.js routing mode",
          description: "Choose either the App Router or the Pages Router and remove conflicting routes or settings.",
          risk: "medium",
          automatic: false,
          steps: ["Review app/ and pages/ directories.", "Consolidate routing into one supported router mode."],
        },
      }));
    }

    if (nextExists && reactVersion && nextVersion && !this.isReactCompatibleWithNext(nextVersion, reactVersion)) {
      issues.push(this.createIssue({
        id: "next-react-version-mismatch",
        title: "React version does not match Next.js version",
        severity: Severity.Warning,
        message: `Next.js ${nextVersion} may not be compatible with React ${reactVersion}.`,
        evidence: [
          {
            id: "next-react-version-mismatch-evidence",
            type: "metadata",
            file: "package.json",
            description: "React and Next.js versions appear to be incompatible.",
            expected: "React version compatible with Next.js",
            actual: `React ${reactVersion} / Next.js ${nextVersion}`,
          },
        ],
        fix: {
          id: "align-react-next-versions",
          title: "Align React and Next.js versions",
          description: "Update package versions so React and Next.js are compatible.",
          risk: "medium",
          automatic: false,
          steps: ["Review package.json dependencies.", "Install matching React and Next.js versions."],
        },
      }));
    }

    if (nextExists && turbopack && !configExists) {
      issues.push(this.createIssue({
        id: "next-turbopack-config-issue",
        title: "Turbopack is enabled but configuration is missing or invalid",
        severity: Severity.Warning,
        message: "Turbopack was detected, but Next.js configuration is missing or does not support the setting.",
        evidence: [
          {
            id: "next-turbopack-config-evidence",
            type: "metadata",
            file: configPath,
            description: "Turbopack is enabled while the Next.js config is missing or invalid.",
            expected: "Valid next.config.* file with turbopack support",
            actual: "missing or invalid config",
          },
        ],
        fix: {
          id: "validate-turbopack-configuration",
          title: "Validate Turbopack configuration",
          description: "Ensure Turbopack is configured correctly in Next.js configuration.",
          risk: "medium",
          automatic: false,
          steps: ["Verify the Turbopack experimental settings in next.config.*.", "Remove or adjust unsupported Turbopack configuration."],
        },
      }));
    }

    if (nextExists && !typescriptEnabled) {
      issues.push(this.createIssue({
        id: "next-typescript-inactive",
        title: "TypeScript is not enabled for Next.js project",
        severity: Severity.Warning,
        message: "A Next.js project should typically use TypeScript for the best developer experience.",
        evidence: [
          {
            id: "next-typescript-inactive-evidence",
            type: "metadata",
            file: "package.json",
            description: "TypeScript is not detected in the Next.js project metadata.",
            expected: "typescript dependency present",
            actual: "typescript not enabled",
          },
        ],
        fix: {
          id: "enable-typescript-for-next",
          title: "Enable TypeScript",
          description: "Add TypeScript support to the Next.js project.",
          risk: "low",
          automatic: false,
          steps: ["Install typescript and @types/react.", "Create or update tsconfig.json."],
        },
      }));
    }

    return issues;
  }

  private isReactCompatibleWithNext(nextVersion: string, reactVersion: string): boolean {
    const nextMajor = this.parseMajorVersion(nextVersion);
    const reactMajor = this.parseMajorVersion(reactVersion);
    if (nextMajor === null || reactMajor === null) {
      return true;
    }
    if (nextMajor >= 13) {
      return reactMajor === 18 || reactMajor === 19;
    }
    if (nextMajor === 12) {
      return reactMajor === 17 || reactMajor === 18;
    }
    return reactMajor === 16 || reactMajor === 17;
  }

  private parseMajorVersion(version: string): number | null {
    const match = version.match(/\d+/);
    return match ? Number(match[0]) : null;
  }

  private createIssue(args: {
    id: string;
    title: string;
    severity: Severity;
    message: string;
    evidence: Evidence[];
    fix: FixSuggestion;
  }): Issue {
    return {
      id: args.id,
      title: args.title,
      category: this.category,
      severity: args.severity,
      message: args.message,
      evidence: args.evidence,
      fixes: [args.fix],
    };
  }
}

import type { Context } from "../../core/Context.js";
import type { FixSuggestion } from "../../core/FixSuggestion.js";
import type { Issue } from "../../core/Issue.js";
import type { Evidence } from "../../core/Evidence.js";
import type { IRule } from "../IRule.js";
import { Severity } from "../../core/Severity.js";

export class TurboConfigurationRule implements IRule {
  public readonly id = "turbo-configuration";
  public readonly name = "Turbo Configuration";
  public readonly category = "turbo";

  public match(context: Context): boolean {
    const metadata = context.metadata as Record<string, unknown>;
    return metadata.turbo !== undefined && metadata.turbo !== null;
  }

  public analyze(context: Context): Issue[] {
    const metadata = context.metadata as Record<string, unknown>;
    const turboMetadata = metadata.turbo as Record<string, unknown> | null;
    const packageJson = metadata.packageJson as Record<string, unknown> | undefined;
    if (!turboMetadata) {
      return [];
    }

    const issues: Issue[] = [];
    const configExists = turboMetadata.configExists === true;
    const configPath = typeof turboMetadata.configPath === "string" ? turboMetadata.configPath : "turbo.json";
    const tasks = turboMetadata.tasks as Record<string, unknown> | null;
    const cache = turboMetadata.cache as Record<string, unknown> | null;
    const outputs = Array.isArray(turboMetadata.outputs) ? turboMetadata.outputs.map(String) : null;
    const remoteCache = turboMetadata.remoteCache as Record<string, unknown> | null;
    const turboPackageManager = typeof turboMetadata.packageManager === "string" ? turboMetadata.packageManager : null;
    const packageJsonPackageManager = typeof packageJson?.packageManager === "string" ? packageJson.packageManager.split("@")[0] : null;

    if (!configExists) {
      issues.push(this.createIssue({
        id: "turbo-config-missing",
        title: "Turbo configuration file is missing",
        severity: Severity.Error,
        message: "turbo.json is not present in the project root.",
        evidence: [
          {
            id: "turbo-config-missing-evidence",
            type: "file",
            file: configPath,
            description: "Turbo configuration file is required for workspace task orchestration.",
            expected: "turbo.json exists",
            actual: "missing",
          },
        ],
        fix: {
          id: "create-turbo-config",
          title: "Create turbo.json",
          description: "Add a turbo.json configuration file to define tasks, cache, and outputs.",
          risk: "low",
          automatic: false,
          steps: [
            "Create turbo.json in the project root.",
            "Define tasks, pipeline, cache, and outputs according to Turbo repo conventions.",
          ],
        },
      }));
    }

    if (!tasks || Object.keys(tasks).length === 0) {
      issues.push(this.createIssue({
        id: "turbo-tasks-empty",
        title: "Turbo tasks are not configured",
        severity: Severity.Error,
        message: "The Turbo configuration defines no tasks.",
        evidence: [
          {
            id: "turbo-tasks-empty-evidence",
            type: "file",
            file: configPath,
            description: "Turbo tasks must be defined to execute workspace commands.",
            expected: "tasks object contains at least one task",
            actual: "tasks is empty or missing",
          },
        ],
        fix: {
          id: "define-turbo-tasks",
          title: "Define Turbo tasks",
          description: "Add tasks to turbo.json for build, lint, test, or other workspace commands.",
          risk: "low",
          automatic: false,
          steps: [
            "Open turbo.json.",
            "Add a tasks object with named task definitions.",
          ],
        },
      }));
    }

    const cacheInvalid = cache !== null && !this.isValidCacheConfig(cache);
    if (cacheInvalid) {
      issues.push(this.createIssue({
        id: "turbo-cache-invalid",
        title: "Turbo cache configuration is invalid",
        severity: Severity.Warning,
        message: "The cache section in turbo.json is not configured correctly.",
        evidence: [
          {
            id: "turbo-cache-invalid-evidence",
            type: "file",
            file: configPath,
            description: "Turbo cache settings should include recognized cache fields.",
            expected: "cache contains valid Turbo cache configuration",
            actual: "invalid or unsupported cache configuration",
          },
        ],
        fix: {
          id: "fix-turbo-cache",
          title: "Fix Turbo cache configuration",
          description: "Update the turbo.json cache section with supported settings.",
          risk: "low",
          automatic: false,
          steps: [
            "Open turbo.json.",
            "Ensure the cache object includes supported properties such as enabled and directory.",
          ],
        },
      }));
    }

    if (!outputs || outputs.length === 0) {
      issues.push(this.createIssue({
        id: "turbo-outputs-empty",
        title: "Turbo outputs are not configured",
        severity: Severity.Warning,
        message: "Turbo configuration does not specify outputs.",
        evidence: [
          {
            id: "turbo-outputs-empty-evidence",
            type: "file",
            file: configPath,
            description: "Turbo outputs are required for cache invalidation and task incrementalization.",
            expected: "outputs array contains output paths",
            actual: "outputs is empty or missing",
          },
        ],
        fix: {
          id: "define-turbo-outputs",
          title: "Define Turbo outputs",
          description: "Add output paths to turbo.json so Turbo can manage task cache consistency.",
          risk: "low",
          automatic: false,
          steps: [
            "Open turbo.json.",
            "Add an outputs array with files or directories produced by tasks.",
          ],
        },
      }));
    }

    if (remoteCache && !this.isValidRemoteCache(remoteCache)) {
      issues.push(this.createIssue({
        id: "turbo-remote-cache-invalid",
        title: "Turbo remote cache configuration is invalid",
        severity: Severity.Warning,
        message: "The remoteCache section in turbo.json is missing required configuration.",
        evidence: [
          {
            id: "turbo-remote-cache-invalid-evidence",
            type: "file",
            file: configPath,
            description: "Remote cache needs a valid url or GitHub remote cache configuration.",
            expected: "remoteCache contains a valid remote cache configuration",
            actual: "invalid remoteCache object",
          },
        ],
        fix: {
          id: "fix-turbo-remote-cache",
          title: "Fix Turbo remote cache settings",
          description: "Provide a valid remote cache configuration in turbo.json.",
          risk: "low",
          automatic: false,
          steps: [
            "Open turbo.json.",
            "Add or correct the remoteCache configuration with a valid url or provider.",
          ],
        },
      }));
    }

    if (
      turboPackageManager &&
      packageJsonPackageManager &&
      turboPackageManager !== packageJsonPackageManager
    ) {
      issues.push(this.createIssue({
        id: "turbo-package-manager-mismatch",
        title: "Turbo package manager does not match workspace package manager",
        severity: Severity.Warning,
        message: `turbo.json package manager is set to '${turboPackageManager}', but package.json workspace package manager is '${packageJsonPackageManager}'.`, 
        evidence: [
          {
            id: "turbo-package-manager-mismatch-evidence",
            type: "file",
            file: "package.json",
            description: "Turbo metadata package manager does not match the package.json packageManager field.",
            expected: `packageManager should be ${packageJsonPackageManager}`,
            actual: turboPackageManager,
          },
        ],
        fix: {
          id: "align-turbo-package-manager",
          title: "Align Turbo package manager with workspace package manager",
          description: "Use the same package manager in turbo.json and package.json.",
          risk: "low",
          automatic: false,
          steps: [
            "Open package.json and turbo.json.",
            "Set the packageManager value consistently across both files.",
          ],
        },
      }));
    }

    return issues;
  }

  private isValidCacheConfig(cache: Record<string, unknown>): boolean {
    const validKeys = new Set(["enabled", "directory", "cacheDirectory", "fetch", "store", "pipeline"]);
    const keys = Object.keys(cache);
    if (keys.length === 0) {
      return false;
    }
    return keys.some((key) => validKeys.has(key));
  }

  private isValidRemoteCache(remoteCache: Record<string, unknown>): boolean {
    if (Object.keys(remoteCache).length === 0) {
      return false;
    }

    const url = typeof remoteCache.url === "string" ? remoteCache.url.trim() : "";
    const github = typeof remoteCache.github === "object" && remoteCache.github !== null;

    return url.length > 0 || github;
  }

  private createIssue(args: {
    id: string;
    title: string;
    severity: Severity;
    message: string;
    evidence: Evidence[];
    fix: FixSuggestion;
  }): Issue {
    return {
      id: args.id,
      title: args.title,
      category: this.category,
      severity: args.severity,
      message: args.message,
      evidence: args.evidence,
      fixes: [args.fix],
    };
  }
}

import type { Context } from "../../core/Context.js";
import type { FixSuggestion } from "../../core/FixSuggestion.js";
import type { Issue } from "../../core/Issue.js";
import type { Evidence } from "../../core/Evidence.js";
import type { IRule } from "../IRule.js";
import { Severity } from "../../core/Severity.js";

export class DependencyConflictRule implements IRule {
  public readonly id = "dependency-conflict";
  public readonly name = "Dependency Conflict";
  public readonly category = "dependency";

  public match(context: Context): boolean {
    const metadata = context.metadata as Record<string, unknown>;
    return metadata.dependencies !== undefined && metadata.dependencies !== null;
  }

  public analyze(context: Context): Issue[] {
    const metadata = context.metadata as Record<string, unknown>;
    const dependenciesMetadata = metadata.dependencies as Record<string, unknown> | null;
    if (!dependenciesMetadata) {
      return [];
    }

    const duplicatePackages = Array.isArray(dependenciesMetadata.duplicatePackages)
      ? dependenciesMetadata.duplicatePackages.map(String)
      : [];
    const versionConflicts = dependenciesMetadata.versionConflicts as Record<string, unknown> | null;
    const circularCandidates = Array.isArray(dependenciesMetadata.circularCandidates)
      ? dependenciesMetadata.circularCandidates.filter(Array.isArray).map((cycle) => cycle.map(String))
      : [];
    const unusedCandidates = Array.isArray(dependenciesMetadata.unusedCandidates)
      ? dependenciesMetadata.unusedCandidates.map(String)
      : [];
    const peerDependencies = Array.isArray(dependenciesMetadata.peerDependencies)
      ? dependenciesMetadata.peerDependencies.map(String)
      : [];

    const issues: Issue[] = [];

    if (duplicatePackages.length > 0) {
      issues.push(this.createIssue({
        id: "duplicate-package-dependencies",
        title: "Duplicate package declarations detected",
        severity: Severity.Warning,
        message: `Found duplicate package declarations for ${duplicatePackages.join(", ")}.`,
        evidence: [
          {
            id: "duplicate-package-dependencies-evidence",
            type: "metadata",
            file: "package.json",
            description: "The dependency graph contains packages declared multiple times across workspace packages.",
            expected: "Each package is declared once",
            actual: duplicatePackages.join(", "),
          },
        ],
        fix: {
          id: "remove-duplicate-dependencies",
          title: "Remove duplicate dependency declarations",
          description: "Ensure each package dependency is declared only once in workspace package definitions.",
          risk: "low",
          automatic: false,
          steps: [
            "Review package.json files in the workspace.",
            "Consolidate duplicate dependency declarations and keep a single version.",
          ],
        },
      }));
    }

    if (versionConflicts && Object.keys(versionConflicts).length > 0) {
      const conflictEntries = Object.entries(versionConflicts).map(
        ([name, versions]) => `${name}: ${Array.isArray(versions) ? versions.join(", ") : String(versions)}`
      );

      issues.push(this.createIssue({
        id: "dependency-version-conflicts",
        title: "Dependency version conflicts detected",
        severity: Severity.Warning,
        message: `Found version conflicts for dependencies: ${conflictEntries.join("; ")}.`,
        evidence: [
          {
            id: "dependency-version-conflicts-evidence",
            type: "metadata",
            file: "package.json",
            description: "Some dependencies are required at multiple versions across workspace packages.",
            expected: "Single version per dependency",
            actual: conflictEntries.join("; "),
          },
        ],
        fix: {
          id: "resolve-version-conflicts",
          title: "Resolve dependency version conflicts",
          description: "Align dependency versions across workspace packages so the same package uses one version.",
          risk: "medium",
          automatic: false,
          steps: [
            "Review the version conflict report.",
            "Update package.json files so conflicting dependencies use a single compatible version.",
          ],
        },
      }));
    }

    if (circularCandidates.length > 0) {
      issues.push(this.createIssue({
        id: "circular-dependency-candidates",
        title: "Circular dependency candidates detected",
        severity: Severity.Error,
        message: `Detected ${circularCandidates.length} circular dependency candidate(s).`,
        evidence: [
          {
            id: "circular-dependency-candidates-evidence",
            type: "metadata",
            file: "package.json",
            description: "A circular dependency was detected among workspace packages.",
            expected: "Acyclic dependency graph",
            actual: circularCandidates.map((cycle) => cycle.join(" -> ")).join("; "),
          },
        ],
        fix: {
          id: "break-circular-dependencies",
          title: "Break circular dependencies",
          description: "Refactor dependencies to remove cycles between packages.",
          risk: "medium",
          automatic: false,
          steps: [
            "Identify the cycle path from the evidence.",
            "Refactor dependencies so packages no longer depend on each other in a loop.",
          ],
        },
      }));
    }

    if (unusedCandidates.length > 0) {
      issues.push(this.createIssue({
        id: "unused-dependency-candidates",
        title: "Unused dependency candidates found",
        severity: Severity.Warning,
        message: `Found unused dependency candidate(s): ${unusedCandidates.join(", ")}.`,
        evidence: [
          {
            id: "unused-dependency-candidates-evidence",
            type: "metadata",
            file: "package.json",
            description: "These workspace packages were declared but are not referenced by other packages.",
            expected: "Unused dependencies should be removed or referenced",
            actual: unusedCandidates.join(", "),
          },
        ],
        fix: {
          id: "remove-unused-dependencies",
          title: "Remove unused dependencies",
          description: "Delete unused dependency declarations or reintroduce references if they are required.",
          risk: "low",
          automatic: false,
          steps: [
            "Review unused dependency candidates.",
            "Remove unused dependencies from package.json or use them in code if needed.",
          ],
        },
      }));
    }

    const peerMismatchNames = this.getPeerMismatchNames(peerDependencies, versionConflicts);
    if (peerMismatchNames.length > 0) {
      issues.push(this.createIssue({
        id: "peer-dependency-mismatch",
        title: "Peer dependency mismatch detected",
        severity: Severity.Warning,
        message: `Peer dependency mismatch found for: ${peerMismatchNames.join(", ")}.`,
        evidence: [
          {
            id: "peer-dependency-mismatch-evidence",
            type: "metadata",
            file: "package.json",
            description: "Peer dependencies have conflicting requirements or are declared inconsistently.",
            expected: "Peer dependencies should resolve to a compatible version",
            actual: peerMismatchNames.join(", "),
          },
        ],
        fix: {
          id: "resolve-peer-dependency-mismatch",
          title: "Resolve peer dependency mismatch",
          description: "Align peer dependency versions so they satisfy all package requirements.",
          risk: "medium",
          automatic: false,
          steps: [
            "Review peer dependency requirements across workspace packages.",
            "Update peer dependency versions to a compatible range.",
          ],
        },
      }));
    }

    return issues;
  }

  private getPeerMismatchNames(peerDependencies: string[], versionConflicts: Record<string, unknown> | null): string[] {
    if (!versionConflicts) {
      return [];
    }

    return peerDependencies.filter((name) =>
      Object.prototype.hasOwnProperty.call(versionConflicts, name)
    );
  }

  private createIssue(args: {
    id: string;
    title: string;
    severity: Severity;
    message: string;
    evidence: Evidence[];
    fix: FixSuggestion;
  }): Issue {
    return {
      id: args.id,
      title: args.title,
      category: this.category,
      severity: args.severity,
      message: args.message,
      evidence: args.evidence,
      fixes: [args.fix],
    };
  }
}

import type { Context } from "../core/Context.js";
import type { Issue } from "../core/Issue.js";
import type { Diagnosis } from "./Diagnosis.js";
import { mapFixSuggestion } from "./Diagnosis.js";
import DiagnosisManager from "./DiagnosisManager.js";
import { Severity } from "../core/Severity.js";
import type { IEngine } from "../core/IEngine.js";

export class DiagnosticEngine implements IEngine {
  public readonly name = "DiagnosticEngine";
  private readonly manager: DiagnosisManager;

  constructor(manager?: DiagnosisManager) {
    this.manager = manager ?? new DiagnosisManager();
  }

  async run(context: Context): Promise<void> {
    const issues: readonly Issue[] = context.getIssues();
    const diagnoses: Diagnosis[] = issues.map((issue) => this.issueToDiagnosis(issue));
    this.manager.addMany(diagnoses);
    context.diagnosis = diagnoses;
  }

  private issueToDiagnosis(issue: Issue): Diagnosis {
    const confidence = this.mapSeverityToConfidence(issue.severity);
    const affectedFiles = issue.file ? [issue.file] : [];
    const recommendedFixes = (issue.fixes ?? []).map(mapFixSuggestion);
    const automaticFixAvailable = recommendedFixes.some((f) => f.automatic === true);

    const estimatedRepairTime = this.estimateRepairTime(recommendedFixes);

    return {
      id: issue.id,
      title: issue.title ?? issue.message ?? issue.id,
      rootCause: issue.category ?? issue.message ?? "unknown",
      confidence,
      description: issue.message ?? "",
      affectedFiles,
      recommendedFixes,
      estimatedRepairTime,
      automaticFixAvailable,
    };
  }

  private mapSeverityToConfidence(severity: Issue["severity"]) {
    switch (severity) {
      case Severity.Critical:
        return 90;
      case Severity.Error:
        return 80;
      case Severity.Warning:
        return 60;
      default:
        return 40;
    }
  }

  private estimateRepairTime(fixes: Diagnosis["recommendedFixes"]) : number | null {
    if (!fixes || fixes.length === 0) return null;
    // simple heuristic: low=30m, medium=120m, high=480m; sum and average
    const totals = fixes.map((f) => {
      if (f.risk === "low") return 30;
      if (f.risk === "medium") return 120;
      return 480;
    });
    const sum = totals.reduce((a, b) => a + b, 0);
    return Math.round(sum / totals.length);
  }
}

export default DiagnosticEngine;

import type { FixSuggestion } from "../core/FixSuggestion.js";

