import fs from "node:fs/promises";
import path from "node:path";
import { CommandExecutor } from "../commands/CommandExecutor.js";
import type { Context, RepairLogEntry } from "../core/Context.js";
import { RepairPlanner } from "./RepairPlanner.js";
import type { IEngine } from "../core/IEngine.js";

export class RepairEngine implements IEngine {
  public readonly name = "RepairEngine";
  private readonly planner: RepairPlanner;
  private readonly executor: CommandExecutor;

  constructor(planner?: RepairPlanner, executor?: CommandExecutor) {
    this.planner = planner ?? new RepairPlanner();
    this.executor = executor ?? new CommandExecutor();
  }

  async run(context: Context): Promise<void> {
    const rootCauses = context.rootCauses ?? [];
    const repairPlans = (context.repairPlans?.length ? context.repairPlans : rootCauses.map((rootCause) => this.planner.plan(rootCause))).slice();
    context.repairPlans = repairPlans;

    const repairOptions = context.repairOptions ?? {};
    const maxSteps = repairOptions.maxSteps ?? Number.MAX_SAFE_INTEGER;
    let stepCount = 0;
    let hitMaxSteps = false;

    for (const plan of repairPlans) {
      for (const step of plan.steps) {
        if (stepCount >= maxSteps) {
          this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "skipped", "Reached the configured repair-step limit.", undefined);
          hitMaxSteps = true;
          break;
        }

        const action = this.resolveAction(step);
        if (!action) {
          this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "skipped", "No executable repair action matched the step.", undefined);
          stepCount += 1;
          continue;
        }

        if (!step.automatic && !this.canAutoApply(step)) {
          this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "skipped", "No executable repair action matched the step.", undefined);
          stepCount += 1;
          continue;
        }

        const targetPath = path.resolve(context.projectRoot, action.filePath);
        const status = repairOptions.dryRun ? "dry-run" : "applied";
        const message = repairOptions.dryRun
          ? `Dry-run: would ${action.description.toLowerCase()} (${path.relative(context.projectRoot, targetPath) || action.filePath}).`
          : `${action.description} (${path.relative(context.projectRoot, targetPath) || action.filePath}).`;

        let retryCount = 0;
        if (!repairOptions.dryRun) {
          const applied = await this.applyAction(targetPath, action, context);
          if (!applied) {
            this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "failed", `Repair action failed for ${path.relative(context.projectRoot, targetPath) || action.filePath}.`, targetPath, "failed", retryCount);
            continue;
          }
          retryCount += 1;
        }

        this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, status, message, targetPath, undefined, retryCount);
        stepCount += 1;
      }
    }

    // Store execution completeness flag in metadata for downstream consumers
    context.metadata = {
      ...context.metadata,
      repairExecutionCompleted: !hitMaxSteps,
    } as typeof context.metadata & { repairExecutionCompleted?: boolean };
  }

  private canAutoApply(step: { title: string; description: string; automatic?: boolean }): boolean {
    return step.automatic === true || /auto|generate|tsconfig|prisma|typescript/i.test(`${step.title}\n${step.description}`);
  }

  private resolveAction(step: { title: string; description: string }): { filePath: string; content: string; description: string } | undefined {
    const text = `${step.title}\n${step.description}`.toLowerCase();
    if (text.includes("tsconfig") || text.includes("typescript") || text.includes("prisma") || text.includes("generate")) {
      return {
        filePath: "tsconfig.json",
        description: "Create a minimal TypeScript configuration file",
        content: `{
  "compilerOptions": {
    "target": "ES2020",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "strict": false
  }
}
`,
      };
    }

    return undefined;
  }

  private async applyAction(targetPath: string, action: { filePath: string; content: string; description: string }, context: Context): Promise<boolean> {
    try {
      await fs.mkdir(path.dirname(targetPath), { recursive: true });
      const exists = await fs.access(targetPath).then(() => true).catch(() => false);
      if (exists) {
        await fs.copyFile(targetPath, `${targetPath}.bak`);
      }
      await fs.writeFile(targetPath, action.content, "utf8");
      if (context.projectRoot) {
        await this.executor.pnpm(["--version"], context.projectRoot);
      }
      return true;
    } catch {
      return false;
    }
  }

  private pushLog(context: Context, planId: string | undefined, rootCauseId: string | undefined, stepId: string | undefined, title: string, status: RepairLogEntry["status"], message: string, filePath: string | undefined, rollbackStatus?: RepairLogEntry["rollbackStatus"], retryCount?: number): void {
    const entry: RepairLogEntry = {
      id: `${planId ?? "plan"}-${stepId ?? title}-${status}-${Date.now()}`,
      planId,
      rootCauseId,
      stepId,
      title,
      status,
      message,
      filePath,
      timestamp: new Date().toISOString(),
      rollbackStatus,
      retryCount,
    };
    context.repairLog = [...(context.repairLog ?? []), entry];
  }
}

export default RepairEngine;

import type { RootCause } from "../rootcause/RootCause.js";
import type { RepairStep } from "./RepairStep.js";
import type { RepairPlan } from "./RepairPlan.js";

function estimateRisk(text: string): "low" | "medium" | "high" {
  const lower = text.toLowerCase();
  if (lower.includes("critical") || lower.includes("urgent") || lower.includes("important")) {
    return "high";
  }
  if (lower.includes("fix") || lower.includes("validate") || lower.includes("review")) {
    return "medium";
  }
  return "low";
}

function estimateTime(text: string): number {
  const lower = text.toLowerCase();
  if (lower.includes("refactor") || lower.includes("upgrade") || lower.includes("migrate")) {
    return 180;
  }
  if (lower.includes("fix") || lower.includes("resolve") || lower.includes("update")) {
    return 90;
  }
  return 60;
}

export class RepairPlanner {
  public plan(rootCause: RootCause): RepairPlan {
    const steps = this.buildSteps(rootCause);
    const orderedSteps = this.sortSteps(steps);
    const totalEstimatedTime = orderedSteps.reduce((total, step) => total + step.estimatedTime, 0);

    return {
      id: `repair-plan:${rootCause.id}`,
      rootCauseId: rootCause.id,
      title: `Repair plan for ${rootCause.title}`,
      description: rootCause.description,
      steps: orderedSteps,
      totalEstimatedTime,
      priority: rootCause.priority,
    };
  }

  private buildSteps(rootCause: RootCause): RepairStep[] {
    const steps: RepairStep[] = rootCause.repairSteps.map((text, index) => {
      const metadata = this.parseStepMetadata(text);
      return {
        id: `${rootCause.id}-step-${index + 1}`,
        title: metadata.title,
        description: metadata.description,
        estimatedTime: metadata.estimatedTime,
        automatic: metadata.automatic,
        risk: metadata.risk,
        dependsOn: metadata.dependsOn,
      };
    });

    return steps;
  }

  private parseStepMetadata(text: string): {
    title: string;
    description: string;
    estimatedTime: number;
    automatic: boolean;
    risk: "low" | "medium" | "high";
    dependsOn: string[];
  } {
    const dependsOn: string[] = [];
    let title = text.trim();
    const metadataMatch = text.match(/\[dependsOn:\s*([^\]]+)\]/i);

    if (metadataMatch) {
      title = title.replace(metadataMatch[0], "").trim();
      dependsOn.push(
        ...metadataMatch[1]
          .split(",")
          .map((chunk) => chunk.trim())
          .filter(Boolean)
      );
    }

    return {
      title,
      description: text,
      estimatedTime: estimateTime(title),
      automatic: /auto(mat(ic)?)?/i.test(title),
      risk: estimateRisk(title),
      dependsOn,
    };
  }

  private sortSteps(steps: RepairStep[]): RepairStep[] {
    const output: RepairStep[] = [];
    const remaining = new Map(steps.map((step) => [step.id, step]));
    const dependencyMap = new Map<string, Set<string>>();

    for (const step of steps) {
      dependencyMap.set(step.id, new Set(step.dependsOn.map((d) => this.resolveStepId(d, steps))));
    }

    while (remaining.size > 0) {
      const ready = Array.from(remaining.values()).filter((step) => {
        const deps = dependencyMap.get(step.id);
        if (!deps) return true;
        return Array.from(deps).every((depId) => !remaining.has(depId) || depId === step.id ? true : !remaining.has(depId));
      });

      if (ready.length === 0) {
        output.push(...Array.from(remaining.values()));
        break;
      }

      ready.sort((a, b) => a.risk.localeCompare(b.risk));
      const nextStep = ready[0];
      output.push(nextStep);
      remaining.delete(nextStep.id);
    }

    return output;
  }

  private resolveStepId(dependency: string, steps: RepairStep[]): string {
    const match = steps.find((step) => step.title === dependency || step.id === dependency);
    return match ? match.id : dependency;
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import { CommandExecutor } from "../commands/CommandExecutor.js";
import type { Context, RepairLogEntry } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { RollbackManager } from "../fixer/RollbackManager.js";
import { PrismaScanner } from "../scanner/PrismaScanner.js";
import { deriveRepairLifecycleState, normalizeRepairState, statusToLoopReason } from "../repair/RepairLifecycle.js";

interface RepairExecutionResult {
  attempted: boolean;
  action: string;
  command?: string;
  operation?: string;
  success: boolean;
  changed: boolean;
  error?: string;
}

interface RepairAction {
  kind: "prisma-generate" | "file-write";
  description: string;
  filePath?: string;
  content?: string;
  command?: string;
  args?: string[];
  operation?: string;
}

export class AutoRepairEngine implements IEngine {
  public readonly name = "AutoRepairEngine";
  private readonly executor: CommandExecutor;
  private readonly rollbackManager: RollbackManager;
  private readonly scanner: PrismaScanner;

  constructor(executor?: CommandExecutor, rollbackManager?: RollbackManager, scanner?: PrismaScanner) {
    this.executor = executor ?? new CommandExecutor();
    this.rollbackManager = rollbackManager ?? new RollbackManager();
    this.scanner = scanner ?? new PrismaScanner();
  }

  async run(context: Context): Promise<void> {
    const repairOptions = context.repairOptions ?? {};
    const maxAttempts = Math.max(1, repairOptions.maxSteps ?? 3);
    const beforeIssues = context.getIssues();
    const beforeIssueCount = beforeIssues.length;
    const beforeHealth = context.health?.score ?? 0;
    const startedAt = Date.now();

    context.repairLoop = {
      attempt: 0,
      completed: false,
      reason: "started",
    };

    let attempts = 0;
    let changed = false;
    let reason = "no-repair-needed";
    let repairApplied = false;
    let repairAttempted = false;
    let repairExecutionSucceeded = true;
    let actualRepairAction: string | undefined;
    const failedIssueIds: string[] = [];

    repairLoop: while (attempts < maxAttempts) {
      const issues = context.getIssues();
      const repairPlans = context.repairPlans ?? [];

      if (issues.length === 0 || repairPlans.length === 0) {
        normalizeRepairState(context);
        if (repairApplied) {
          reason = "resolved";
        } else {
          reason = issues.length === 0 ? "no-issues" : "no-repair-plans";
        }
        break;
      }

      let attemptChanged = false;
      for (const plan of repairPlans) {
        for (const step of plan.steps) {
          const action = this.resolveAction(step);
          if (!action) {
            this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "skipped", "No actionable repair step matched the current plan.", undefined);
            continue;
          }

          repairAttempted = true;
          actualRepairAction = action.description;
          const targetPath = action.filePath ? path.resolve(context.projectRoot, action.filePath) : undefined;
          if (repairOptions.dryRun) {
            const dryRunPath = targetPath ? path.relative(context.projectRoot, targetPath) || action.filePath : action.operation ?? action.description;
            this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "dry-run", `Dry-run: ${action.description} (${dryRunPath}).`, targetPath);
            attemptChanged = true;
            continue;
          }

          const backupId = targetPath ? await this.backupFile(targetPath, plan.id) : undefined;
          const executionResult = await this.dispatchAction(context, action);
          if (!executionResult.success) {
            if (targetPath) {
              await this.restoreBackup(targetPath, backupId);
            }
            this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "failed", `Repair action failed: ${executionResult.error ?? "unknown error"}.`, targetPath, targetPath ? "restored" : "none");
            repairExecutionSucceeded = false;
            failedIssueIds.push(step.id ?? action.description);
            reason = "failed";
            attempts = maxAttempts;
            break repairLoop;
          }

          const resolved = await this.recheckIssueResolution(context);
          if (!resolved) {
            this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "failed", `Repair action was applied but the targeted issue remains unresolved.`, targetPath, "none");
            failedIssueIds.push(step.id ?? action.description);
            reason = "ineffective";
            attempts = maxAttempts;
            break repairLoop;
          }

          normalizeRepairState(context);
          this.pushLog(context, plan.id, plan.rootCauseId, step.id, step.title, "applied", `${action.description} (${executionResult.operation ?? action.operation ?? action.description}).`, targetPath, "none");
          repairApplied = true;
          reason = "resolved";
          attemptChanged = true;
          break;
        }
      }

      changed = changed || attemptChanged;
      attempts += 1;
      if (!attemptChanged) {
        reason = "no-change";
        break;
      }
    }

    const afterIssues = context.getIssues();
    // Check if repair execution was incomplete (e.g., due to maxSteps limit)
    const executionCompleted = (context.metadata as Record<string, unknown>)?.repairExecutionCompleted !== false;
    const lifecycle = deriveRepairLifecycleState({
      beforeIssues,
      afterIssues,
      repairAttempted,
      repairExecutionSucceeded,
      repairSkipped: false,
      repairAttemptCount: attempts,
      actualRepairAction,
      failedIssueIds,
      executionCompleted,
    });

    context.repairLoop = {
      attempt: attempts,
      completed: true,
      reason: statusToLoopReason(lifecycle.repairStatus),
    };
    context.metadata = {
      ...context.metadata,
      repairExecutionCompleted: executionCompleted,
    } as typeof context.metadata & { repairExecutionCompleted?: boolean };
    context.repairSummary = {
      beforeIssueCount,
      afterIssueCount: afterIssues.length,
      beforeHealth,
      afterHealth: context.health?.score ?? beforeHealth,
      fixedIssueCount: Math.max(0, beforeIssueCount - afterIssues.length),
      remainingIssueCount: afterIssues.length,
      durationMs: Date.now() - startedAt,
      rollbackStatus: context.repairLog?.some((entry) => entry.rollbackStatus === "restored") ? "restored" : "none",
      beforeIssueIds: lifecycle.beforeIssueIds,
      afterIssueIds: lifecycle.afterIssueIds,
      resolvedIssueIds: lifecycle.resolvedIssueIds,
      remainingIssueIds: lifecycle.remainingIssueIds,
      failedIssueIds: lifecycle.failedIssueIds,
      repairStatus: lifecycle.repairStatus,
      repairAttemptCount: lifecycle.repairAttemptCount,
      actualRepairAction: lifecycle.actualRepairAction,
      verificationPassed: lifecycle.verificationPassed,
      verificationReasons: lifecycle.verificationReasons,
    };
  }

  private async recheckIssueResolution(context: Context): Promise<boolean> {
    await this.scanner.scan(context);

    const prisma = context.metadata.prisma as Record<string, unknown> | undefined;
    if (!prisma) {
      return true;
    }

    const issues = context.getIssues();
    const prismaIssues = issues.filter((issue) => issue.category === "Prisma");

    const unresolvedFlags = [
      prisma.hasNamespacePrisma === false,
      prisma.hasPrismaClient === false,
      prisma.hasKnownRequestError === false,
      prisma.hasPrismaPromise === false,
      prisma.runtimeExists === false,
      prisma.generatedPrismaExists === false,
      prisma.schemaExists === false,
      prisma.hasGenerator === false,
      prisma.hasDatasource === false,
    ];

    if (unresolvedFlags.some(Boolean)) {
      return false;
    }

    if (prismaIssues.length > 0) {
      const remainingIssueIds = new Set(context.getIssues().filter((issue) => issue.category !== "Prisma").map((issue) => issue.id));
      context.issues = context.issues.filter((issue) => issue.category !== "Prisma");
      context.diagnosis = (context.diagnosis ?? []).filter((entry) => remainingIssueIds.has(entry.id));
    }
    return true;
  }

  private resolveAction(step: { title: string; description: string }): RepairAction | undefined {
    const text = `${step.title}\n${step.description}`.toLowerCase();
    if (text.includes("prisma")) {
      return {
        kind: "prisma-generate",
        description: "Run Prisma client generation",
        command: "prisma",
        args: ["generate"],
        operation: "prisma generate",
      };
    }

    if (text.includes("tsconfig") || text.includes("typescript")) {
      return {
        kind: "file-write",
        filePath: "tsconfig.json",
        description: "Create a minimal TypeScript configuration file",
        content: `{
  "compilerOptions": {
    "target": "ES2020",
    "module": "NodeNext",
    "moduleResolution": "NodeNext",
    "strict": false
  }
}
`,
        operation: "write tsconfig.json",
      };
    }

    return undefined;
  }

  private async backupFile(targetPath: string, planId: string): Promise<string | undefined> {
    try {
      const exists = await fs.access(targetPath).then(() => true).catch(() => false);
      if (!exists) {
        return undefined;
      }
      const backupPath = `${targetPath}.bak`;
      await fs.copyFile(targetPath, backupPath);
      this.rollbackManager.registerBackup({ id: backupPath, path: targetPath, createdAt: new Date().toISOString(), metadata: { planId } });
      return backupPath;
    } catch {
      return undefined;
    }
  }

  private async restoreBackup(targetPath: string, backupId?: string): Promise<void> {
    if (!backupId) {
      return;
    }
    try {
      await fs.copyFile(backupId, targetPath);
    } catch {
      // best effort rollback
    }
  }

  private async dispatchAction(context: Context, action: RepairAction): Promise<RepairExecutionResult> {
    if (action.kind === "prisma-generate") {
      const result = await this.executor.prisma(action.args ?? ["generate"], context.projectRoot);
      return {
        attempted: true,
        action: action.description,
        command: action.command,
        operation: action.operation,
        success: result.exitCode === 0,
        changed: result.exitCode === 0,
        error: result.exitCode === 0 ? undefined : result.stderr || result.stdout || "Prisma generation failed",
      };
    }

    if (!action.filePath || !action.content) {
      return { attempted: true, action: action.description, success: false, changed: false, error: "No file target was defined for the repair action." };
    }

    const targetPath = path.resolve(context.projectRoot, action.filePath);
    try {
      await fs.mkdir(path.dirname(targetPath), { recursive: true });
      await fs.writeFile(targetPath, action.content, "utf8");
      return { attempted: true, action: action.description, operation: action.operation, success: true, changed: true };
    } catch (error) {
      return { attempted: true, action: action.description, operation: action.operation, success: false, changed: false, error: error instanceof Error ? error.message : String(error) };
    }
  }

  private pushLog(context: Context, planId: string | undefined, rootCauseId: string | undefined, stepId: string | undefined, title: string, status: RepairLogEntry["status"], message: string, filePath: string | undefined, rollbackStatus?: RepairLogEntry["rollbackStatus"]): void {
    const entry: RepairLogEntry = {
      id: `${planId ?? "plan"}-${stepId ?? title}-${status}-${Date.now()}`,
      planId,
      rootCauseId,
      stepId,
      title,
      status,
      message,
      filePath,
      timestamp: new Date().toISOString(),
      rollbackStatus,
    };
    context.repairLog = [...(context.repairLog ?? []), entry];
  }
}

export default AutoRepairEngine;

export interface BackupRecord {
  id: string;
  path: string;
  createdAt: string;
  metadata?: Record<string, unknown>;
}

export interface RollbackSession {
  id: string;
  createdAt: string;
  backups: BackupRecord[];
}

export class RollbackManager {
  private readonly backups = new Map<string, BackupRecord>();
  private readonly sessions = new Map<string, RollbackSession>();

  public registerBackup(backup: BackupRecord): void {
    this.backups.set(backup.id, backup);
  }

  public createSession(sessionId: string): RollbackSession {
    const session: RollbackSession = {
      id: sessionId,
      createdAt: new Date().toISOString(),
      backups: [],
    };
    this.sessions.set(sessionId, session);
    return session;
  }

  public restoreSession(sessionId: string): RollbackSession | null {
    return this.sessions.get(sessionId) ?? null;
  }

  public cleanup(sessionId: string): boolean {
    return this.sessions.delete(sessionId);
  }

  public listBackups(): BackupRecord[] {
    return Array.from(this.backups.values());
  }
}

import type { Context } from "../core/Context.js";
import type { Issue } from "../core/Issue.js";

export type RepairLifecycleStatus = "ALREADY_HEALTHY" | "RESOLVED" | "PARTIALLY_RESOLVED" | "INEFFECTIVE" | "FAILED" | "SKIPPED";

export interface RepairLifecycleState {
  beforeIssueIds: string[];
  afterIssueIds: string[];
  resolvedIssueIds: string[];
  remainingIssueIds: string[];
  failedIssueIds: string[];
  repairStatus: RepairLifecycleStatus;
  repairAttemptCount: number;
  actualRepairAction?: string;
  verificationPassed: boolean;
  verificationReasons: string[];
}

export function deriveRepairLifecycleState(params: {
  beforeIssues: readonly Issue[];
  afterIssues: readonly Issue[];
  repairAttempted?: boolean;
  repairExecutionSucceeded?: boolean;
  repairSkipped?: boolean;
  repairAttemptCount?: number;
  actualRepairAction?: string;
  failedIssueIds?: readonly string[];
  executionCompleted?: boolean;
}): RepairLifecycleState {
  const beforeIssueIds = uniqueIds(params.beforeIssues);
  const afterIssueIds = uniqueIds(params.afterIssues);
  const resolvedIssueIds = beforeIssueIds.filter((issueId) => !afterIssueIds.includes(issueId));
  const remainingIssueIds = afterIssueIds.filter((issueId) => beforeIssueIds.includes(issueId));
  const failedIssueIds = uniqueIds(params.failedIssueIds ?? []);

  let repairStatus: RepairLifecycleStatus;
  if (!params.repairAttempted) {
    repairStatus = beforeIssueIds.length === 0 ? "ALREADY_HEALTHY" : params.repairSkipped ? "SKIPPED" : "INEFFECTIVE";
  } else if (params.repairSkipped) {
    repairStatus = "SKIPPED";
  } else if (!params.repairExecutionSucceeded) {
    repairStatus = "FAILED";
  } else if (beforeIssueIds.length === 0) {
    repairStatus = "ALREADY_HEALTHY";
  } else if (afterIssueIds.length === 0) {
    // If execution was incomplete (e.g., hit maxSteps limit), do not report RESOLVED
    // Report as PARTIALLY_RESOLVED instead to indicate incomplete work
    repairStatus = params.executionCompleted === false ? "PARTIALLY_RESOLVED" : "RESOLVED";
  } else if (resolvedIssueIds.length > 0 && remainingIssueIds.length > 0) {
    repairStatus = "PARTIALLY_RESOLVED";
  } else {
    repairStatus = "INEFFECTIVE";
  }

  return {
    beforeIssueIds,
    afterIssueIds,
    resolvedIssueIds,
    remainingIssueIds,
    failedIssueIds,
    repairStatus,
    repairAttemptCount: params.repairAttemptCount ?? 0,
    actualRepairAction: params.actualRepairAction,
    verificationPassed: repairStatus === "ALREADY_HEALTHY" || repairStatus === "RESOLVED",
    verificationReasons: repairStatus === "ALREADY_HEALTHY" || repairStatus === "RESOLVED" ? [] : [`Repair lifecycle status: ${repairStatus}`],
  };
}

export function normalizeRepairState(context: Pick<Context, "diagnosis" | "rootCauses" | "repairPlans" | "getIssues">): void {
  const activeIssues = context.getIssues();
  const activeIssueIds = new Set(activeIssues.map((issue) => issue.id));

  if (activeIssues.length === 0) {
    context.diagnosis = [];
    context.rootCauses = [];
    context.repairPlans = [];
    return;
  }

  context.diagnosis = (context.diagnosis ?? []).filter((entry) => activeIssueIds.has(entry.id));

  const activeRootCauses = (context.rootCauses ?? []).filter((rootCause) => {
    const evidenceIds = new Set(rootCause.evidence.map((issue) => issue.id));
    return Array.from(evidenceIds).some((issueId) => activeIssueIds.has(issueId));
  });

  const activeRootCauseIds = new Set(activeRootCauses.map((rootCause) => rootCause.id));
  context.rootCauses = activeRootCauses;
  context.repairPlans = (context.repairPlans ?? []).filter((plan) => activeRootCauseIds.has(plan.rootCauseId));
}

export function statusToLoopReason(status: RepairLifecycleStatus): string {
  switch (status) {
    case "ALREADY_HEALTHY":
      return "no-issues";
    case "RESOLVED":
      return "resolved";
    case "PARTIALLY_RESOLVED":
      return "partially-resolved";
    case "INEFFECTIVE":
      return "ineffective";
    case "FAILED":
      return "failed";
    case "SKIPPED":
      return "skipped";
    default:
      return "unknown";
  }
}

export function reasonToStatus(reason?: string): RepairLifecycleStatus {
  switch (reason) {
    case "ALREADY_HEALTHY":
      return "ALREADY_HEALTHY";
    case "RESOLVED":
      return "RESOLVED";
    case "PARTIALLY_RESOLVED":
      return "PARTIALLY_RESOLVED";
    case "INEFFECTIVE":
      return "INEFFECTIVE";
    case "FAILED":
      return "FAILED";
    case "SKIPPED":
      return "SKIPPED";
    case "no-issues":
      return "ALREADY_HEALTHY";
    case "resolved":
      return "RESOLVED";
    case "partially-resolved":
      return "PARTIALLY_RESOLVED";
    case "ineffective":
      return "INEFFECTIVE";
    case "failed":
      return "FAILED";
    case "skipped":
      return "SKIPPED";
    case "no-repair-needed":
      return "ALREADY_HEALTHY";
    case "no-change":
      return "ALREADY_HEALTHY";
    case "no-repair-plans":
      return "SKIPPED";
    default:
      return "INEFFECTIVE";
  }
}

function uniqueIds(values: readonly string[] | readonly Issue[] | undefined): string[] {
  const ids = (values ?? []).map((value) => (typeof value === "string" ? value : value.id));
  return Array.from(new Set(ids.filter(Boolean))) as string[];
}

import type { Context } from "../core/Context.js";
import type { Issue } from "../core/Issue.js";
import type { Diagnosis } from "../diagnostic/Diagnosis.js";
import type { HealthSummary, HealthGrade, HealthStatus } from "./HealthSummary.js";
import type { IEngine } from "../core/IEngine.js";
import { reasonToStatus } from "../repair/RepairLifecycle.js";

interface SeverityCounts {
  critical: number;
  error: number;
  warning: number;
  info: number;
}

export class HealthEngine implements IEngine {
  public readonly name = "HealthEngine";

  async run(context: Context): Promise<void> {
    const issues = context.getIssues();
    const diagnoses = context.diagnosis ?? [];
    const diagnosisConfidence = diagnoses.length > 0 ? Math.max(...diagnoses.map((d) => d.confidence ?? 0)) : 0;
    const counts = this.countBySeverity(issues);
    const repairPlans = context.repairPlans ?? [];
    const rootCauseCount = context.rootCauses?.length ?? 0;
    const verificationPassed = Boolean(
      context.verification &&
        typeof context.verification === "object" &&
        "passed" in context.verification &&
        (context.verification as { passed: boolean }).passed
    );
    const repairStatus = reasonToStatus(context.repairLoop?.reason);

    const score = this.calculateScore(counts, diagnosisConfidence, rootCauseCount, repairPlans.length, verificationPassed, repairStatus);
    const grade = this.determineGrade(score);
    const status = this.determineStatus(score);
    const recommendation = this.buildRecommendation(score, counts, diagnoses, repairPlans.length, verificationPassed);

    context.health = {
      score,
      grade,
      status,
      recommendation,
      critical: counts.critical,
      error: counts.error,
      warning: counts.warning,
      info: counts.info,
      autoRepairAvailable: repairPlans.some((plan) => plan.steps.some((step) => step.automatic)),
      diagnosisConfidence,
    };
  }

  private countBySeverity(issues: readonly Issue[]): SeverityCounts {
    return issues.reduce(
      (acc, issue) => {
        switch (issue.severity.toLowerCase()) {
          case "critical":
            acc.critical += 1;
            break;
          case "error":
            acc.error += 1;
            break;
          case "warning":
            acc.warning += 1;
            break;
          default:
            acc.info += 1;
            break;
        }
        return acc;
      },
      { critical: 0, error: 0, warning: 0, info: 0 }
    );
  }

  private calculateScore(
    counts: SeverityCounts,
    diagnosisConfidence: number,
    rootCauseCount: number,
    repairPlanCount: number,
    verificationPassed: boolean,
    repairStatus: string
  ): number {
    let score = 100;
    score -= counts.critical * 20;
    score -= counts.error * 10;
    score -= counts.warning * 5;

    if (diagnosisConfidence > 0) {
      score += Math.min(20, Math.round(diagnosisConfidence / 10));
    }

    if (rootCauseCount > 0) {
      const coverageRatio = repairPlanCount / rootCauseCount;
      score += Math.min(20, Math.round(coverageRatio * 10));
    }

    if (verificationPassed) {
      score += 10;
    }

    if (repairStatus === "PARTIALLY_RESOLVED") {
      score -= 5;
    } else if (repairStatus === "FAILED" || repairStatus === "INEFFECTIVE") {
      score -= 10;
    }

    return Math.max(0, Math.min(100, score));
  }

  private buildRecommendation(
    score: number,
    counts: SeverityCounts,
    diagnoses: readonly Diagnosis[],
    repairPlanCount: number,
    verificationPassed: boolean
  ): string {
    if (score >= 90) {
      return "Excellent health. Keep the diagnosis, repair coverage, and verification status aligned.";
    }

    const pieces: string[] = [];

    if (counts.critical > 0 || counts.error > 0 || counts.warning > 0) {
      pieces.push("Resolve remaining critical and error issues first.");
    }

    if (diagnoses.length === 0) {
      pieces.push("Add diagnosis entries for detected issues.");
    }

    if (repairPlanCount === 0) {
      pieces.push("Create repair plans for identified root causes.");
    }

    if (!verificationPassed) {
      pieces.push("Verify the current repair and diagnosis results.");
    }

    if (pieces.length === 0) {
      return "Improve repair coverage and verification for a stronger health score.";
    }

    return pieces.join(" ");
  }

  private determineGrade(score: number): HealthGrade {
    if (score >= 90) return "A";
    if (score >= 80) return "B";
    if (score >= 70) return "C";
    if (score >= 60) return "D";
    return "E";
  }

  private determineStatus(score: number): HealthStatus {
    if (score >= 90) return "Excellent";
    if (score >= 80) return "Good";
    if (score >= 70) return "Fair";
    if (score >= 60) return "Poor";
    return "Critical";
  }
}

import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import type { Issue } from "../core/Issue.js";
import type { Diagnosis } from "../diagnostic/Diagnosis.js";
// RepairPlan type is inferred from planner output and not required here
import type { RootCause } from "../rootcause/RootCause.js";
import { HealthEngine } from "../health/HealthEngine.js";
import type { HealthSummary } from "../health/HealthSummary.js";
import { deriveRepairLifecycleState, reasonToStatus, statusToLoopReason } from "../repair/RepairLifecycle.js";

export interface VerificationCheck {
  name: string;
  passed: boolean;
  reason: string;
  details?: Record<string, unknown>;
}

export interface VerificationResult {
  passed: boolean;
  checks: VerificationCheck[];
  reasons: string[];
}

export class VerificationEngine implements IEngine {
  public readonly name = "VerificationEngine";

  async run(context: Context): Promise<void> {
    const result = this.verifyAll(context);
    context.verification = result;

    const healthEngine = new HealthEngine();
    await healthEngine.run(context);
  }

  private verifyAll(context: Context): VerificationResult {
    const checks = [
      this.verifyDiagnosis(context),
      this.verifyRepairPlan(context),
      this.verifyIssueConsistency(context),
      this.verifyRepairOutcome(context),
      this.verifyHealthScore(context),
    ];

    const reasons = checks.filter((check) => !check.passed).map((check) => check.reason);
    return {
      passed: reasons.length === 0,
      checks,
      reasons,
    };
  }

  private verifyDiagnosis(context: Context): VerificationCheck {
    const issues = context.getIssues();
    const diagnosis = context.diagnosis ?? [];

    if (issues.length === 0 && diagnosis.length === 0) {
      return {
        name: "diagnosis",
        passed: true,
        reason: "No issues were found, and the diagnosis list is empty.",
      };
    }

    if (issues.length > 0 && diagnosis.length === 0) {
      return {
        name: "diagnosis",
        passed: false,
        reason: "Diagnosis is missing while issues were detected.",
      };
    }

    const issueIds = new Set(issues.map((issue) => issue.id));
    const invalid = diagnosis.filter((entry) => !issueIds.has(entry.id)).map((entry) => entry.id);
    if (invalid.length > 0) {
      return {
        name: "diagnosis",
        passed: false,
        reason: `Diagnosis contains references to unknown issues: ${invalid.join(", ")}`,
        details: { unknownIssueIds: invalid },
      };
    }

    const duplicateIds = diagnosis.length !== new Set(diagnosis.map((entry) => entry.id)).size;
    if (duplicateIds) {
      return {
        name: "diagnosis",
        passed: false,
        reason: "Duplicate diagnosis identifiers were detected.",
      };
    }

    return {
      name: "diagnosis",
      passed: true,
      reason: "Diagnosis entries are consistent with detected issues.",
    };
  }

  private verifyRepairPlan(context: Context): VerificationCheck {
    const rootCauses = context.rootCauses ?? [];
    const repairPlans = context.repairPlans ?? [];

    if (rootCauses.length === 0 && repairPlans.length === 0) {
      return {
        name: "repairPlan",
        passed: true,
        reason: "No root causes were identified and no repair plans are required.",
      };
    }

    if (rootCauses.length > 0 && repairPlans.length === 0) {
      return {
        name: "repairPlan",
        passed: false,
        reason: "Repair plans are missing for identified root causes.",
      };
    }

    const rootCauseIds = new Set(rootCauses.map((cause) => cause.id));
    const invalidPlans = repairPlans.filter((plan) => !rootCauseIds.has(plan.rootCauseId)).map((plan) => plan.id);
    if (invalidPlans.length > 0) {
      return {
        name: "repairPlan",
        passed: false,
        reason: `Some repair plans reference unknown root cause ids: ${invalidPlans.join(", ")}`,
        details: { invalidRepairPlanIds: invalidPlans },
      };
    }

    if (repairPlans.length !== rootCauses.length) {
      return {
        name: "repairPlan",
        passed: false,
        reason: "Expected one repair plan for each root cause, but the counts differ.",
        details: { rootCauseCount: rootCauses.length, repairPlanCount: repairPlans.length },
      };
    }

    const emptySteps = repairPlans.filter((plan) => !plan.steps || plan.steps.length === 0).map((plan) => plan.id);
    if (emptySteps.length > 0) {
      return {
        name: "repairPlan",
        passed: false,
        reason: `Some repair plans have no steps: ${emptySteps.join(", ")}`,
        details: { emptyStepPlanIds: emptySteps },
      };
    }

    return {
      name: "repairPlan",
      passed: true,
      reason: "Repair plans are consistent with identified root causes.",
    };
  }

  private verifyIssueConsistency(context: Context): VerificationCheck {
    const issues = context.getIssues();
    const diagnosis = context.diagnosis ?? [];
    const rootCauses = context.rootCauses ?? [];
    const issueIds = new Set<string>();
    const duplicateIssueIds = new Set<string>();

    for (const issue of issues) {
      if (!issue.id || !issue.message) {
        return {
          name: "issueConsistency",
          passed: false,
          reason: "Every issue must have a non-empty id and message.",
        };
      }
      if (issueIds.has(issue.id)) {
        duplicateIssueIds.add(issue.id);
      }
      issueIds.add(issue.id);
    }

    if (duplicateIssueIds.size > 0) {
      return {
        name: "issueConsistency",
        passed: false,
        reason: `Duplicate issue ids detected: ${Array.from(duplicateIssueIds).join(", ")}`,
      };
    }

    if (diagnosis.length > 0) {
      const diagnosisIds = diagnosis.map((entry) => entry.id);
      const missing = diagnosisIds.filter((id) => !issueIds.has(id));
      if (missing.length > 0) {
        return {
          name: "issueConsistency",
          passed: false,
          reason: `Diagnosis references issue ids that are not present: ${missing.join(", ")}`,
          details: { missingIssueIds: missing },
        };
      }
    }

    if (rootCauses.length > 0) {
      if (issueIds.size === 0) {
        return {
          name: "issueConsistency",
          passed: true,
          reason: "No active issues remain; historical root cause evidence is not relevant.",
        };
      }

      const evidenceIds = new Set(rootCauses.flatMap((rootCause) => rootCause.evidence.map((issue) => issue.id)));
      const invalidEvidence = Array.from(evidenceIds).filter((id) => !issueIds.has(id));
      if (invalidEvidence.length > 0) {
        return {
          name: "issueConsistency",
          passed: false,
          reason: `Root cause evidence refers to unknown issue ids: ${invalidEvidence.join(", ")}`,
          details: { invalidEvidenceIds: invalidEvidence },
        };
      }
    }

    return {
      name: "issueConsistency",
      passed: true,
      reason: "Issue metadata and references are consistent.",
    };
  }

  private verifyRepairOutcome(context: Context): VerificationCheck {
    const repairLoop = context.repairLoop;
    const currentIssueCount = context.getIssues().length;
    const beforeIssueCount = context.repairSummary?.beforeIssueCount ?? context.repairSummary?.beforeIssueIds?.length ?? currentIssueCount;
    const afterIssueCount = context.repairSummary?.afterIssueCount ?? currentIssueCount;
    const repairStatus = reasonToStatus(repairLoop?.reason);

    if (!repairLoop || repairLoop.reason === "started") {
      return {
        name: "repairOutcome",
        passed: true,
        reason: "No repair outcome was recorded yet.",
      };
    }

    if (repairStatus === "ALREADY_HEALTHY") {
      if (currentIssueCount > 0) {
        return {
          name: "repairOutcome",
          passed: false,
          reason: `Repair reported already healthy but the current issue state still contains ${currentIssueCount} unresolved issue(s).`,
          details: { beforeIssueCount, afterIssueCount, currentIssueCount, reason: repairLoop.reason },
        };
      }

      return {
        name: "repairOutcome",
        passed: true,
        reason: "No repair was required because the issue state was already healthy.",
      };
    }

    if (repairStatus === "RESOLVED") {
      if (currentIssueCount > 0) {
        return {
          name: "repairOutcome",
          passed: false,
          reason: `Repair reported resolved but the current issue state still contains ${currentIssueCount} unresolved issue(s).`,
          details: { beforeIssueCount, afterIssueCount, currentIssueCount, reason: repairLoop.reason },
        };
      }

      if (beforeIssueCount > 0 && afterIssueCount > 0 && afterIssueCount < beforeIssueCount) {
        return {
          name: "repairOutcome",
          passed: false,
          reason: `Repair partially resolved the issue state: before=${beforeIssueCount}, after=${afterIssueCount}.`,
          details: { beforeIssueCount, afterIssueCount, currentIssueCount, reason: repairLoop.reason },
        };
      }

      return {
        name: "repairOutcome",
        passed: true,
        reason: "Repair outcome indicates the targeted issue was resolved.",
      };
    }

    if (repairStatus === "PARTIALLY_RESOLVED") {
      return {
        name: "repairOutcome",
        passed: false,
        reason: `Repair partially resolved the issue state: before=${beforeIssueCount}, after=${afterIssueCount}.`,
        details: { beforeIssueCount, afterIssueCount, currentIssueCount, reason: repairLoop.reason },
      };
    }

    if (beforeIssueCount > 0 && afterIssueCount >= beforeIssueCount && (repairStatus === "INEFFECTIVE" || repairStatus === "FAILED" || repairStatus === "SKIPPED" || repairLoop.reason === "no-change" || repairLoop.reason === "no-repair-needed")) {
      return {
        name: "repairOutcome",
        passed: false,
        reason: `Repair did not improve the issue state: before=${beforeIssueCount}, after=${afterIssueCount}.`,
        details: { beforeIssueCount, afterIssueCount, currentIssueCount, reason: repairLoop.reason },
      };
    }

    return {
        name: "repairOutcome",
        passed: true,
        reason: "Repair outcome is consistent with the current issue state.",
      };
  }

  private verifyHealthScore(context: Context): VerificationCheck {
    const health = context.health;
    const issues = context.getIssues();
    const diagnosis = context.diagnosis ?? [];
    const repairPlans = context.repairPlans ?? [];
    const rootCauses = context.rootCauses ?? [];

    const counts = this.countBySeverity(issues);
    const diagnosisConfidence = diagnosis.length > 0 ? Math.max(...diagnosis.map((d) => d.confidence ?? 0)) : 0;
    const verificationPassed = reasonToStatus(context.repairLoop?.reason) === "RESOLVED" || reasonToStatus(context.repairLoop?.reason) === "ALREADY_HEALTHY";
    const expectedScore = this.calculateScore(counts, diagnosisConfidence, rootCauses.length, repairPlans.length, verificationPassed);
    const expectedGrade = this.determineGrade(expectedScore);
    const expectedStatus = this.determineStatus(expectedScore);

    if (!health) {
      return {
        name: "healthScore",
        passed: true,
        reason: "Health summary will be generated from the current diagnostics and repair state.",
        details: { expectedScore, expectedGrade, expectedStatus },
      };
    }

    if (health.score !== expectedScore) {
      return {
        name: "healthScore",
        passed: false,
        reason: `Health score mismatch: expected ${expectedScore}, got ${health.score}.`,
        details: { expectedScore, actualScore: health.score },
      };
    }

    if (health.grade !== expectedGrade) {
      return {
        name: "healthScore",
        passed: false,
        reason: `Health grade mismatch: expected ${expectedGrade}, got ${health.grade}.`,
        details: { expectedGrade, actualGrade: health.grade },
      };
    }

    if (health.status !== expectedStatus) {
      return {
        name: "healthScore",
        passed: false,
        reason: `Health status mismatch: expected ${expectedStatus}, got ${health.status}.`,
        details: { expectedStatus, actualStatus: health.status },
      };
    }

    return {
      name: "healthScore",
      passed: true,
      reason: "Health score and summary are consistent with diagnostics and repair state.",
    };
  }

  private countBySeverity(issues: readonly Issue[]): {
    critical: number;
    error: number;
    warning: number;
    info: number;
  } {
    return issues.reduce(
      (counts, issue) => {
        switch (issue.severity.toLowerCase()) {
          case "critical":
            counts.critical += 1;
            break;
          case "error":
            counts.error += 1;
            break;
          case "warning":
            counts.warning += 1;
            break;
          default:
            counts.info += 1;
            break;
        }
        return counts;
      },
      { critical: 0, error: 0, warning: 0, info: 0 }
    );
  }

  private calculateScore(
    counts: { critical: number; error: number; warning: number; info: number },
    diagnosisConfidence: number,
    rootCauseCount: number,
    repairPlanCount: number,
    verificationPassed: boolean
  ): number {
    let score = 100;
    score -= counts.critical * 20;
    score -= counts.error * 10;
    score -= counts.warning * 5;

    if (diagnosisConfidence > 0) {
      score += Math.min(20, Math.round(diagnosisConfidence / 10));
    }

    if (rootCauseCount > 0) {
      const coverageRatio = repairPlanCount / rootCauseCount;
      score += Math.min(20, Math.round(coverageRatio * 10));
    }

    if (verificationPassed) {
      score += 10;
    }

    return Math.max(0, Math.min(100, score));
  }

  private determineGrade(score: number): string {
    if (score >= 90) return "A";
    if (score >= 80) return "B";
    if (score >= 70) return "C";
    if (score >= 60) return "D";
    return "E";
  }

  private determineStatus(score: number): string {
    if (score >= 90) return "Excellent";
    if (score >= 80) return "Good";
    if (score >= 70) return "Fair";
    if (score >= 60) return "Poor";
    return "Critical";
  }
}

