export interface BuildVerificationResult {
  compilePassed: boolean;
  testsPassed: boolean;
  verificationPassed: boolean;
  summary: string;
}

export class BuildVerifier {
  constructor(private readonly verificationEngine: VerificationEngine = new VerificationEngine()) {}

  async verify(context: Context, compileResult: CompileResult): Promise<BuildVerificationResult> {
    await this.verificationEngine.run(context);
    const verification = context.verification as { passed?: boolean } | undefined;
    const testsPassed = this.readTestsPassed(context);
    const buildPassed = compileResult.succeeded && testsPassed && (verification?.passed ?? false);
    return {
      compilePassed: compileResult.succeeded,
      testsPassed,
      verificationPassed: verification?.passed ?? false,
      summary: buildPassed ? "Build verified" : "Build verification failed",
    };
  }

  private readTestsPassed(context: Context): boolean {
    const testMetrics = (context.metadata as { test?: TestMetrics } | undefined)?.test;
    if (!testMetrics) {
      return false;
    }

    const exitCodes = [testMetrics.unitExitCode, testMetrics.integrationExitCode];
    return exitCodes.every((exitCode) => exitCode === 0);
  }
}

import type { Context } from "../core/Context.js";
import { EventBus, type EngineEvent } from "./EventBus.js";

export interface DashboardSnapshot {
  runningEngines: string[];
  waitingEngines: string[];
  completedEngines: string[];
  failedEngines: string[];
  retryCount: number;
  elapsedTimeMs: number;
  etaMs: number;
  currentArtifact: string;
  currentRepairLoop: number;
}

export class DashboardRuntime {
  private readonly snapshot: DashboardSnapshot;

  constructor(private readonly context: Context, private readonly eventBus: EventBus) {
    this.snapshot = {
      runningEngines: [],
      waitingEngines: [],
      completedEngines: [],
      failedEngines: [],
      retryCount: 0,
      elapsedTimeMs: 0,
      etaMs: 0,
      currentArtifact: "",
      currentRepairLoop: 0,
    };

    this.eventBus.subscribe((event) => this.apply(event));
  }

  getSnapshot(): DashboardSnapshot {
    return { ...this.snapshot };
  }

  private apply(event: EngineEvent): void {
    if (event.type === "EngineStarted") {
      this.snapshot.runningEngines = [...new Set([...this.snapshot.runningEngines, event.engine ?? ""])]
        .filter(Boolean);
    }

    if (event.type === "EngineFinished") {
      this.snapshot.completedEngines = [...new Set([...this.snapshot.completedEngines, event.engine ?? ""])]
        .filter(Boolean);
      this.snapshot.runningEngines = this.snapshot.runningEngines.filter((name) => name !== event.engine);
    }

    if (event.type === "EngineFailed") {
      this.snapshot.failedEngines = [...new Set([...this.snapshot.failedEngines, event.engine ?? ""])]
        .filter(Boolean);
      this.snapshot.runningEngines = this.snapshot.runningEngines.filter((name) => name !== event.engine);
    }
  }
}

import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";

export interface FailureReport {
  category: "typescript" | "eslint" | "dependency" | "runtime" | "test" | "infrastructure";
  severity: "low" | "medium" | "high";
  errors: string[];
}

export class FailureClassifierEngine implements IEngine {
  public readonly name = "FailureClassifierEngine";

  async run(context: Context): Promise<void> {
    const buildLoop = (context.metadata as Record<string, unknown>).buildLoop as {
      report?: {
        compilerResult?: { diagnostics?: string[] };
      };
    } | undefined;
    const diagnostics = buildLoop?.report?.compilerResult?.diagnostics ?? [];
    const errors = diagnostics.join("\n");

    let category: FailureReport["category"] = "typescript";
    let severity: FailureReport["severity"] = "medium";

    if (/eslint|lint/i.test(errors)) {
      category = "eslint";
    } else if (/cannot find module|missing dependency|ERR_MODULE_NOT_FOUND|enoent/i.test(errors)) {
      category = "dependency";
    } else if (/timeout|referenceerror|typeerror|runtime/i.test(errors)) {
      category = "runtime";
    } else if (/test|jest|vitest/i.test(errors)) {
      category = "test";
    } else if (/docker|network|infrastructure/i.test(errors)) {
      category = "infrastructure";
    }

    if (category === "typescript" || category === "runtime") {
      severity = "high";
    } else if (category === "dependency") {
      severity = "medium";
    }

    const report: FailureReport = { category, severity, errors: diagnostics };
    context.metadata = {
      ...context.metadata,
      failureReport: report,
    } as typeof context.metadata & { failureReport?: FailureReport };
  }
}

