import type { Context } from "../core/Context.js";
import { AgentPlanner } from "./AgentPlanner.js";
import { ExecutionQueue } from "./ExecutionQueue.js";
import { TaskExecutor } from "./TaskExecutor.js";
import { GoalManager } from "./GoalManager.js";
import { AgentMemory } from "./AgentMemory.js";
import { ExecutionHistory } from "./ExecutionHistory.js";

export class AgentCoordinator {
  constructor(
    private readonly root: string = process.cwd(),
    private readonly planner: AgentPlanner = new AgentPlanner(root),
    private readonly queue: ExecutionQueue = new ExecutionQueue(),
    private readonly executor: TaskExecutor = new TaskExecutor(root),
    private readonly goals: GoalManager = new GoalManager(root),
    private readonly memory: AgentMemory = new AgentMemory(root),
    private readonly history: ExecutionHistory = new ExecutionHistory(root)
  ) {}

  async run(goal: string, context: Context): Promise<{ goalId: string; status: string }> {
    const createdGoal = await this.goals.createGoal(goal);
    const plan = await this.planner.planGoal(goal, context);
    plan.tasks.forEach((task) => this.queue.enqueue(task));

    while (this.queue.getProgress().pending > 0) {
      const task = this.queue.dequeue();
      if (!task) {
        break;
      }
      await this.executor.execute(task, createdGoal.id);
    }

    await this.goals.updateGoal(createdGoal.id, { status: "completed" });
    await this.memory.record({ goalId: createdGoal.id, taskId: "summary", status: "completed", summary: `Completed ${goal}` });
    this.history.push({ id: `summary-${createdGoal.id}`, goalId: createdGoal.id, taskId: "summary", status: "completed", summary: `Completed ${goal}`, timestamp: new Date().toISOString() });

    return { goalId: createdGoal.id, status: "completed" };
  }
}

import type { AgentTask } from "./ExecutionContext.js";

export interface ExecutionQueueProgress {
  completed: number;
  total: number;
  pending: number;
}

export class ExecutionQueue {
  private readonly pending: AgentTask[] = [];
  private readonly completed: AgentTask[] = [];

  enqueue(task: AgentTask): void {
    this.pending.push(task);
  }

  dequeue(): AgentTask | undefined {
    const next = this.pending.shift();
    if (next) {
      this.completed.push(next);
    }
    return next;
  }

  getProgress(): ExecutionQueueProgress {
    return {
      completed: this.completed.length,
      total: this.completed.length + this.pending.length,
      pending: this.pending.length,
    };
  }
}

import type { AgentTask } from "./ExecutionContext.js";
import { AgentDecisionEngine } from "./AgentDecisionEngine.js";
import { AgentMemory } from "./AgentMemory.js";
import { ExecutionHistory } from "./ExecutionHistory.js";
import { GoalManager } from "./GoalManager.js";

export class TaskExecutor {
  constructor(
    private readonly root: string = process.cwd(),
    private readonly decisionEngine: AgentDecisionEngine = new AgentDecisionEngine(),
    private readonly memory: AgentMemory = new AgentMemory(root),
    private readonly history: ExecutionHistory = new ExecutionHistory(root),
    private readonly goals: GoalManager = new GoalManager(root)
  ) {}

  async execute(task: AgentTask, goalId: string): Promise<AgentTask> {
    task.status = "running";
    task.attempts += 1;
    await this.memory.record({ goalId, taskId: task.id, status: "running", summary: task.title });
    this.history.push({ id: `${task.id}-${task.attempts}`, goalId, taskId: task.id, status: "running", summary: task.title, timestamp: new Date().toISOString() });

    try {
      task.status = "completed";
      task.summary = `executed ${task.title}`;
      await this.memory.record({ goalId, taskId: task.id, status: "completed", summary: task.summary ?? task.title });
      this.history.push({ id: `${task.id}-${task.attempts}-done`, goalId, taskId: task.id, status: "completed", summary: task.summary ?? task.title, timestamp: new Date().toISOString() });
      return task;
    } catch (error) {
      task.status = "failed";
      task.error = error instanceof Error ? error.message : String(error);
      const decision = this.decisionEngine.decide({ status: "failed", attempts: task.attempts, error: task.error }, { goal: goalId });
      await this.memory.record({ goalId, taskId: task.id, status: "failed", summary: decision.reason, error: task.error });
      this.history.push({ id: `${task.id}-${task.attempts}-failed`, goalId, taskId: task.id, status: "failed", summary: decision.reason, error: task.error, timestamp: new Date().toISOString() });
      return task;
    }
  }
}

export interface DecisionInput {
  status: "failed" | "completed" | "blocked";
  attempts: number;
  error?: string;
}

export interface DecisionOutput {
  action: "retry" | "escalate" | "continue";
  reason: string;
}

export class AgentDecisionEngine {
  decide(input: DecisionInput, context: { goal: string }): DecisionOutput {
    if (input.status === "failed" && input.attempts < 3) {
      return { action: "retry", reason: "retrying after a failed execution" };
    }

    if (input.status === "blocked") {
      return { action: "escalate", reason: `blocking the goal ${context.goal}` };
    }

    return { action: "continue", reason: `continuing the goal ${context.goal}` };
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { AgentExecutionEntry } from "./ExecutionContext.js";

export interface AgentMemoryStore {
  entries: AgentExecutionEntry[];
}

export interface AgentMemoryRecord {
  goalId: string;
  taskId: string;
  status: AgentExecutionEntry["status"];
  summary: string;
  error?: string;
}

export class AgentMemory {
  constructor(private readonly root: string = process.cwd()) {}

  async record(entry: AgentMemoryRecord): Promise<AgentExecutionEntry> {
    const store = await this.load();
    const item: AgentExecutionEntry = {
      id: `entry-${store.entries.length + 1}`,
      timestamp: new Date().toISOString(),
      ...entry,
    };
    store.entries.push(item);
    this.entries = store.entries;
    await this.persist(store);
    return item;
  }

  recall(goalId: string): AgentExecutionEntry[] {
    return [...this.entries].filter((entry) => entry.goalId === goalId);
  }

  private entries: AgentExecutionEntry[] = [];

  private async load(): Promise<AgentMemoryStore> {
    const filePath = this.getFilePath();
    try {
      const content = await fs.readFile(filePath, "utf8");
      const parsed = JSON.parse(content) as AgentMemoryStore;
      this.entries = parsed.entries;
      return parsed;
    } catch {
      this.entries = [];
      return { entries: [] };
    }
  }

  private async persist(store: AgentMemoryStore): Promise<void> {
    const filePath = this.getFilePath();
    await fs.mkdir(path.dirname(filePath), { recursive: true });
    await fs.writeFile(filePath, JSON.stringify(store, null, 2), "utf8");
  }

  private getFilePath(): string {
    return path.join(this.root, "knowledge", "agent-history.json");
  }
}

