export class AgentOrchestrationEngine implements IEngine {
  public readonly name = "AgentOrchestrationEngine";

  constructor(private readonly coordinator: AgentCoordinator = new AgentCoordinator()) {}

  async run(context: Context): Promise<void> {
    const goal = this.getGoal(context);
    const result = await this.coordinator.run(goal, context);
    const report: AgentExecutionReport = {
      goal,
      status: result.status,
      goalId: result.goalId,
    };

    const reportPath = path.join(context.projectRoot, "knowledge", "execution-report.json");
    await fs.mkdir(path.dirname(reportPath), { recursive: true });
    await fs.writeFile(reportPath, JSON.stringify(report, null, 2), "utf8");

    context.metadata = {
      ...context.metadata,
      agentRuntime: report,
    } as typeof context.metadata & { agentRuntime?: AgentExecutionReport };
  }

  private getGoal(context: Context): string {
    const candidate = (context.metadata as Record<string, unknown> | undefined)?.agentGoal;
    return typeof candidate === "string" && candidate.trim().length > 0
      ? candidate
      : `Autonomous coding task for ${context.projectName}`;
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { EventBus } from "../doctor/EventBus.js";
import { SwarmAgentRuntime } from "./SwarmAgent.js";
import { SwarmCoordinator } from "./SwarmCoordinator.js";
import type { SwarmAgent, SwarmMessage, SwarmTask, SwarmAgentName } from "./SwarmTypes.js";

const AGENTS: Array<{ name: SwarmAgentName; role: string }> = [
  { name: "ArchitectAgent", role: "architecture" },
  { name: "BackendAgent", role: "backend" },
  { name: "FrontendAgent", role: "frontend" },
  { name: "DatabaseAgent", role: "database" },
  { name: "APIAgent", role: "api" },
  { name: "SecurityAgent", role: "security" },
  { name: "TestingAgent", role: "testing" },
  { name: "RepairAgent", role: "repair" },
  { name: "BenchmarkAgent", role: "benchmark" },
  { name: "DocumentationAgent", role: "documentation" },
];

export class SwarmCoordinatorEngine implements IEngine {
  public readonly name = "SwarmCoordinatorEngine";

  constructor(
    private readonly eventBus: EventBus = new EventBus(),
    private readonly coordinator: SwarmCoordinator = new SwarmCoordinator()
  ) {}

  async run(context: Context): Promise<void> {
    const runtimeByAgent = new Map<SwarmAgentName, SwarmAgentRuntime>();
    const agents: SwarmAgent[] = [];
    const tasks: SwarmTask[] = [];
    const messages: SwarmMessage[] = [];
    const history: Array<{ type: string; agent: string; taskId?: string }> = [];

    for (const agentInfo of AGENTS) {
      const runtime = new SwarmAgentRuntime(agentInfo.name, this.eventBus);
      runtimeByAgent.set(agentInfo.name, runtime);
      agents.push({ name: agentInfo.name, queue: [], active: true, role: agentInfo.role });
    }

    for (let index = 0; index < AGENTS.length; index += 1) {
      const agentInfo = AGENTS[index];
      const task: SwarmTask = {
        id: `task-${index + 1}`,
        title: `${agentInfo.name} task`,
        description: `Task for ${agentInfo.name}`,
        priority: AGENTS.length - index,
        agent: agentInfo.name,
        status: "queued",
        attempts: 0,
      };
      tasks.push(task);
      runtimeByAgent.get(agentInfo.name)?.enqueue(task);
      history.push({ type: "queued", agent: agentInfo.name, taskId: task.id });
    }

    const orderedTasks = this.coordinator.resolveConflicts(tasks);
    for (const task of orderedTasks) {
      const runtime = runtimeByAgent.get(task.agent);
      if (!runtime) {
        continue;
      }
      const completed = runtime.process();
      for (const item of completed) {
        task.status = "completed";
        history.push({ type: "completed", agent: task.agent, taskId: item.id });
        messages.push({ from: task.agent, to: task.agent, type: "status", payload: `completed ${item.id}`, timestamp: new Date().toISOString() });
      }
    }

    const swarm = {
      agents,
      tasks: orderedTasks,
      messages,
    };

    const metrics = {
      total: orderedTasks.length,
      completed: orderedTasks.filter((task) => task.status === "completed").length,
      blocked: 0,
    };

    const knowledgePath = path.join(context.projectRoot, "knowledge");
    await fs.mkdir(knowledgePath, { recursive: true });
    await fs.writeFile(path.join(knowledgePath, "swarm.json"), JSON.stringify(swarm, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgePath, "swarm-history.json"), JSON.stringify({ events: history }, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgePath, "swarm-metrics.json"), JSON.stringify(metrics, null, 2), "utf8");

    context.metadata = {
      ...context.metadata,
      swarm: swarm,
      swarmHistory: { events: history },
      swarmMetrics: metrics,
    } as typeof context.metadata & { swarm?: typeof swarm; swarmHistory?: { events: typeof history }; swarmMetrics?: typeof metrics };
  }
}

import type { SwarmAgentName, SwarmTask } from "./SwarmTypes.js";
import { EventBus } from "../doctor/EventBus.js";

export class SwarmAgentRuntime {
  constructor(
    private readonly name: SwarmAgentName,
    private readonly eventBus: EventBus = new EventBus()
  ) {}

  enqueue(task: SwarmTask): void {
    this.queue.push(task);
    this.eventBus.emit({ type: "SwarmTaskQueued", timestamp: new Date().toISOString(), stage: this.name, engine: this.name, details: { taskId: task.id } });
  }

  process(): SwarmTask[] {
    const completed = this.queue.splice(0, this.queue.length);
    return completed.map((task) => ({ ...task, status: "completed" as const }));
  }

  getQueue(): SwarmTask[] {
    return [...this.queue];
  }

  private readonly queue: SwarmTask[] = [];
}

import type { SwarmTask } from "./SwarmTypes.js";

export class SwarmCoordinator {
  resolveConflicts(tasks: SwarmTask[]): SwarmTask[] {
    return [...tasks].sort((left, right) => {
      if (left.priority !== right.priority) {
        return right.priority - left.priority;
      }
      return left.id.localeCompare(right.id);
    });
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { BenchmarkEngine } from "../benchmark/BenchmarkEngine.js";
import { KnowledgeGraphEngine } from "../doctor/KnowledgeGraphEngine.js";
import type { EvolutionProposal, EvolutionRecord, ConfidencePoint, SelfEvolutionSnapshot } from "./SelfEvolutionTypes.js";

export class SelfEvolutionEngine implements IEngine {
  public readonly name = "SelfEvolutionEngine";

  async run(context: Context): Promise<void> {
    const previousProjects = await this.inspectPreviousProjects(context.projectRoot);
    const repeatedMistakes = this.detectRepeatedMistakes(previousProjects);
    const proposals = this.generateProposals(repeatedMistakes, context.projectName);
    const accepted = proposals.filter((proposal) => proposal.confidence >= 0.7);
    const rejected = proposals.filter((proposal) => proposal.confidence < 0.7);

    const evolutionRecord: EvolutionRecord = {
      id: `evolution-${Date.now()}`,
      project: context.projectName,
      summary: `Learned from ${previousProjects.length} previous projects`,
      proposals,
      timestamp: new Date().toISOString(),
    };

    const confidenceHistory: ConfidencePoint[] = [
      { timestamp: new Date().toISOString(), score: accepted.length / Math.max(1, proposals.length), reason: "proposal acceptance rate" },
    ];

    const snapshot: SelfEvolutionSnapshot = {
      evolution: [evolutionRecord],
      improvements: accepted,
      confidenceHistory,
      learning: {
        repeatedMistakes,
        acceptedImprovements: accepted.length,
        rejectedImprovements: rejected.length,
      },
    };

    const knowledgePath = path.join(context.projectRoot, "knowledge");
    await fs.mkdir(knowledgePath, { recursive: true });
    await fs.writeFile(path.join(knowledgePath, "evolution.json"), JSON.stringify(snapshot, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgePath, "improvements.json"), JSON.stringify({ improvements: accepted }, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgePath, "confidence-history.json"), JSON.stringify({ history: confidenceHistory }, null, 2), "utf8");
    await fs.writeFile(path.join(knowledgePath, "self-learning.json"), JSON.stringify(snapshot.learning, null, 2), "utf8");

    const benchmarkEngine = new BenchmarkEngine();
    await benchmarkEngine.run(context);

    const knowledgeGraphEngine = new KnowledgeGraphEngine();
    await knowledgeGraphEngine.run(context);

    context.metadata = {
      ...context.metadata,
      selfEvolution: snapshot,
    } as typeof context.metadata & { selfEvolution?: SelfEvolutionSnapshot };
  }

  private async inspectPreviousProjects(root: string): Promise<string[]> {
    const knowledgePath = path.join(root, "knowledge");
    try {
      const entries = await fs.readdir(knowledgePath);
      return entries.filter((entry) => entry.endsWith(".json"));
    } catch {
      return [];
    }
  }

  private detectRepeatedMistakes(previousProjects: string[]): string[] {
    if (previousProjects.length === 0) {
      return ["missing-validation"];
    }
    return previousProjects.slice(0, 3);
  }

  private generateProposals(repeatedMistakes: string[], projectName: string): EvolutionProposal[] {
    return repeatedMistakes.map((mistake, index) => ({
      id: `proposal-${index + 1}`,
      kind: index % 2 === 0 ? "repair-strategy" : "benchmark-threshold",
      summary: `Improve ${projectName} against ${mistake}`,
      details: `Propose a patch for ${mistake} without modifying production code directly`,
      confidence: 0.72 + index * 0.05,
      accepted: false,
    }));
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { AutonomousOrchestrator } from "../runtime/AutonomousOrchestrator.js";
import { EngineRegistry } from "../runtime/EngineRegistry.js";
import { ArchitectAgent } from "./ArchitectAgent.js";
import { BackendAgent } from "./BackendAgent.js";
import { FrontendAgent } from "./FrontendAgent.js";
import { DatabaseAgent } from "./DatabaseAgent.js";
import { QAAgent } from "./QAAgent.js";
import { RepairAgent } from "./RepairAgent.js";
import { SecurityAgent } from "./SecurityAgent.js";
import { PerformanceAgent } from "./PerformanceAgent.js";
import { DocumentationAgent } from "./DocumentationAgent.js";
import { DevOpsAgent } from "./DevOpsAgent.js";

export interface AgentMeshSnapshot {
  queue: string[];
  history: Array<{ agent: string; status: string; confidence: number }>;
  activeAgent?: string;
  progress: number;
  durationMs: number;
  confidence: number;
}

export class AgentMeshEngine implements IEngine {
  public readonly name = "AgentMeshEngine";

  constructor(private readonly orchestrator: AutonomousOrchestrator = new AutonomousOrchestrator(new EngineRegistry())) {}

  async run(context: Context): Promise<void> {
    const agents: IEngine[] = [
      new ArchitectAgent(),
      new BackendAgent(),
      new FrontendAgent(),
      new DatabaseAgent(),
      new QAAgent(),
      new RepairAgent(),
      new SecurityAgent(),
      new PerformanceAgent(),
      new DocumentationAgent(),
      new DevOpsAgent(),
    ];

    for (const agent of agents) {
      this.orchestrator.registerEngine(agent);
    }

    const startedAt = Date.now();
    const history: AgentMeshSnapshot["history"] = [];
    for (const agent of agents) {
      const confidence = 0.7 + Math.min(0.25, agents.indexOf(agent) * 0.02);
      try {
        await agent.run(context);
        history.push({ agent: agent.name, status: "completed", confidence });
      } catch (error) {
        history.push({ agent: agent.name, status: "failed", confidence: Math.max(0.1, confidence - 0.2) });
      }

      const mesh = (context.metadata as Record<string, unknown>).agentMesh as { history?: AgentMeshSnapshot["history"]; queue?: string[]; activeAgent?: string; progress?: number; durationMs?: number; confidence?: number } | undefined;
      const liveHistory = [...(mesh?.history ?? []), ...history];
      const snapshot: AgentMeshSnapshot = {
        queue: agents.map((item) => item.name),
        history: liveHistory,
        activeAgent: agent.name,
        progress: Math.round((history.length / Math.max(1, agents.length)) * 100),
        durationMs: Date.now() - startedAt,
        confidence: liveHistory.reduce((sum, item) => sum + item.confidence, 0) / Math.max(1, liveHistory.length),
      };

      context.metadata = {
        ...context.metadata,
        agentMesh: snapshot,
      } as typeof context.metadata & { agentMesh?: AgentMeshSnapshot };
    }

    const finalMesh = (context.metadata as Record<string, unknown>).agentMesh as AgentMeshSnapshot | undefined;
    const snapshot: AgentMeshSnapshot = {
      queue: agents.map((agent) => agent.name),
      history: finalMesh?.history ?? history,
      activeAgent: agents[agents.length - 1]?.name,
      progress: 100,
      durationMs: Date.now() - startedAt,
      confidence: (finalMesh?.history ?? history).reduce((sum, item) => sum + item.confidence, 0) / Math.max(1, (finalMesh?.history ?? history).length),
    };

    await fs.mkdir(path.join(context.projectRoot, "knowledge"), { recursive: true });
    await fs.writeFile(path.join(context.projectRoot, "knowledge", "agent-mesh.json"), JSON.stringify(snapshot, null, 2), "utf8");

    context.metadata = {
      ...context.metadata,
      agentMesh: snapshot,
    } as typeof context.metadata & { agentMesh?: AgentMeshSnapshot };
  }
}

